import React, { useState } from 'react'
import { View, Text, Switch } from 'react-native'
import { Global } from '../Common/Global'
import { ValueCheck } from '../CommonStyle/ComponentFunctions'
import { normalize } from '../CommonStyle/componentStyle'

export default function STimingSwitch(props) {
    const [refresh, setRefresh] = useState(0)
    const [data, setData] = useState(props.data)
    return (
        <View style={{ flexDirection: 'row' ,borderWidth: 0, marginTop:ValueCheck(props.type) ? 0 : 19,alignItems:'center',justifyContent:'center',marginHorizontal:5}}>
            {data.map((selectslot, k) => {
                return (
                    <View key={k} style={{alignItems:'center',justifyContent:'center'}}>
                        <Switch
                            trackColor={{ false: "#767577", true: Global.AppTheme.primary_color }}
                            thumbColor={"lightgrey"}
                            onChange={() => getSwitch(selectslot)}
                            value={selectslot.selected}
                        />
                        <Text style={{ color: 'black', fontWeight: 'bold', fontSize: normalize(10) }}>{selectslot.slotname}</Text>
                    </View>)
            })}
        </View>
    )

    function getSwitch(params) {
        data.map((item) => item.selected = false)
        params.selected = !params.selected
        props.callBack(params)
        setRefresh(refresh + 1)
    }
}

