import React, { useState } from 'react'
import { Defs, LinearGradient, Stop } from 'react-native-svg'
import { View, Dimensions, TouchableOpacity, Platform } from 'react-native';
import { LineChart, Grid, XAxis, YAxis } from 'react-native-svg-charts'
import { Circle, G, Line, Rect, Text } from 'react-native-svg'
// import CText from '../../CustomComponents/CText';
// import moment from 'moment'
// import SDatePickerNew from '../../StaticComponents/SDatePickerNew'
import { normalize } from '../../CommonStyle/componentStyle'
// import { ScrollView } from 'react-native';
import { ArrayCheck, isBNUL, ValueCheck } from '../../CommonStyle/ComponentFunctions';


export default function CLineChart(props) {

    const [index, setIndex] = useState(1)
    const [propsData, setPropsData] = useState(props.data)
    const [data, setData] = useState(isBNUL(propsData) ? (propsData).map(({ value }) => parseFloat(value)) : [])
    const axesSvg = { fontSize: normalize(11), fill: 'grey' };
    const verticalContentInset = { top: 5, bottom: 5 }
    const xAxisHeight = 30

    const Gradient = () => (
        <Defs key={'gradient'}>
            <LinearGradient id={'gradient'} x1={'0'} y={'0%'} x2={'100%'} y2={'0%'}>
                <Stop offset={'0%'} stopColor={'rgb(134, 65, 244)'} />
                <Stop offset={'100%'} stopColor={'rgb(66, 194, 244)'} />
            </LinearGradient>
        </Defs>
    )

    const Tooltip = ({ x, y }) => (

        propsData[index] != undefined ?
            <G
                x={10}
                key={'tooltip'}
                onPress={() => console.log('tooltip clicked')}
            >
                <G y={50}>
                    <Rect
                        height={normalize(30)}
                        width={normalize(70)}
                        stroke={'grey'}
                        fill={'white'}
                        ry={10}
                        rx={10}
                    />
                    <Text
                        x={75 / 2}
                        dy={normalize(10)}
                        alignmentBaseline={'middle'}
                        textAnchor={'middle'}
                        stroke={'rgb(134, 65, 244)'}
                    >
                        {`${data[index]}`}
                    </Text>

                    <Text
                        x={75 / 2}
                        dy={normalize(25)}
                        alignmentBaseline={'middle'}
                        textAnchor={'middle'}
                        stroke={'rgb(134, 65, 244)'}
                        fontSize={"7"}
                    >
                        {`${propsData[index].date}`}
                    </Text>
                </G>
                <G x={75 / 2}>
                    <Circle
                        cy={y(data[index])}
                        r={6}
                        stroke={'rgb(134, 65, 244)'}
                        strokeWidth={2}
                        fill={'white'}
                    />
                </G>
            </G> : null
    )

    const Decorator = ({ x, y, data }) => {
        return data.map((value, index) => (
            <Circle
                onPress={() => setIndex(index)}
                key={index}
                cx={x(index)}
                cy={y(value)}
                r={6}
                stroke={'rgb(134, 65, 244)'}
                fill={'white'}
            />
        ))
    }

    return (
        data != null && data != undefined && data.length > 0 ?
            <>
                <View style={{ alignItems: 'flex-start', borderWidth: 0, borderColor: 'green', backgroundColor: 'white' }}>
                    <View style={{ flexDirection: 'row', borderWidth: 0 }}>
                        <YAxis
                            data={data}
                            style={{ borderWidth: 0 }}
                            contentInset={verticalContentInset}
                            svg={axesSvg}
                        />
                        <View style={{ flex: 1, borderWidth: 0 }}>
                            <LineChart
                                style={{ height: normalize(150) }}
                                data={data}
                                contentInset={{ top: normalize(10), bottom: normalize(10), left: normalize(10), right: normalize(10) }}
                                svg={{
                                    strokeWidth: normalize(3),
                                    stroke: 'url(#gradient)',
                                }}
                            >
                                <Grid
                                    direction='HORIZONTAL'
                                // direction='VERTICAL'
                                />
                                <Gradient />
                                {/* <Tooltip /> */}
                                <Decorator />
                            </LineChart>
                        </View>
                    </View>
                    <XAxis
                        style={{ marginHorizontal: 0, height: normalize(55), borderWidth: 0, width: '100%' }}
                        data={propsData}
                        formatLabel={(value, index) => propsData[index].displayvalue}
                        contentInset={{ left: normalize(20), right: normalize(10),}}
                        svg={{ fontSize: normalize(7), fontWeight: 'bold', fill: 'black', translateY: normalize(15), rotation: normalize(75), originY: 0 }}
                    />
                </View>
            </>
            : null
    )
}


