import React, { useState, useEffect, useRef } from 'react';
import {
    View,
    Text,
    TouchableOpacity,
    Modal,
    FlatList,
    TextInput,
    StyleSheet,
    ActivityIndicator,
    Animated,
    Dimensions,
} from 'react-native';
import Icons from '../Common/Icons';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import { APIURL } from '../Common/apiConstants';

const { height: SCREEN_HEIGHT } = Dimensions.get('window');

const ModernMultiSelectDropdown = ({
    label,
    value = [], // Array of selected values (IDs)
    displayValue, // Optional: Override text to display in the box
    placeholder = 'Select...',
    options = [], // Static options
    api = null, // API endpoint to fetch options
    onChange, // Returns updated array of selected values
    icon = null,
    iconGroup = 'FontAwesome5',
    searchable = false,
    disabled = false,
    required = false,
    error = null,
    style,
    masterList = [], // Pass pre-fetched master list if available
}) => {
    const [visible, setVisible] = useState(false);
    const [data, setData] = useState(options);
    const [loading, setLoading] = useState(false);
    const [searchText, setSearchText] = useState('');
    const [filteredData, setFilteredData] = useState([]);
    const [loadedFromApi, setLoadedFromApi] = useState(false);

    // Animation for modal
    const slideAnim = useRef(new Animated.Value(SCREEN_HEIGHT)).current;

    useEffect(() => {
        if (visible) {
            if (masterList && masterList.length > 0) {
                const formatted = formatOptions(masterList);
                setData(formatted);
                setFilteredData(formatted);
                setLoadedFromApi(true);
            } else if (api && !loadedFromApi) {
                fetchData();
            } else if (!api) {
                // If static options change
                const formatted = formatOptions(options);
                setData(formatted);
                setFilteredData(formatted);
            }
            openModal();
        } else {
            closeModal();
        }
    }, [visible]);

    useEffect(() => {
        if (searchText) {
            const lower = searchText.toLowerCase();
            const filtered = data.filter(item =>
                item.label.toLowerCase().includes(lower)
            );
            setFilteredData(filtered);
        } else {
            setFilteredData(data);
        }
    }, [searchText, data]);

    const formatOptions = (rawOptions) => {
        return rawOptions.map(item => ({
            label: item.displayvalue || item.label || item.toString(),
            value: item.datavalue || item.value || item,
            icon: item.icon,
            iconColor: item.iconcolor,
            original: item
        }));
    };

    const fetchData = async () => {
        setLoading(true);
        try {
            const safeApi = api.replace(' ', '%20');
            const response = await NetworkServiceCall('get', APIURL + safeApi, '');

            let items = [];
            if (response?.data?.data && Array.isArray(response.data.data)) {
                items = response.data.data.map(item => ({
                    label: item.displayvalue || item.datatext || item.name || 'Unknown',
                    value: item.datavalue || item.code || item.id,
                    original: item
                }));
            }

            // Ensure "Other" is present if not already (common requirement)
            if (!items.find(i => i.value === 'OTHER' || i.value === 12)) {
                // Check if it's allergies (ID 12 usually) or generic OTHER
                // For now, adhere to what API returns, parent handles adding specific extras if needed.
                // But logic in AllergyDropdown expects ID 12 for Other.
            }

            setData(items);
            setFilteredData(items);
            setLoadedFromApi(true);
        } catch (err) {
            console.error('Dropdown Fetch Error:', err);
        } finally {
            setLoading(false);
        }
    };

    const openModal = () => {
        Animated.spring(slideAnim, {
            toValue: 0,
            useNativeDriver: true,
        }).start();
    };

    const closeModal = () => {
        Animated.timing(slideAnim, {
            toValue: SCREEN_HEIGHT,
            duration: 250,
            useNativeDriver: true,
        }).start(() => setVisible(false));
    };

    const handleSelect = (item) => {
        // Toggle selection
        const isSelected = value.includes(item.value);
        let newValues;

        if (isSelected) {
            newValues = value.filter(v => v !== item.value);
        } else {
            newValues = [...value, item.value];
        }

        // We also need to return the full item objects for the parent to process logic like "No Known Allergies"
        // which might need to see the label or other props.
        // But standard onChange usually just gives values.
        // Let's call onChange with (newValues, selectedItems)
        const selectedItems = data.filter(d => newValues.includes(d.value)).map(d => d.original);

        onChange(newValues, selectedItems);
    };

    const renderItem = ({ item }) => {
        const isSelected = value.includes(item.value);
        const itemIconGroup = item.iconGroup || iconGroup;

        return (
            <TouchableOpacity
                style={[styles.itemContainer, isSelected && styles.itemSelected]}
                onPress={() => handleSelect(item)}
            >
                <View style={styles.itemContent}>
                    {item.icon && (
                        itemIconGroup === 'FontAwesome5' ? (
                            <Icons.FontAwesome5
                                name={item.icon}
                                size={16}
                                color={item.iconColor || '#555'}
                                style={{ marginRight: 12 }}
                                solid
                            />
                        ) : (
                            <Icons.MaterialCommunityIcons
                                name={item.icon}
                                size={20}
                                color={item.iconColor || '#555'}
                                style={{ marginRight: 12 }}
                            />
                        )
                    )}
                    <Text style={[styles.itemText, isSelected && styles.itemTextSelected]}>
                        {item.label}
                    </Text>
                </View>

                {isSelected ? (
                    <Icons.FontAwesome5 name="check-square" size={18} color="#094485" solid />
                ) : (
                    <Icons.FontAwesome5 name="square" size={18} color="#9ca3af" />
                )}
            </TouchableOpacity>
        );
    };

    // Construct display text
    const getDisplayText = () => {
        if (displayValue) return displayValue;
        if (!value || value.length === 0) return '';

        // Try to map values to labels from data if available
        if (data.length > 0) {
            const names = value.map(v => {
                const match = data.find(d => d.value === v);
                return match ? match.label : v;
            });
            if (names.length > 2) return `${names.length} selected`;
            return names.join(', ');
        }

        return `${value.length} selected`;
    };

    return (
        <View style={[styles.container, style]}>
            {/* Trigger Button */}
            <TouchableOpacity
                style={[
                    styles.trigger,
                    disabled && styles.disabled,
                    error && styles.errorBorder,
                    visible && styles.focusedBorder
                ]}
                onPress={() => !disabled && setVisible(true)}
                activeOpacity={0.7}
                disabled={disabled}
            >
                {label && (
                    <View style={styles.labelContainer}>
                        <Text style={[styles.label, disabled && { color: '#6c757d' }]}>
                            {label}
                            {required && <Text style={{ color: '#dc3545' }}> *</Text>}
                        </Text>
                    </View>
                )}

                <View style={styles.triggerContent}>
                    {icon && (
                        <View style={styles.iconContainer}>
                            {iconGroup === 'FontAwesome5' ? (
                                <Icons.FontAwesome5 name={icon} size={16} color={disabled ? "#6c757d" : "#094485"} solid />
                            ) : (
                                <Icons.MaterialCommunityIcons name={icon} size={18} color={disabled ? "#6c757d" : "#094485"} />
                            )}
                        </View>
                    )}

                    <Text style={[
                        styles.valueText,
                        (!value || value.length === 0) && styles.placeholderText,
                        disabled && { color: '#6c757d' }
                    ]} numberOfLines={1}>
                        {getDisplayText() || placeholder}
                    </Text>

                    <Icons.Feather name="chevron-down" size={18} color={disabled ? "#9ca3af" : "#6b7280"} />
                </View>
            </TouchableOpacity>

            {error && <Text style={styles.errorText}>{error}</Text>}

            {/* Modal */}
            <Modal
                visible={visible}
                transparent={true}
                animationType="none"
                onRequestClose={() => setVisible(false)}
            >
                <View style={styles.modalOverlay}>
                    <TouchableOpacity
                        style={styles.modalBackdrop}
                        activeOpacity={1}
                        onPress={() => setVisible(false)}
                    />

                    <Animated.View style={[
                        styles.modalContent,
                        { transform: [{ translateY: slideAnim }] }
                    ]}>
                        <View style={styles.modalHeader}>
                            <TouchableOpacity onPress={() => setVisible(false)}>
                                <Text style={styles.cancelText}>Close</Text>
                            </TouchableOpacity>
                            <Text style={styles.modalTitle}>Select {label}</Text>
                            <TouchableOpacity onPress={() => setVisible(false)}>
                                <Text style={styles.doneText}>Done</Text>
                            </TouchableOpacity>
                        </View>

                        {searchable && (
                            <View style={styles.searchContainer}>
                                <Icons.Feather name="search" size={16} color="#9ca3af" style={styles.searchIcon} />
                                <TextInput
                                    style={styles.searchInput}
                                    placeholder="Search..."
                                    value={searchText}
                                    onChangeText={setSearchText}
                                    autoCapitalize="none"
                                />
                                {searchText.length > 0 && (
                                    <TouchableOpacity onPress={() => setSearchText('')}>
                                        <Icons.Feather name="x-circle" size={16} color="#9ca3af" />
                                    </TouchableOpacity>
                                )}
                            </View>
                        )}

                        {loading ? (
                            <View style={styles.centerContainer}>
                                <ActivityIndicator size="large" color="#094485" />
                            </View>
                        ) : (
                            <FlatList
                                data={filteredData}
                                renderItem={renderItem}
                                keyExtractor={(item, index) => item.value?.toString() || index.toString()}
                                contentContainerStyle={styles.listContent}
                                ListEmptyComponent={
                                    <View style={styles.centerContainer}>
                                        <Text style={styles.emptyText}>No options found</Text>
                                    </View>
                                }
                            />
                        )}
                    </Animated.View>
                </View>
            </Modal>
        </View>
    );
};

const styles = StyleSheet.create({
    container: {
        marginBottom: 0,
        width: '100%',
    },
    trigger: {
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: '#fff',
        borderWidth: 1,
        borderColor: '#E0E0E0',
        borderRadius: 8,
        height: 38,
        paddingHorizontal: 12,
        marginTop: 6,
    },
    focusedBorder: {
        borderColor: '#094485',
        elevation: 2,
    },
    errorBorder: {
        borderColor: '#dc3545',
    },
    disabled: {
        backgroundColor: '#f8f9fa',
        borderColor: '#d6d8db',
    },
    labelContainer: {
        position: 'absolute',
        top: -9,
        left: 8,
        backgroundColor: '#fff',
        paddingHorizontal: 4,
        zIndex: 1,
    },
    label: {
        fontSize: 11,
        color: '#094485',
        fontWeight: '600',
    },
    triggerContent: {
        flex: 1,
        flexDirection: 'row',
        alignItems: 'center',
    },
    iconContainer: {
        marginRight: 8,
        width: 20,
        alignItems: 'center',
    },
    valueText: {
        flex: 1,
        fontSize: 14,
        color: '#1f2937',
        fontWeight: '500',
    },
    placeholderText: {
        color: '#9ca3af',
        fontWeight: '400',
    },
    errorText: {
        color: '#dc3545',
        fontSize: 12,
        marginTop: 4,
        marginLeft: 4,
    },
    modalOverlay: {
        flex: 1,
        backgroundColor: 'rgba(0,0,0,0.5)',
        justifyContent: 'flex-end',
    },
    modalBackdrop: {
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
    },
    modalContent: {
        backgroundColor: '#fff',
        borderTopLeftRadius: 20,
        borderTopRightRadius: 20,
        height: '70%',
        shadowColor: '#000',
        shadowOffset: { width: 0, height: -2 },
        shadowOpacity: 0.25,
        shadowRadius: 5,
        elevation: 5,
    },
    modalHeader: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'space-between',
        paddingHorizontal: 16,
        paddingVertical: 14,
        borderBottomWidth: 1,
        borderBottomColor: '#f3f4f6',
    },
    modalTitle: {
        fontSize: 16,
        fontWeight: 'bold',
        color: '#111827',
    },
    cancelText: {
        fontSize: 16,
        color: '#6b7280',
    },
    doneText: {
        fontSize: 16,
        fontWeight: '600',
        color: '#094485',
    },
    searchContainer: {
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: '#f3f4f6',
        margin: 12,
        borderRadius: 8,
        paddingHorizontal: 10,
        height: 40,
    },
    searchIcon: {
        marginRight: 8,
    },
    searchInput: {
        flex: 1,
        fontSize: 14,
        color: '#1f2937',
        paddingVertical: 0,
    },
    listContent: {
        paddingBottom: 20,
    },
    itemContainer: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'space-between',
        paddingVertical: 14,
        paddingHorizontal: 16,
        borderBottomWidth: 1,
        borderBottomColor: '#f9fafb',
    },
    itemSelected: {
        backgroundColor: '#eff6ff',
    },
    itemContent: {
        flexDirection: 'row',
        alignItems: 'center',
    },
    itemText: {
        fontSize: 15,
        color: '#374151',
    },
    itemTextSelected: {
        color: '#094485',
        fontWeight: '600',
    },
    centerContainer: {
        flex: 1,
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: 100,
    },
    emptyText: {
        color: '#9ca3af',
        fontSize: 14,
    },
});

export default ModernMultiSelectDropdown;
