import React, { useState, useRef, useEffect } from 'react';
import { TouchableOpacity, View, Text, Image, FlatList, Dimensions, PanResponder, TextInput } from 'react-native';
// import Carousel, { Pagination } from 'react-native-snap-carousel';
import ImageZoom from 'react-native-image-pan-zoom';
import FastImage from 'react-native-fast-image'
import HOCIcons from '../HOC/HOCIcons';
import { CircleLoader, CShadowDynamic, isBNUL, isNU, isNUQ, LoaderIndicator, normalize, notifyMessage } from '../CommonStyle/ComponentFunctions';
import Loader from '../Custom/Loader';
import CFooterView from './CFooterView';
import HeaderBlock from '../Screens/HeaderBlock';
import { Global } from '../Common/Global';
import CCustomTextInput from './CCustomTextInput';
// import TextRecognition, { TextRecognitionScript } from '@react-native-ml-kit/text-recognition';
import { Menu, MenuOptions, MenuProvider, MenuTrigger } from 'react-native-popup-menu';
const { width } = Dimensions.get('window');
const { height } = Dimensions.get('window');

const CPhotoGallery = (props) => {

  const flatListRef = useRef();
  const [images, setImages] = useState([...props.route.params.displayarray]);
  const [indexSelected, setIndexSelected] = useState(isNU(props.route.params.index) ? props.route.params.index : 0);
  const [isLoading, setIsLoading] = useState(false);
  const [searchText, setSearchText] = useState();
  const [searchEnabled, setSearchEnabled] = useState(false);

  useEffect(() => {

    const processImages = async (imageUris) => {
      try {
        const results = await Promise.all(
          imageUris.map(async (uri) => {
            try {
              // const result = await TextRecognition.recognize(uri.filelink, TextRecognitionScript.LATIN);
              return {
                ...uri,
                searchtext: result.text
              };
            } catch {
              return { ...uri };
            }
          })
        );
        // Filter out null results (error cases)
        const successfulResults = results.filter(result => result !== null);
        setSearchEnabled(true);
        setImages(successfulResults);
        setIsLoading(false);

      } catch (error) {

        console.error('Error processing images:', error);
        setIsLoading(false);
      } finally {
        setIsLoading(false);
      }
    };

    const sampledata = props?.route?.params?.displayarray ? [...props?.route?.params?.displayarray] : [];

    if (isBNUL(sampledata)) {
      setIsLoading(true)
      processImages(sampledata);
    }
    else {
      setIsLoading(false);
    }

  }, [props?.route?.params?.displayarray]);

  function getCurrentData(array, count) {

    let prevcodearray = isBNUL(array) ? array.filter((i, k) => { return k == count ? { ...i } : undefined }) : [];
    let prevcode = isBNUL(prevcodearray) && isNU(prevcodearray[0]) ? prevcodearray[0] : {};
    return prevcode;
  }

  function mainArrayList(array) {

    const newDropDownData = array != undefined ? array.filter(function (item) {
      const dataItem = item.searchtext ? item.searchtext.toUpperCase() : ''.toUpperCase();
      const textData = isNU(searchText) ? searchText.toUpperCase() : '';
      return dataItem.indexOf(textData) > -1;
    }) : null;

    return (
      isBNUL(newDropDownData) ?
        <FlatList
          ref={flatListRef}
          initialNumToRender={50}
          maxToRenderPerBatch={50}
          horizontal={true}
          data={newDropDownData}
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={{ alignItems: 'center' }}
          keyExtractor={(item, index) => 'key' + index}
          renderItem={renderItem}
        />
        : null
    )
  }

  function renderItem({ item, index }) {

    return (
      <TouchableOpacity
        onPress={() => {
          if (index == indexSelected) {
          }
          else {
            setIndexSelected(index)
          }
        }}
        activeOpacity={0.3}
        style={{
          elevation: 5,
          marginVertical: normalize(5),
          marginHorizontal:normalize(7),
          borderRadius: 3,
          borderWidth: index === indexSelected ? 3 : 1,
          borderColor: index === indexSelected ? Global.AppTheme.primary_color : 'grey',
          justifyContent: 'center',
          alignItems: 'center',
          backgroundColor: index === indexSelected ? '#e8ecff' : 'white',
          ...CShadowDynamic(-3,3,7,0,Global.AppTheme.primary_color)
        }}
      >
        {isNUQ(item.filelink) ?

          <FastImage
            style={{ width: normalize(45), height: normalize(45), borderWidth: 1, borderColor: 'white', borderRadius: 0 }}
            resizeMode="stretch"
            source={{ uri: item.filelink }}
          />
          : null}
        <View style={[{ opacity: 0.8, position: 'absolute', backgroundColor: '#e2e8ff', borderWidth: 0, borderRadius: 1000 }, { width: normalize(20), height: normalize(20), justifyContent: 'center' }]}>
          <Text
            adjustsFontSizeToFit
            style={{ textAlign: 'center', color: 'grey', fontSize: normalize(15) }}
          >
            {index + 1}
          </Text>
        </View>
      </TouchableOpacity>
    )

  }

  function renderMainView(array) {

    const newDropDownData = array != undefined ? array.filter(function (item) {
      const dataItem = item.searchtext ? item.searchtext.toUpperCase() : ''.toUpperCase();
      const textData = isNU(searchText) ? searchText.toUpperCase() : '';
      return dataItem.indexOf(textData) > -1;
    }) : null;

    return (
      <View style={{ flex: 1 }}>

        {isBNUL(newDropDownData) && isNU(getCurrentData(newDropDownData, indexSelected).searchtext) ?
         
          <View style={{ borderWidth: 1, borderRadius: 5, backgroundColor: '#f0f0f0', borderColor: 'lightgrey', margin: normalize(4), padding: normalize(4) }}>
            
            <Menu>
              <MenuTrigger customStyles={{ triggerWrapper: {} }} >
                <Text selectable={true} numberOfLines={3} style={{ fontSize: normalize(10), fontWeight: '200', color: 'black' }}>{JSON.stringify(getCurrentData(newDropDownData, indexSelected).searchtext).replace(/\n/g, '')}</Text>
                {/* <Text selectable style={{ marginLeft: normalize(3), fontSize: normalize(12), color: 'black', fontWeight: 'bold', }}>
                {JSON.stringify(getCurrentData(newDropDownData, indexSelected).searchtext).replace(/\n/g, '')}
                </Text> */}
              </MenuTrigger>
              <MenuOptions optionsContainerStyle={{ marginTop: normalize(15) }} customStyles={{ optionsContainer: { width: '95%', backgroundColor: '#f0f0f0', borderRadius: 10, borderWidth: 1, borderColor: 'lightgrey' }, optionText: {}, }}>
                <View style={{ borderWidth: 0, padding: normalize(5), justifyContent: 'center', alignItems: 'center' }}>
                  <Text selectable={true} style={{ fontSize: normalize(10), color: 'black', fontWeight: 'normal' }} >{JSON.stringify(getCurrentData(newDropDownData, indexSelected).searchtext.replace(/\n/g, ''))}</Text>
                  <View style={{ flexDirection: 'row' }}>
                    <HOCIcons.Feather
                      name={'info'}
                      size={normalize(10)}
                      color={'grey'}
                      style={{ marginHorizontal: normalize(3) }}
                    />
                    <Text style={{ color: 'grey', fontSize: normalize(8), fontStyle: 'italic' }}>long press to copy</Text>
                  </View>
                </View>
              </MenuOptions>
            </Menu>
          </View>
          
          : null}

        {isBNUL(newDropDownData) && isNU(getCurrentData(newDropDownData, indexSelected).filelink) ?
          <ImageZoom
            cropWidth={width * 1}
            cropHeight={height * 0.6}
            imageWidth={width * 1}
            imageHeight={height * 0.6}
            enableSwipeDown={false}
            panToMove={true}
            style={{ borderWidth: 0 }}
          >
            <FastImage
              style={{ width: Dimensions.get('window').width, height: normalize(60), borderWidth: 0, flex: 1 }}
              resizeMode={'contain'}
              source={{ uri: getCurrentData(newDropDownData, indexSelected).filelink }}
            />
          </ImageZoom>
          : null}

        {isBNUL(newDropDownData) && (indexSelected != 0) ?
          <TouchableOpacity
            onPress={() => {
              setIndexSelected(indexSelected - 1);
              flatListRef.current.scrollToIndex({ index: indexSelected - 1 });
            }}
            style={{ opacity: 1, position: 'absolute', left: 0, top: Dimensions.get('window').height * 0.2, backgroundColor: 'white', justifyContent: 'center', alignItems: 'center', borderTopRightRadius: 5, borderBottomRightRadius: 5, elevation: 2, borderWidth: 0.5, borderColor: 'grey' }}>
            <HOCIcons.Icons
              icongroup={4}
              name={'angle-double-left'}
              color={Global.AppTheme.primary_color}
              size={normalize(20)}
              style={{
                textAlign: 'center',
                margin: normalize(5),
                marginVertical: normalize(10)
              }}
            />
          </TouchableOpacity>
          : null}

        {isBNUL(newDropDownData) && (newDropDownData.length != (indexSelected + 1)) ?
          <TouchableOpacity
            onPress={() => {
              setIndexSelected(indexSelected + 1);
              flatListRef.current.scrollToIndex({ index: indexSelected + 1 });
            }}
            style={{
              opacity: 1,
              right: 0,
              top: Dimensions.get('window').height * 0.2,
              position: 'absolute',
              backgroundColor: 'white',
              justifyContent: 'center',
              alignItems: 'center',
              borderTopLeftRadius: 5,
              borderBottomLeftRadius: 5,
              elevation: 2,
              borderWidth: 0.5,
              borderColor: 'grey'
            }}>
            <HOCIcons.Icons
              icongroup={4}
              name={'angle-double-right'}
              color={Global.AppTheme.primary_color}
              size={normalize(20)}
              style={{
                textAlign: 'center',
                margin: normalize(5),
                marginVertical: normalize(10)
              }}
            />
          </TouchableOpacity>
          : null}

      </View>
    )

  }

  function findFilterImageLength(array) {

    const newDropDownData = array != undefined ? array.filter(function (item) {
      const dataItem = item.searchtext ? item.searchtext.toUpperCase() : ''.toUpperCase();
      const textData = isNU(searchText) ? searchText.toUpperCase() : '';
      return dataItem.indexOf(textData) > -1;
    }) : [];

    return newDropDownData.length

  }

  return (
    <View style={{ flex: 1, backgroundColor: 'white', borderWidth: 0 }}>
      <View style={{ flex: 1 }}>
        {props.route.params.hideheader ? null :
          <HeaderBlock />
        }
        <View style={{ flex: 1, backgroundColor: 'white' }}>
          <View style={{ flex: 1, justifyContent: 'center' }}
          // {...panResponder.panHandlers}
          >

            <View style={{ width: '95%', marginBottom: normalize(5), height: normalize(45), borderWidth: 0, justifyContent: 'center', alignItems: 'center', alignSelf: 'center' }}>
              {searchEnabled && !isLoading ?
                <CCustomTextInput
                  required={false}
                  // info={"Enter Keywords to search image."}
                  custompositiontextviewstyle={{
                    position: 'absolute',
                    top: normalize(-4),
                    left: normalize(7),
                    flexDirection: 'row',
                    alignItems: 'center',
                    backgroundColor: 'white',
                  }}
                  inputstyle={{
                    marginTop: normalize(10),
                    borderWidth: 1,
                    borderColor: 'lightgrey',
                    borderRadius: 5,
                    alignItems: 'center',
                    justifyContent: 'flex-start',
                    height: normalize(35),
                    flexDirection: 'row',
                    backgroundColor: 'white',
                    elevation: 2,
                    width: '100%'
                  }}
                  iconstyle={{
                    icongroup: 3,
                    iconname: "image-search",
                    iconsize: normalize(18),
                    iconcolor: Global.AppTheme.primary_color,
                    style: {
                      paddingHorizontal: normalize(7)
                    }
                  }}
                  data={{
                    displaytext: 'Search Image',
                    type: 'default',
                    iconcolor: 'darkblue',
                    editable: true,
                    itemwidth: '100%',
                    icongroup: 3,
                    iconname: 'image-search',
                    value: searchText ? searchText : "",
                    tfontweight: 'bold',
                    placeholder: 'Search Image',
                    placeholdercolor: 'lightgrey',
                    capitalize: 'characters',
                    tfontsize: normalize(12)
                  }}
                  callBack={changevalue => (changevalue == undefined ? null : (
                    setSearchText(changevalue),
                    setIndexSelected(0)
                  ))}
                  CloseIcon={isNUQ(searchText) ? true : false}
                  CloseCallBack={val => (val == undefined ? null : (
                    setSearchText('')
                  ))}
                />
                : null}
              {isBNUL(images) && searchEnabled && !isLoading && isNUQ(searchText) ?
                <Text style={{ color: 'grey', fontSize: normalize(10), marginTop: normalize(5), textAlign: 'center', borderWidth: 0, width: '100%' }}>
                  {findFilterImageLength(images)}{' Image(s) found.'}
                </Text>
                : null}
              {isLoading ?
                <View style={{ borderWidth: 0 }}>
                  <CircleLoader />
                </View>
                : null}
            </View>

            <View style={{ flex: 1 }}>
            <MenuProvider>
              {renderMainView(images)}
              </MenuProvider>
            </View>
          </View>
          <View
            style={[{ paddingVertical: 5, justifyContent: 'center', backgroundColor: 'white', borderTopWidth: 1, borderTopColor: 'lightgrey' }]}
          >
            {isBNUL(images) ?
              <View style={{ alignItems: 'center', borderWidth: 0 }}>
                {mainArrayList(images)}
              </View>
              : null}
            {isBNUL(images) ?
              <View
                style={{
                  borderWidth: 0,
                  alignSelf: 'flex-end',
                  marginRight: normalize(10)
                }}
              >
                <Text style={{ color: Global.AppTheme.primary_color, fontSize: normalize(12), fontWeight: 'bold' }}>
                  {indexSelected + 1}/{images.length}
                </Text>
              </View>
              : null}
          </View>
        </View>
      </View>
    </View>
  );
};

export default CPhotoGallery;

