import React, { useState } from 'react';
import { View, TextInput, Dimensions, TouchableOpacity, Text } from 'react-native';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import { Global } from '../Common/Global';
import { normalize } from '../CommonStyle/componentStyle';
import CText from '../CustomComponents/CText';

const STextInput = (props) => {
    const [text, setText] = useState("")
    const [colorBg, setColorBg] = useState(false)
    // const [data, setData] = useState(props.data != undefined ? props.data : {
    //     itemwidth: "92%",
    //     displaytext: "Name",
    //     iconname: 'home',
    //     value: 45,
    //     type: 'number-pad',
    //     editable: true,
    //     placeholder: "Name",
    //     decimal: 2
    // })

    const data = props.data != undefined ? props.data : {
        itemwidth: "92%",
        displaytext: "Name",
        iconname: 'home',
        value: 45,
        type: 'number-pad',
        editable: true,
        placeholder: "Name",
        decimal: 2
    };

    return (
        <View style={{
            marginHorizontal: normalize(5)
        }}>
            {data.displaytext != undefined ?
                <CText style={{ fontSize: normalize(12), color: 'black', paddingHorizontal: 5 }}>{data.displaytext != undefined ? data.displaytext : "Default"}</CText> : null}

            <View style={{ flexDirection: 'row',alignItems:'center' }}>
                <View style={{ flexDirection: 'row', borderWidth: 1, borderRadius: 5, alignItems: 'center', backgroundColor: props.bgcolor ? props.bgcolor : '#ffffff', elevation: 3, borderColor: colorBg ? '#8ec6ff' : 'lightgrey' }}>
                    {props.hideicon ? null : <FontAwesome5 name={data.iconname != undefined ? data.iconname : "file-alt"} size={normalize(15)} color={Global.AppTheme.primary_color} style={{ paddingHorizontal: 5, width: normalize(25) }} />}
                    <TextInput
                        style={{
                            width: data.itemwidth != undefined ? data.itemwidth : Dimensions.get('screen').width * 0.25,
                            padding: normalize(5),
                            fontSize: normalize(14),
                            height: data.disableheight ? null : data.height != undefined ? normalize(100) : normalize(30),
                            paddingBottom: 3,
                            color:'black'
                        }}
                        onChangeText={val => ChangeValue(val)}
                        multiline={true}
                        // onFocus={() => setColorBg(true)}
                        onEndEditing={(val) => props.onEndEditing != undefined ? props.onEndEditing(val) : () => 
                            null
                            // getFocusOut()
                        }
                        onSubmitEditing={props.onSubmitEditing != undefined ? (val) => props.onSubmitEditing(val) : null}
                        autoCapitalize={data.capitalize != undefined ? data.capitalize : 'none'}
                        textAlign={data.alignment != undefined ? data.alignment : data.type == 'number-pad' ? 'right' : 'left'}
                        keyboardType={data.type != undefined ? data.type : 'default'}
                        maxLength={data.maxlength != undefined ? data.maxlength : 200}
                        editable={data.editable != undefined ? data.editable : true}
                        placeholder={data.placeholder != undefined ? data.placeholder : null}
                        {...props}
                    >{data.value != undefined ? data.value : ""}</TextInput>
                </View>

                {props.unit != undefined && props.unit != null && props.unit != "" ?
                    <TouchableOpacity
                        disabled={props.tprcallback ? false : true}
                        onPress={() => {
                            props.tprcallback ? props.tprcallback(true) : null
                        }}
                        style={{
                            borderStyle: props.tprcallback ? 'solid' : 'dotted',
                            elevation: props.tprcallback ? 3 : 0,
                            borderRadius: 5,
                            alignItems: 'center',
                            height: normalize(30),
                            justifyContent: 'center',
                            borderWidth: 1,
                            marginLeft: 1,
                            width: normalize(30),
                            backgroundColor: '#f7f7f7',
                            borderColor: Global.AppTheme.primary_color
                        }}>
                        <Text numberOfLines={1} adjustsFontSizeToFit style={{
                            fontWeight: 'bold', color: data.errorStatus != undefined
                                && data.errorStatus ? 'red' : Global.AppTheme.primary_color, fontSize: normalize(12)
                        }}>{props.unit}</Text>
                        {/* <Text style={{
                            fontSize: normalize(8),
                            color: 'black'
                        }}>
                            {"Setup"}
                        </Text> */}
                    </TouchableOpacity> : null}
            </View>
        </View>
    )

    function getFocusOut() {
        setColorBg(false)
    }

    function ChangeValue(changevalue) {

        if (props.normalTextInput) {
            setText(changevalue);
            (props.callBack != undefined ? (props.callBack(changevalue)) : console.log('non changed'));
        }
        else {

            let datatype = data.datatype != undefined ? data.datatype : "integer";
            let _error = changevalue == '' ? false : validate(changevalue, datatype);
            data.errorStatus = _error == false ? false : true;
            setText(changevalue);
            (props.callBack != undefined ? (props.callBack(changevalue)) : console.log('non changed'));
        }
    }

    function validate(text, datatype) {
        let status = true;
        switch (datatype) {
            case 'integer':
                let integerRegex = /^[0-9.]*$/;
                if (integerRegex.exec(text)) {
                    if (data.minvalue == null && data.maxvalue == null) {
                        status = false;
                    } else if (data.minvalue == null) {
                        if (data.maxvalue == '') {
                            status = false;
                        } else {
                            if (text <= data.maxvalue) {
                                status = false;
                            } else {
                                status = true;
                            }
                        }
                    } else if (data.maxvalue == null) {
                        if (data.minvalue == '') {
                            status = false;
                        } else {
                            if (text >= data.minvalue) {
                                status = false;
                            } else {
                                status = true;
                            }
                        }
                    } else if (data.minvalue == '' && data.maxvalue == '') {
                        status = false;
                    } else if (data.minvalue == '') {
                        if (text <= data.maxvalue) {
                            status = false;
                        } else {
                            status = true;
                        }
                    } else if (data.maxvalue == '') {
                        if (text >= data.minvalue) {
                            status = false;
                        } else {
                            status = true;
                        }
                    } else {
                        if (text >= data.minvalue && text <= data.maxvalue) {
                            status = false;
                        } else {
                            status = true;
                        }
                    }
                } else {
                    status = true;
                }
                break;
            case 'password':
                let passwordRegex = /[0-9a-zA-Z]/;
                if (passwordRegex.exec(text)) status = false;
                else status = true;
                break;
            case 'string':
                let stringRegex = /^[a-zA-Z0-9.!#$%&@\s]*$/;
                if (stringRegex.exec(text)) {
                    let minvalue = data.minvalue;
                    let maxvalue = data.maxvalue;
                    let length = text == null ? 0 : text.length;
                    if (minvalue == null && maxvalue == null) {
                        status = false;
                    } else if (minvalue == null) {
                        if (maxvalue == '') {
                            status = false;
                        } else {
                            if (length <= maxvalue) {
                                status = false;
                            } else {
                                status = true;
                            }
                        }
                    } else if (maxvalue == null) {
                        if (minvalue == '') {
                            status = false;
                        } else {
                            if (length >= minvalue) {
                                status = false;
                            } else {
                                status = true;
                            }
                        }
                    } else if (minvalue == '' && maxvalue == '') {
                        status = false;
                    } else if (minvalue == '') {
                        if (length <= maxvalue) {
                            status = false;
                        } else {
                            status = true;
                        }
                    } else if (maxvalue == '') {
                        if (length >= minvalue) {
                            status = false;
                        } else {
                            status = true;
                        }
                    } else {
                        if (length >= minvalue && length <= maxvalue) {
                            status = false;
                        } else {
                            status = true;
                        }
                    }
                } else {
                    status = true;
                }
                break;
            case 'numeric':
                let numericRegex = /^[0-9.]*$/;
                if (numericRegex.exec(text)) {
                    if (data.minvalue == null && data.maxvalue == null) {
                        status = false;
                    } else if (data.minvalue == null) {
                        if (data.maxvalue == '') {
                            status = false;
                        } else {
                            if (text <= data.maxvalue) {
                                status = false;
                            } else {
                                status = true;
                            }
                        }
                    } else if (data.maxvalue == null) {
                        if (data.minvalue == '') {
                            status = false;
                        } else {
                            if (text >= data.minvalue) {
                                status = false;
                            } else {
                                status = true;
                            }
                        }
                    } else if (data.minvalue == '' && data.maxvalue == '') {
                        status = false;
                    } else if (data.minvalue == '') {
                        if (text <= data.maxvalue) {
                            status = false;
                        } else {
                            status = true;
                        }
                    } else if (data.maxvalue == '') {
                        if (text >= data.minvalue) {
                            status = false;
                        } else {
                            status = true;
                        }
                    } else {
                        if (text >= data.minvalue && text <= data.maxvalue) {
                            status = false;
                        } else {
                            status = true;
                        }
                    }
                } else {
                    status = true;
                }
                break;
        }
        return status;
    }
}
export default STextInput;



