import React from 'react';
import { TextInput, View, TouchableOpacity, StyleSheet, Platform } from 'react-native';
import { normalize } from '../CommonStyle/componentStyle';
import HOCIcons from '../HOC/HOCIcons';
import { Global } from '../Common/Global';

const SSearchBar = (props) => {
  const { placeholder = "Search", callBack } = props;
  
  return (
    <View style={styles.container}>
      <View style={styles.searchContainer}>
        <TextInput
          style={styles.input}
          editable={true}
          autoCapitalize={'none'}
          keyboardType={'default'}
          placeholder={placeholder}
          placeholderTextColor={'#9e9e9e'}
          {...props}
        />
         <TouchableOpacity
          style={styles.searchIconContainer}
          disabled={!callBack}
          onPress={() => callBack && callBack(true)}
        >
          <HOCIcons.Icons
            icongroup={5}
            name={'search'}
            size={normalize(16)}
            color={Global.AppTheme.primary_color}
          />
        </TouchableOpacity>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
    alignItems: 'center',
    paddingHorizontal: normalize(5),
    marginVertical: normalize(5),
  },
  searchContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    width: '100%',
    height: normalize(30),
    backgroundColor: '#ffffff',
    borderRadius: normalize(12),
    paddingHorizontal: normalize(12),
    ...Platform.select({
      ios: {
        shadowColor: Global.AppTheme.primary_color,
        shadowOffset: { width: 0, height: 2 },
        shadowOpacity: 0.2,
        shadowRadius: 4,
      },
      android: {
        elevation: 4,
      },
      web: {
        boxShadow: `0px 2px 4px rgba(0, 0, 0, 0.1)`,
      },
    }),
    borderWidth: Platform.OS === 'ios' ? 0 : 0.5,
    borderColor: Platform.OS === 'ios' ? 'transparent' : '#e0e0e0',
  },
  searchIconContainer: {
    justifyContent: 'center',
    alignItems: 'center',
    paddingRight: normalize(8),
  },
  input: {
    flex: 1,
    height: '100%',
    color: '#333333',
    fontSize: normalize(15),
    fontWeight: '500',
    padding: 0,
  },
});

export default SSearchBar;