import React, { useState, useContext, useEffect } from 'react'
import { View, Text, TouchableOpacity, TextInput, TouchableWithoutFeedback, Dimensions, StyleSheet, ScrollView, FlatList, Switch, Alert } from 'react-native'
import Icons from '../Common/Icons';
import { colors, fontWeight } from '../CommonStyle/commonStyle';
import ComponentStyles, { normalize } from '../CommonStyle/componentStyle';
import Loader from '../Custom/Loader';
import { Collapse, CollapseHeader, CollapseBody, } from 'accordion-collapse-react-native';
import popupStyles, { getListviewItem, getListviewItemText, } from '../CommonStyle/PopupStyle';
import SAlphabet from '../StaticComponents/SAlphabet';
import SSearchBar from '../StaticComponents/SSearchBar';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import { CButtonShadow, CFooterShadow, CFooterShadowWhite, getLoading, isBNUL, isNU, isNUQ, notifyMessage } from '../CommonStyle/ComponentFunctions';
import CFooterView from '../CustomComponents/CFooterView';
import CAwesomeButton from '../CustomComponents/CAwesomeButton';
import { APIURL } from '../Common/apiConstants';
import { Global } from '../Common/Global';
import CBackHandler from '../CustomComponents/CBackHandler';
import FastImage from 'react-native-fast-image';
import AwesomeButton from 'react-native-really-awesome-button';
import HShadowButton from '../HOC/HShadowButton';

export default function AddDiagnosisTemplate(props) {

    console.log('props.data', JSON.stringify(props.data.link));

    const { width, height } = Dimensions.get('window');
    const [searchData, setSearchData] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [displayData, setDisplayData] = useState([]);
    const [overwrite, setOverwrite] = useState(false);
    const [tempString, settempString] = useState([]);
    const [selected, setSelected] = useState(0);
    const [alphaFilter, setAlphaFilter] = useState(false);
    const [backHandler, setBackHandler] = useState(false)
    const [filterPurpose, setFilterPurpose] = useState([]);
    const [stage, setStage] = useState(1);
    const [diagnosisData, setDiagnosisData] = useState([]);

    useEffect(() => {
        DropDownList()
    }, []);

    function DropDownList() {

        // let buttonapi = APIURL + 'emr/emrcommonget/rntemplatedropdown ' + Global.userData.hosuconsultant + "," + 2
        let buttonapi = props.data.link;
        setIsLoading(true);
        console.log("RETRIEVALLLLL DROPPPPP DOWNNNNNNNN", JSON.stringify(buttonapi))
        setDisplayData([]);

        NetworkServiceCall('get', buttonapi, '')
            .then(function (response) {
                if (response.httpstatus == 200 &&
                    response.data.data != null &&
                    response.data.data.length > 0) {
                    setDisplayData(response.data.data);
                    setIsLoading(false);
                } else {
                    notifyMessage('No Data Found!!!!!', 1);
                    setIsLoading(false);
                }
            });

        getLoading(v => setIsLoading(false))
    }

    function getAlphabetData(alpha, index) {
        var filter = displayData.filter(value => (value.displayvalue != undefined ? value.displayvalue : "").charAt(0) == alpha)
        setFilterPurpose(filter)
        index == 0 ? setSearchData('') : setSearchData(alpha)
        index == 0 ? setAlphaFilter(false) : setAlphaFilter(true)
    }

    function getFooterFunctions(item, val) {
        switch (item.functionid) {
            case "AD01":
                tempString.length > 0 ? getTemplate() : notifyMessage("Please select one template", 3)
                break;
            case "AD02":
                tempString.length > 0 ? getDeleteTemp() : notifyMessage("Please select one template", 3)
                break;
            default:
                break;
        }
    }

    function getDeleteTemp() {

        let buttonapi = APIURL + "emr/emrcommonget/hosumrtemplatedelete1 " + tempString[0] + "," + Global.userData.suuser;

        console.log("getDeleteTemp buttonapi........", JSON.stringify(buttonapi));

        NetworkServiceCall('get', buttonapi, '')
            .then(function (response) {
                if (response.httpstatus == 200 && response.data != undefined && response.data.message != undefined) {
                    notifyMessage(response.data.message);
                    if (response.data.deletestatus == true) {
                        settempString([]);
                        DropDownList();
                    } else {
                        notifyMessage(response.data.message, 3);
                    }
                } else {
                    notifyMessage('Error On Delete', 2);
                }
            })
    }

    function getTemplate() {

        var overwriteValue = overwrite ? 1 : 0;
        var apidata = Global.ParameterInfo;
        let buttonapi = APIURL + 'templatechart/getTemplate/' + apidata.hopapatient + "/" + apidata.homrpatientchart + "/" + apidata.hosuconsultant + "/" + apidata.suuser + "/" + tempString + "/" + overwriteValue;
        setIsLoading(true);
        console.log("Template Retrieveee dropp downnnnnnnnnnnn", JSON.stringify(buttonapi));

        NetworkServiceCall('get', buttonapi, '').then(function (response) {
            if (response.httpstatus == 200 &&
                response.data.data != null &&
                response.data.data.length > 0) {
                if (overwrite == 1) {
                    props.overwrite(response.data.data, props.visibility(false))
                } else {
                    props.callBack(response.data.data, props.visibility(false))
                }
            } else {
                notifyMessage('Please try again', 1);
                setIsLoading(false);
            }
        });

        getLoading(v => setIsLoading(false));
    }

    function GetSearchData(data) {
        var filterAlpha = alphaFilter ? filterPurpose : data;
        const newDropDownData = filterAlpha.filter(function (item) {
            const dataItem = item.displayvalue
                ? item.displayvalue.toUpperCase()
                : ''.toUpperCase();
            const textData = searchData.toUpperCase();
            return dataItem.indexOf(textData) > -1;
        });

        function renderItem(data) {
            return (
                <View style={{}}>
                    <Collapse
                        onToggle={() =>
                            stage == 1 ?
                                onSelectItem(data.item, false)
                                :
                                null
                        }>
                        <CollapseHeader>
                            <View
                                style={[
                                    getListviewItem(data.item.selected),
                                    {
                                        flexDirection: 'row',
                                        alignItems: 'center',
                                        justifyContent: 'flex-start',
                                    },
                                ]}>
                                <Icons.FontAwesome5
                                    name="dot-circle"
                                    color={Global.AppTheme.primary_color}
                                    size={normalize(17)}
                                    style={[{ margin: 2, paddingLeft: 5 }]}
                                />

                                <Text
                                    style={[
                                        getListviewItemText(data.item.selected),
                                        { margin: 2, paddingLeft: 2 },
                                    ]}>
                                    {data.item.displayvalue}
                                </Text>
                            </View>
                        </CollapseHeader>
                        <CollapseBody>
                            <FlatList data={data.item.datagroup1} renderItem={renderHeader} />
                        </CollapseBody>
                    </Collapse>
                </View>
            );
        }

        function getOveritePopUp() {
            Alert.alert(
                "Overwrite ?",
                "Do you really want to OVERWRITE TEMPLATE ? Saved classification data will be deleted on Select.",
                [
                    { text: "CONFIRM", onPress: () => setOverwrite(true) },
                    { text: "NO", onPress: () => setOverwrite(false) }
                ]
            )
        }

        function renderHeader(data) {
            return (
                <View style={getParameterView()}>
                    <Collapse isExpanded={data.item.isexpand}>
                        <CollapseHeader style={getCollapseHeader()}>
                            <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                                <Icons.FontAwesome5
                                    name={data.item.icon}
                                    color={Global.AppTheme.primary_color}
                                    size={normalize(14)}
                                    style={{
                                        margin: 2,
                                        paddingLeft: 5,
                                    }}
                                />
                                <Text style={layoutstyles.collapseheader_text}>
                                    {data.item.displayvalue}
                                </Text>
                            </View>
                        </CollapseHeader>

                        <CollapseBody style={getCollapseBody()}>
                            <FlatList
                                data={data.item.datagroup2}
                                renderItem={renderValue} />
                        </CollapseBody>
                    </Collapse>
                </View>
            );
        }

        function renderValue(data) {
            return (
                <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                    <Icons.Entypo name="dot-single" color="black" size={normalize(12)} />
                    <Text style={{ fontSize: normalize(12) }}>{data.item.display}</Text>
                </View>
            );
        }

        function onSelectItem(datavalue, multiselect) {

            if (multiselect == true) {
                if (tempString.includes(datavalue.datavalue)) {
                    datavalue.selected = !datavalue.selected;
                    setSelected(selected + 1);
                    var index = tempString.indexOf(datavalue.datavalue);
                    if (index > -1) {
                        tempString.splice(index, 1);
                    }
                } else {
                    datavalue.selected = !datavalue.selected;
                    setSelected(selected + 1);
                    tempString.push(datavalue.datavalue);
                }
            } else {
                displayData.map((sub) => sub.selected = false);
                datavalue.selected = true;
                tempString.splice(0, tempString.length);
                tempString.push(datavalue.datavalue);
                setSelected(selected + 1);
            }
        }

        return (
            <View style={layoutstyles.overlay_screen_listview_container}>
                <View style={getOverlayScreenChildlistContainer()}>
                    <FlatList data={newDropDownData} renderItem={renderItem} />
                </View>
                {stage == 1 ?

                    <TouchableOpacity
                        onPress={() => !overwrite ? getOveritePopUp() : setOverwrite(false)}
                        style={{ width: normalize(120), alignItems: 'center', position: 'absolute', bottom: normalize(-60), right: 0, zIndex: 1, backgroundColor: 'transparent' }}>

                        <FastImage
                            style={{
                                height: normalize(50),
                                width: normalize(70),
                                justifyContent: "center",
                                alignItems: "center",
                            }}
                            resizeMode={'cover'}
                            source={require('../Asset/gif/overwrite.gif')}
                        />

                        <View style={{ flexDirection: 'row', alignItems: 'center', zIndex: 1 }}>
                            <Text style={{ fontSize: normalize(10), paddingHorizontal: normalize(2) }}>OVERWRITE ?</Text>
                            <View style={{}}>
                                <Switch
                                    trackColor={{ false: "#767577", true: "red" }}
                                    thumbColor={"lightgrey"}
                                    onChange={() => !overwrite ? getOveritePopUp() : setOverwrite(false)}
                                    value={overwrite}
                                />
                            </View>
                        </View>
                    </TouchableOpacity>
                    : null}
                {backHandler ?
                    <CBackHandler
                        type={5} // 5 for overwrite template
                        callBack={(val) => (val == undefined ? null : console.log("VAL ADD TEMPLATE", JSON.stringify(val)))}
                        close={(val) => (val == undefined ? null : setBackHandler(val))}
                    /> : null}
            </View>
        );
    }

    function getOverlayScreenChildlistContainer() {
        return {
            flex: 1,
            marginBottom: height * 0.01,
            marginTop: height * 0.01,
        };
    }

    function getCollapseBody() {
        return {
            paddingLeft: width * 0.03,
        };
    }

    function getCollapseHeader() {
        return {
            margin: width * 0.002,
            padding: width * 0.007,
            ...layoutstyles.collapse_header,
        };
    }

    function getOverlayScreenChildContainer() {
        return {
            flex: 1,
        };
    }

    function getParameterView() {
        return {
            paddingLeft: width * 0.02,
        };
    }

    function getOverlayScreenContainer() {
        return {
            flexDirection: 'row',
        };
    }

    function getProvDiagnosis(stage) {

        const hosuconsultant = Global.userData.hosuconsultant;
        const type = stage == 2 ? 'P' : 'F';
        const micd = null;
        const mflag = 0;

        let buttonapi = `${APIURL}emr/emrcommonget/rnicdropdown ${hosuconsultant},'${type}','${micd}',${mflag}`;
        console.log("getProvDiagnosis buttonapi........", JSON.stringify(buttonapi));

        setDisplayData([]);

        NetworkServiceCall('get', buttonapi, '')
            .then(function (response) {
                if (response.httpstatus == 200) {
                    if (isNU(response.data) && isBNUL(response.data.data)) {
                        setDisplayData(response.data.data);
                    } else {
                        notifyMessage('Error On Delete', 2);
                    }
                }
                else {
                    notifyMessage('network error.')
                }
            })

    }

    function fnOnpress(buttons) {

        if (buttons.stage == 1) {
            setStage(buttons.stage)
        }
        else if (buttons.stage == 2) {
            getProvDiagnosis(buttons.stage);
            setStage(buttons.stage)
        }
        else if (buttons.stage == 3) {
            getProvDiagnosis(buttons.stage);
            setStage(buttons.stage)
        }
    }

    return (
        <View style={{ flex: 1 }}>
            {isLoading ? <Loader displaytext={true} /> : null}

            <View style={{ borderWidth: 0, width: '80%', justifyContent: 'center', alignItems: 'center', alignSelf: 'center' }}>
                <Text
                    adjustsFontSizeToFit
                    numberOfLines={2} style={{
                        alignSelf: 'center',
                        marginTop: normalize(-7),
                        fontSize: normalize(14),
                        fontWeight: 'bold',
                        textAlign: 'center',
                        marginBottom: normalize(5)
                    }}>
                    {isNU(props.data) && isNU(props.data.displayvalue) ? props.data.displayvalue : ''}{" Templates"}
                </Text>
            </View>

            <View style={{ flex: 1 }}>
                <View style={{ flex: 1, width: '100%' }}>

                    <View style={getOverlayScreenContainer()}>
                        <SSearchBar
                            onChangeText={val => setSearchData(val)} />
                    </View>
                    <View style={{ flexDirection: 'row', justifyContent: 'space-between', flex: 1 }}>
                        <View style={getOverlayScreenChildContainer()}>
                            {GetSearchData(alphaFilter ? filterPurpose : displayData)}
                        </View>
                        <View>
                            <SAlphabet
                                callBack={val => val == undefined ? null : getAlphabetData(val.alpha, val.index)}
                            />
                        </View>
                    </View>
                    <CFooterView style={{ width: Dimensions.get('screen').width - normalize(15), backgroundColor: "#fff" }}>
                        <View style={{ flexDirection: 'row' }}>
                            {[{
                                "displaytext": "Select",
                                "iconcolor": Global.AppTheme.primary_color,
                                "fontcolor": Global.AppTheme.primary_color,
                                "shadowcolor": '#f1f3f6',
                                "size": 10,
                                "iconname": "file-import",
                                "selected": false,
                                "visibility": stage == 1 ? true : false,
                                "iconsize": 20,
                                "functionid": "AD01"
                            }
                                // {
                                //     "displaytext": "Delete",
                                //     "iconcolor": Global.AppTheme.primary_color,
                                //     "fontcolor": "red",
                                //     "shadowcolor": '#f1f3f6',
                                //     "size": 10,
                                //     "iconname": "trash",
                                //     "selected": false,
                                //     "visibility": stage == 1 ? true : false,
                                //     "iconsize": 20,
                                //     "functionid": "AD02"
                                // }
                            ].map((item, i) => {
                                return (
                                    <View key={i} style={{ width: normalize(58), borderRadius: normalize(10) }}>
                                        {item.visibility ?
                                            <CAwesomeButton
                                                data={item}
                                                callBack={val => val == undefined ? null : getFooterFunctions(item, val)}
                                            />
                                            : null}
                                    </View>
                                )
                            })}
                        </View>
                    </CFooterView>
                </View>
            </View>

        </View>
    )
}

const layoutstyles = StyleSheet.create({
    overlay_screen_listview_container: {
        marginBottom: 10,
        flex: 1
    },
    collapseheader_text: {
        fontSize: normalize(11),
        margin: 2,
        paddingLeft: 5,
    },
    collapsebody_text: {
        fontSize: normalize(10),
        margin: 2,
        paddingLeft: 5,
    },

    overlay_searchTextbox_View: {
        width: '96%',
    },
    collapse_header: {
        backgroundColor: '#F0F0F0',
        flexDirection: 'row',
        justifyContent: 'flex-start',
        alignContent: 'center',
        alignItems: 'center',
        borderRadius: 7,
        marginLeft: 0,
    },
    textinput_view: {
        flex: 1,
        paddingLeft: '1%',
    },
    overwrite_child_container: {
        flexDirection: 'column',
        flex: 1,
    },
    overwrite_left_container: {
        flex: 1,
        justifyContent: 'center',
    },
    overwrite_right_container: {
        flex: 1,
        justifyContent: 'space-around',
        flexDirection: 'row',
        alignContent: 'center',
        alignItems: 'center',
    },
    overwrite_right_container_text: {},
    overwrite_left_container_text: {
        fontSize: normalize(11),
        fontWeight: '300',
        color: colors.color_SelectText,
    },
});


