import React, { useState } from 'react';
import { View, Text, TouchableOpacity, Image, StyleSheet, ActivityIndicator, Alert } from 'react-native';
import Icon from 'react-native-vector-icons/Feather';
import { APIURL } from '../Common/apiConstants'; // Import your API URL
import Icons from '../Common/Icons';
import { normalize } from '../CommonStyle/componentStyle';

/**
 * Helper function to construct image URL from filename
 */
const getImageUrl = (fileName) => {
  if (!fileName) return null;
  return `${APIURL}bldfile/filedownload/patientprofile?filename=${fileName}`;
};

/**
 * PhotoUpload component with local + backend preview and upload status
 */
const PhotoUpload = ({ photo, onChoosePhoto, onTakePhoto, uploadedFileName, getText, }) => {
  const [imageLoading, setImageLoading] = useState(false);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [imageError, setImageError] = useState(false);


  // Handle photo preview click
  const handlePhotoPreviewClick = () => {
    if (photo || uploadedFileName) {
      // If photo exists, show it (you can implement a full-screen viewer here)
      console.log('Photo exists, would show full screen viewer');
      // For now, just show an alert or you can implement a modal image viewer
      Alert.alert(
        'Photo Options',
        'What would you like to do?',
        [
          {
            text: 'Take New Photo',
            onPress: onTakePhoto,
          },
          {
            text: 'Choose from Gallery',
            onPress: onChoosePhoto,
          },
          {
            text: 'Cancel',
            style: 'cancel',
          },
        ]
      );
    } else {
      // If no photo exists, open camera directly
      onTakePhoto();
    }
  };

  return (
    <View style={styles.photoUploadContainer}>
      {/* Main photo preview circle - Make it clickable */}
      <View style={styles.photoPreviewContainer}>
        <TouchableOpacity
          style={styles.photoWrapper}
          onPress={handlePhotoPreviewClick}
          activeOpacity={0.7}
        >
          {photo ? (
            // Always show local photo immediately (fast preview)
            <Image
              source={{ uri: photo.uri }}
              style={styles.roundPhotoPreview}
              resizeMode="cover"
            />
          ) : uploadedFileName ? (
            // Fallback: show retrieved image from backend
            <>
              <Image
                source={{ uri: getImageUrl(uploadedFileName) }}
                style={styles.roundPhotoPreview}
                resizeMode="cover"
                onLoadStart={() => {
                  console.log('🔄 Starting to load image from backend...');
                  setImageLoading(true);
                  setImageLoaded(false);
                  setImageError(false);
                }}
                onLoad={() => {
                  console.log('✅ Image retrieved and loaded successfully from backend!');
                  setImageLoading(false);
                  setImageLoaded(true);
                  setImageError(false);
                }}
                onError={(error) => {
                  console.log('❌ Failed to load image from backend:', error.nativeEvent.error);
                  setImageLoading(false);
                  setImageLoaded(false);
                  setImageError(true);
                }}
                onLoadEnd={() => {
                  console.log('🏁 Image loading process completed');
                  setImageLoading(false);
                }}
              />

              {/* Loading indicator overlay */}
              {imageLoading && (
                <View style={styles.loadingOverlay}>
                  <ActivityIndicator size="small" color="#0066cc" />
                  <Text style={styles.loadingText}>Loading...</Text>
                </View>
              )}

              {/* Error overlay */}
              {imageError && (
                <View style={styles.errorOverlay}>
                  <Icon name="alert-circle" size={16} color="#fff" />
                  <Text style={styles.errorOverlayText}>Error</Text>
                </View>
              )}

              {/* Success indicator */}
              {imageLoaded && !imageLoading && (
                <View style={styles.successBadge}>
                  <Icon name="check" size={12} color="#fff" />
                </View>
              )}
            </>
          ) : (
            // Placeholder - shows camera icon indicating it's clickable
            <View style={styles.photoPlaceholderRound}>
              <Icons.Entypo name="camera" size={24} color="#094485" />
              <Text style={styles.placeholderText}>{getText('takephoto')}</Text>
            </View>
          )}

          {/* Upload status overlay for local photos */}

          {photo && photo.isUploading && (
            <View style={[styles.uploadStatusBadge, styles.uploadingBadge]}>
              <Text style={styles.uploadStatusText}>⏳</Text>
            </View>
          )}
          {photo && photo.uploadFailed && (
            <View style={[styles.uploadStatusBadge, styles.errorBadge]}>
              <Text style={styles.uploadStatusText}>❌</Text>
            </View>
          )}


        </TouchableOpacity>
      </View>

      {/* Action buttons */}
      <View style={styles.photoActionButtons}>
        <TouchableOpacity style={styles.photoActionButton} onPress={onChoosePhoto}>
          <Icons.MaterialIcons name="photo-library" size={20} color="#094485" />
          <Text style={styles.actionButtonText}>{getText("gallery")}</Text>
        </TouchableOpacity>

        <TouchableOpacity style={styles.photoActionButton} onPress={onTakePhoto}>
          <Icons.FontAwesome5 name="camera" size={20} color="#094485" />
          <Text style={styles.actionButtonText}>{getText("camera")}</Text>
        </TouchableOpacity>
      </View>

      {/* Detailed status text */}
      <Text style={styles.photoStatusText}>
        {photo && photo.isUploaded ? null :
          photo && photo.isUploading ? 'Uploading photo...' :
            photo && photo.uploadFailed ? null :
              photo ? 'photo preview' :
                imageLoading ? '🔄 Loading image' :
                  imageLoaded ? '✅ Image retrieved successfully' :
                    imageError ? 'Failed to load image' :
                      uploadedFileName ? null :
                        null}
      </Text>

      {/* Debug info (remove in production) */}
      {uploadedFileName && !photo && (
        <Text style={styles.debugText}>
          Backend URL: {getImageUrl(uploadedFileName)}
        </Text>
      )}
    </View>
  );
};

