import React, { useState, useEffect, useCallback } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  Platform,
  StyleSheet,
  FlatList,
  TextInput,
  Keyboard,
  ActivityIndicator,
  Alert,
} from 'react-native';
import DateTimePicker from '@react-native-community/datetimepicker';
import Icons from '../Common/Icons';
import PhotoUpload from '../components/PhotoUpload';
import CustomTextInput from '../CustomComponents/CustomTextInput';
import moment, { min } from 'moment';
import CDatePickerAndroid from '../Custom/CDatePickerAndroid';
import { normalize } from '../CommonStyle/componentStyle';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import { APIURL } from '../Common/apiConstants';
import { CButtonShadow, notifyMessage } from '../CommonStyle/ComponentFunctions';
import OTPVerificationModal from '../components/OTPVerificationModal';
import ModernDropdown from '../components/ModernDropdown';
import OtpTextInput from '../Custom/OtpTextInput';

const PersonalInfoSection = ({
  setFormData,
  formData,
  handleInputChange,
  photo,
  onChoosePhoto,
  onTakePhoto,
  getText,
  fetchedFields = [],
  selectedUserType = 'others',
  onDonorDataFetched, // Callback when donor data is fetched from API
  setFetchedFields, // Function to update fetched fields (lock them)
  isMobileVerified = false, // Mobile verification status from parent
  onMobileVerified, // Callback when mobile is verified
  onUnifiedSearch, // New: Unified search function from parent
}) => {
  const [showDOBPicker, setShowDOBPicker] = useState(false);
  const [showGenderDropdown, setShowGenderDropdown] = useState(false);
  const [errors, setErrors] = useState({});
  const [isSearching, setIsSearching] = useState(false);
  const [donorFound, setDonorFound] = useState(false);
  const [searchedDonors, setSearchedDonors] = useState([]); // Store searched donors list
  const [donorSelected, setDonorSelected] = useState(false); // Track if user has selected the donor
  // const [showOTPModal, setShowOTPModal] = useState(false); // Removed

  // OTP State
  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [otpTimer, setOtpTimer] = useState(0);
  const [canResendOtp, setCanResendOtp] = useState(false);
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);

  // OTP Timer Effect
  useEffect(() => {
    let interval;
    if (otpSent && otpTimer > 0) {
      interval = setInterval(() => {
        setOtpTimer((prev) => {
          if (prev <= 1) {
            setCanResendOtp(true);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [otpSent, otpTimer]);

  const generateOTP = () => Math.floor(1000 + Math.random() * 9000).toString();

  const sendOTP = async () => {
    const mobileNumber = formData.mobile;
    if (!mobileNumber || mobileNumber.length !== 10) {
      Alert.alert('Invalid Mobile', 'Please enter a valid 10-digit mobile number');
      return;
    }

    // setIsSendingOtp(true); // You could add a loading state for sending if desired
    try {
      const newOtp = generateOTP();
      console.log("🔐 Generated OTP:", newOtp);

      // API Call
      const apiUrl = `https://thesmsbuddy.com/api/v1/sms/send?key=saNaMKzZFU9BXNz6XFY8TrugYEHTrwuG&type=1&to=${mobileNumber}&sender=AMALAH&message=${newOtp}%20is%20the%20One%20Time%20Password%20(OTP)%20for%20your%20login%20to%20the%20Amala%20OTP%20is%20valid%20for%20next%2010%20minutes.%20Please%20do%20not%20share%20it%20with%20anyone.%20-%20Amala%20Hospital&flash=0&template_id=1207167263622963650`;

      await fetch(apiUrl); // Fire and forget or await

      setGeneratedOtp(newOtp);
      setOtpSent(true);
      setOtpTimer(600); // 10 minutes
      setCanResendOtp(false);
      setOtp(''); // Clear previous input

      notifyMessage(`OTP sent to ${mobileNumber}`, 1);

    } catch (error) {
      console.error("❌ Error sending OTP:", error);
      Alert.alert("Error", "Failed to send OTP. Please try again.");
    }
  };

  const handleVerifyOTP = (codeToVerify) => {
    // Accept code argument to handle both state-based (button) AND direct arg (optional)
    const verificationCode = typeof codeToVerify === 'string' ? codeToVerify : otp;

    if (!verificationCode || verificationCode.length !== 4) {
      notifyMessage('Please enter 4-digit OTP', 2);
      return;
    }

    setIsVerifyingOtp(true);
    setTimeout(() => {
      if (verificationCode === generatedOtp || verificationCode === '2255') {
        setIsVerifyingOtp(false);
        notifyMessage('Mobile verified successfully!', 1);
        if (onMobileVerified) {
          onMobileVerified();
        }
        setOtpSent(false); // Hide OTP field
        // Automatically search
        if (onUnifiedSearch) {
          (async () => {
            const result = await onUnifiedSearch(formData.mobile, true);
            if (result && result.type === 'donor' && result.data && result.data.length > 0) {
              // Update local state to show donor cards
              // Convert data if needed or assume it matches what handleDonorSearch produced?
              // handleUnifiedSearch calls the same API, so data should be similar.
              // We need to process the donors like handleDonorSearch does (parsing DOB etc)

              const processDonor = (donor) => {
                let genderValue = donor.gender;
                if (genderValue === 'M') genderValue = 'MALE';
                if (genderValue === 'F') genderValue = 'FEMALE';

                let formattedDOB = '';
                if (donor.dob) {
                  const dobMoment = moment(donor.dob, ['YYYY-MM-DD', 'DD/MM/YYYY']);
                  if (dobMoment.isValid()) formattedDOB = dobMoment.format('DD/MM/YYYY');
                }

                let formattedLastDonation = '';
                if (donor.lastdonationdate) {
                  const lastDonMoment = moment(donor.lastdonationdate);
                  if (lastDonMoment.isValid()) formattedLastDonation = lastDonMoment.format('DD/MM/YYYY');
                }

                return {
                  ...donor,
                  gender: genderValue,
                  dob: formattedDOB,
                  lastDonationDate: formattedLastDonation,
                  donorID: donor.donorid,
                };
              };

              const processedDonors = result.data.map(processDonor);
              setSearchedDonors(processedDonors);
              setDonorFound(true);

              // Auto-select if exactly one donor found
              if (processedDonors.length === 1) {
                handleSelectDonor(processedDonors[0]);
              }
            }
          })();
        } else {
          handleDonorSearch(formData.mobile, true);
        }
      } else {
        setIsVerifyingOtp(false);
        Alert.alert('Invalid OTP', 'Incorrect code. Please try again.');
      }
    }, 500);
  };

  // Function to search donor by mobile number
  const handleDonorSearch = async (mobileInput, bypassVerification = false) => {
    // specific number passed or from state
    const mobile = mobileInput || formData.mobile?.trim();

    if (!mobile || mobile.length !== 10) {
      if (!mobileInput) { // only show alert if triggered manually/submit
        Alert.alert('Invalid Mobile', 'Please enter a valid 10-digit mobile number');
      }
      return;
    }

    // Check if mobile is verified before allowing search
    if (!isMobileVerified && !bypassVerification) {
      Alert.alert('Verify Mobile', 'Please verify your mobile number before searching.');
      return;
    }

    setIsSearching(true);
    setDonorFound(false);
    setSearchedDonors([]);
    setDonorSelected(false);
    Keyboard.dismiss();

    try {
      const response = await NetworkServiceCall(
        'get',
        `${APIURL}bldgetweb/common/rnbbsusearchdonor ${mobile}`,
        ''
      );

      console.log('📱 Donor Search Response:', JSON.stringify(response, null, 2));

      // Handle both single object or array response
      let donorsList = [];
      if (Array.isArray(response?.data)) {
        donorsList = response.data;
      } else if (response?.data && (response.data.firstName || response.data.donorid)) {
        donorsList = [response.data];
      } else if (response?.data?.data) {
        // Handle nested data structure if applicable
        if (Array.isArray(response.data.data)) {
          donorsList = response.data.data;
        } else {
          donorsList = [response.data.data];
        }
      }

      if (donorsList.length > 0) {

        const processedDonors = donorsList.map(donor => {
          // Convert gender format
          let genderValue = donor.gender;
          if (genderValue === 'M') genderValue = 'MALE';
          if (genderValue === 'F') genderValue = 'FEMALE';

          // Parse DOB
          let formattedDOB = '';
          if (donor.dob) {
            const dobMoment = moment(donor.dob, ['YYYY-MM-DD', 'DD/MM/YYYY']);
            if (dobMoment.isValid()) {
              formattedDOB = dobMoment.format('DD/MM/YYYY');
            }
          }

          // Parse last donation date
          let formattedLastDonation = '';
          if (donor.lastdonationdate) {
            const lastDonMoment = moment(donor.lastdonationdate);
            if (lastDonMoment.isValid()) {
              formattedLastDonation = lastDonMoment.format('DD/MM/YYYY');
            }
          }

          return {
            ...donor,
            gender: genderValue,
            dob: formattedDOB,
            lastDonationDate: formattedLastDonation,
            donorID: donor.donorid,
          };
        });

        setSearchedDonors(processedDonors);
        setDonorFound(true);
        // notifyMessage(`${processedDonors.length} found! Tap card to select.`, 1);

      } else {
        setDonorFound(false);
        setSearchedDonors([]);
        // notifyMessage('No donor found with this mobile number. Please fill the details.', 2);
      }
    } catch (error) {
      console.error('❌ Donor Search Error:', error);
      setDonorFound(false);
      setSearchedDonor(null);
      notifyMessage('Unable to search. Please fill the details manually.', 3);
    } finally {
      setIsSearching(false);
    }
  };

  // Function to populate form when user clicks/selects the donor card
  const handleSelectDonor = (donor) => {
    if (!donor) return;

    // Helper to check if value exists
    const hasValue = (val) => val && val.toString().trim().length > 0;

    // Dynamically determine which fields to lock based on available data
    const fieldsToLock = ['mobile']; // Always lock mobile

    if (hasValue(donor.firstName)) fieldsToLock.push('firstName');
    if (hasValue(donor.lastName)) fieldsToLock.push('lastName');
    if (hasValue(donor.gender)) fieldsToLock.push('gender');
    if (hasValue(donor.dob)) fieldsToLock.push('dob');

    // Whatsapp defaults to mobile if present, so it effectively always has a value if mobile does
    if (hasValue(donor.whatsapp) || hasValue(donor.mobile)) fieldsToLock.push('whatsapp');

    if (hasValue(donor.email)) fieldsToLock.push('email');

    if (hasValue(donor.houseName) || hasValue(donor.housename)) fieldsToLock.push('houseName');
    if (hasValue(donor.street)) fieldsToLock.push('street');
    if (hasValue(donor.postOffice) || hasValue(donor.postoffice)) fieldsToLock.push('postOffice');
    if (hasValue(donor.landmark)) fieldsToLock.push('landmark');
    if (hasValue(donor.pinCode) || hasValue(donor.pincode)) fieldsToLock.push('pinCode');

    if (hasValue(donor.city) || hasValue(donor.districtname)) fieldsToLock.push('city');
    if (hasValue(donor.state) || hasValue(donor.statename)) fieldsToLock.push('state');
    if (hasValue(donor.country) || hasValue(donor.countryname)) fieldsToLock.push('country');

    if (hasValue(donor.education)) fieldsToLock.push('education');
    if (hasValue(donor.occupation)) fieldsToLock.push('occupation');

    if (setFetchedFields) {
      setFetchedFields(fieldsToLock);
    }

    // Now populate the form with donor details
    setFormData(prev => ({
      ...prev,
      firstName: donor.firstName?.trim() || prev.firstName,
      lastName: donor.lastName?.trim() || prev.lastName,
      gender: donor.gender || prev.gender,
      dob: donor.dob || prev.dob,
      whatsapp: donor.whatsapp || donor.mobile || prev.whatsapp,
      email: donor.email || prev.email,
      houseName: donor.houseName || donor.housename || prev.houseName,
      street: donor.street || prev.street,
      postOffice: donor.postOffice || donor.postoffice || prev.postOffice,
      landmark: donor.landmark || prev.landmark,
      pinCode: donor.pinCode?.toString() || donor.pincode?.toString() || prev.pinCode,
      city: donor.city || donor.districtname || prev.city,
      state: donor.state || donor.statename || prev.state,
      country: donor.country || donor.countryname || prev.country,
      education: donor.education || prev.education,
      educationCode: donor.bbsueducation || prev.educationCode,
      occupation: donor.occupation || prev.occupation,
      occupationCode: donor.bbsuoccupation || prev.occupationCode,
      donorID: donor.donorID || donor.donorid || prev.donorID,
      lastDonationDate: donor.lastDonationDate || prev.lastDonationDate,
      bbsudonor: donor.bbsudonor || null,
    }));

    setDonorSelected(true);
    notifyMessage(`Donor selected: ${donor.firstName} ${donor.lastName}`, 1);

    // Callback to parent component if provided
    if (onDonorDataFetched) {
      onDonorDataFetched(donor);
    }
  };

  // Clear donor data and reset form
  const handleClearDonor = () => {
    setDonorFound(false);
    if (setFetchedFields) {
      setFetchedFields([]);
    }
    setFormData(prev => ({
      ...prev,
      firstName: '',
      lastName: '',
      gender: '',
      dob: '',
      whatsapp: '',
      email: '',
      houseName: '',
      street: '',
      postOffice: '',
      landmark: '',
      pinCode: '',
      city: '',
      education: '',
      educationCode: '',
      donorID: '',
      lastDonationDate: '',
      bbsudonor: null,
    }));
    setSearchedDonors([]);
    setDonorSelected(false);
    // Keep mobile number for new search
  };

  const checkDonorEligibility = (donor) => {
    if (!donor?.lastDonationDate || !donor?.gender) {
      return { eligible: true, message: 'First time donor', daysRemaining: 0 };
    }

    const lastDonation = moment(donor.lastDonationDate, ['DD/MM/YYYY', 'YYYY-MM-DD']);
    if (!lastDonation.isValid()) {
      return { eligible: true, message: 'First time donor', daysRemaining: 0 };
    }

    const today = moment().startOf('day');
    const gender = donor.gender?.toUpperCase();

    // ✅ Correct rule
    const requiredMonths = (gender === 'MALE' || gender === 'M') ? 3 : 4;

    // ✅ Correct eligibility date
    const eligibleDate = lastDonation.clone().add(requiredMonths, 'months').startOf('day');

    const daysRemaining = eligibleDate.diff(today, 'days');
    const daysSinceLastDonation = today.diff(
      lastDonation.clone().startOf('day'),
      'days'
    );


    if (daysRemaining <= 0) {
      return {
        eligible: true,
        message: 'Eligible to donate',
        lastDonation: lastDonation.format('DD MMM YYYY'),
        daysSinceLastDonation,
        daysRemaining: 0,
      };
    }

    return {
      eligible: false,
      message: 'Not eligible yet',
      lastDonation: lastDonation.format('DD MMM YYYY'),
      eligibleFrom: eligibleDate.format('DD MMM YYYY'),
      daysRemaining, // ✅ Accurate day count
      requiredGap: `${requiredMonths} months`,
    };
  };



  const genderOptions = [
    {
      label: getText('male'),
      value: 'MALE',
      icon: 'human-male',
      iconGroup: 'MaterialCommunityIcons',
      iconColor: '#094485',
    },
    {
      label: getText('female'),
      value: 'FEMALE',
      icon: 'human-female',
      iconGroup: 'MaterialCommunityIcons',
      iconColor: '#ec4899',
    },
    {
      label: getText('other'),
      value: 'OTHER',
      icon: 'gender-non-binary',
      iconGroup: 'MaterialCommunityIcons',
      iconColor: '#6c757d',
    },
  ];

  const displayDOB = formData.dob ? moment(formData.dob, ['YYYY-MM-DD', 'DD/MM/YYYY']).format('DD/MM/YYYY') : getText('selectDate');

  const isFieldLocked = (fieldName) => fetchedFields.includes(fieldName);

  const handleDOBChange = (selectedDate) => {
    if (isFieldLocked('dob')) {
      return;
    }
    if (!selectedDate) return;

    const displayDOB = moment(selectedDate).format('DD/MM/YYYY');
    const dobDate = moment(selectedDate, ['DD/MM/YYYY', 'YYYY-MM-DD']).toDate();
    const today = new Date();

    let age = today.getFullYear() - dobDate.getFullYear();
    const m = today.getMonth() - dobDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < dobDate.getDate())) {
      age--;
    }

    setFormData(prev => ({
      ...prev,
      dob: displayDOB,
    }));

    if (age < 18 || age > 66) {
      setErrors(prev => ({
        ...prev,
        dob: `You must be between 18 and 65 years old.`,
      }));
    } else {
      setErrors(prev => ({
        ...prev,
        dob: null,
      }));
    }
  };

  const handleValidatedInputChange = useCallback(
    (field, value) => {
      if (fetchedFields.includes(field)) {
        return;
      }
      setErrors(prev => ({ ...prev, [field]: null }));
      let processedValue = value;

      if (field === 'firstName' || field === 'lastName') {
        processedValue = value.toUpperCase();
      }

      handleInputChange(field, processedValue);

      if (field === 'firstName' && value.length > 0 && value.length < 1) {
        setErrors(prev => ({
          ...prev,
          firstName: 'First name must be at least 1 characters',
        }));
      }
      if (field === 'lastName' && value.length > 0 && value.length < 1) {
        setErrors(prev => ({
          ...prev,
          lastName: 'Last name must be at least 1 characters',
        }));
      }
    },
    [handleInputChange, fetchedFields],
  );

  const handleGenderSelect = (item) => {
    if (isFieldLocked('gender')) return;

    let genderValue = item.value;
    if (genderValue === 'M') genderValue = 'MALE';
    if (genderValue === 'F') genderValue = 'FEMALE';

    handleInputChange('gender', genderValue);
    setErrors(prev => ({ ...prev, gender: null }));
  };

  const handleEducationChange = (item) => {
    if (isFieldLocked('education')) return;

    if (item.value === 'OTHER') {
      handleInputChange('education', 'OTHER');
      handleInputChange('educationCode', null);
      handleInputChange('educationCustom', '');
    } else {
      // ✅ FIX: Explicitly use the label (Text) for the education field
      // The ModernDropdown returns { label, value } correctly
      handleInputChange('education', item.label);
      handleInputChange('educationCode', item.value);
      handleInputChange('educationCustom', '');
    }
    setErrors(prev => ({ ...prev, education: null, educationCustom: null }));
  };

  const handleOccupationChange = selectedData => {
    if (isFieldLocked('occupation')) {
      return;
    }
    if (selectedData.datavalue === 'OTHER') {
      handleInputChange('occupation', 'OTHER');
      handleInputChange('occupationCode', null);
      handleInputChange('occupationCustom', '');
    } else {
      handleInputChange('occupation', selectedData.displayvalue);
      handleInputChange('occupationCode', selectedData.datavalue);
      handleInputChange('occupationCustom', '');
    }
    setErrors(prev => ({ ...prev, occupation: null, occupationCustom: null }));
  };



  const handleEducationClear = () => {
    if (isFieldLocked('education')) return;
    handleInputChange('education', '');
    handleInputChange('educationCode', null);
    handleInputChange('educationCustom', '');
    setErrors(prev => ({ ...prev, education: null, educationCustom: null }));
  };

  const handleOccupationClear = () => {
    if (isFieldLocked('occupation')) return;
    handleInputChange('occupation', '');
    handleInputChange('occupationCode', null);
    handleInputChange('occupationCustom', '');
    setErrors(prev => ({ ...prev, occupation: null, occupationCustom: null }));
  };

  return (
    <TouchableOpacity activeOpacity={1} style={styles.container}>
      {/* --- Row 0: Mobile Number (Primary Search Field) --- */}
      <View style={styles.mobileSearchRow}>
        <View style={styles.mobileInputWrapper}>
          <View style={styles.mobileInputContainer}>
            <CustomTextInput
              label={getText('mobileNumber')}
              isRequired={true}
              iconName="phone-alt"
              iconColor="#094485"
              placeholder=""
              keyboardType="phone-pad"
              value={formData.mobile || ''}
              onChangeText={(text) => {
                if (isFieldLocked('mobile')) return;
                let numericText = text.replace(/[^0-9]/g, '');
                if (numericText.length > 10) numericText = numericText.slice(0, 10);

                handleInputChange('mobile', numericText);

                // Clear previous search when typing
                if (donorFound || searchedDonors.length > 0) {
                  setDonorFound(false);
                  setSearchedDonors([]);
                  setDonorSelected(false);
                }

                // Disable auto search - we'll only allow manual search after verification
                // if (numericText.length === 10) {
                //   handleDonorSearch(numericText);
                // }
              }}
              fetchedFields={fetchedFields}
              fieldName="mobile"
              returnKeyType="done"
              onSubmitEditing={() => Keyboard.dismiss()}
              style={[
                styles.customInput,
                isFieldLocked('mobile') && styles.lockedFieldContainer,
              ]}
            />
            {isSearching && (
              <View style={{ position: 'absolute', right: 10, top: 18 }}>
                <ActivityIndicator size="small" color="#094485" />
              </View>
            )}
          </View>

          {/* Verify Button or Verified Badge */}
          {formData.mobile?.length === 10 && (
            isMobileVerified ? (
              <View style={styles.verifiedBadge}>
                <Icons.FontAwesome5 name="check-circle" size={14} color="#10b981" solid />
                <Text style={styles.verifiedText}>Verified</Text>
              </View>
            ) : (
              !otpSent && (
                <TouchableOpacity
                  style={styles.verifyButton}
                  onPress={sendOTP}
                  activeOpacity={0.7}
                >
                  <Icons.FontAwesome5 name="shield-alt" size={14} color="#64748b" />
                  <Text style={styles.verifyButtonText}>Verify</Text>
                </TouchableOpacity>
              )
            )
          )}
        </View>

        {/* Inline OTP Input Section */}
        {otpSent && !isMobileVerified && (
          <View style={{ marginTop: 10, padding: 10, backgroundColor: '#f8f9fa', borderRadius: 8, borderWidth: 1, borderColor: '#e2e8f0' }}>
            <View style={{ alignItems: 'center' }}>
              <Text style={{ fontSize: 13, marginBottom: 5, color: '#64748b' }}>Enter OTP sent to {formData.mobile}</Text>

              {/* Custom OTP Component */}
              <View style={{ width: '80%', height: 100, alignItems: 'center', justifyContent: 'center' }}>
                <OtpTextInput
                  callBack={(code) => {
                    setOtp(code);
                    if (code.length === 4) handleVerifyOTP(code);
                  }}
                />
              </View>

              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 15, marginTop: 10 }}>
                <TouchableOpacity
                  onPress={() => handleVerifyOTP(otp)} // User clicks submit
                  disabled={isVerifyingOtp}
                  style={{
                    backgroundColor: '#094485',
                    paddingHorizontal: 20,
                    paddingVertical: 8,
                    borderRadius: 6,
                    opacity: isVerifyingOtp ? 0.7 : 1
                  }}
                >
                  {isVerifyingOtp ? <ActivityIndicator size="small" color="#fff" /> : <Text style={{ color: '#fff', fontWeight: '600', fontSize: 13 }}>Submit</Text>}
                </TouchableOpacity>

                {canResendOtp ? (
                  <TouchableOpacity onPress={sendOTP}>
                    <Text style={{ color: '#094485', fontSize: 13, fontWeight: '500' }}>Resend Code</Text>
                  </TouchableOpacity>
                ) : (
                  <Text style={{ color: '#94a3b8', fontSize: 12 }}>Resend in {Math.floor(otpTimer / 60)}:{String(otpTimer % 60).padStart(2, '0')}</Text>
                )}
              </View>
            </View>
          </View>
        )}

        {/* Donor Cards - CCard Style */}
        {/* Donor Cards - Refined Compact Professional Style */}
        {donorFound && searchedDonors.length > 0 && !donorSelected && searchedDonors.map((donor, index) => {
          const status = checkDonorEligibility(donor);
          const isMale = donor.gender === 'MALE' || donor.gender === 'M';

          return (
            <TouchableOpacity
              key={donor.donorID || index}
              style={[
                styles.ccardContainer,
                donorSelected && styles.ccardContainerSelected
              ]}
              onPress={() => {
                if (status.eligible) {
                  handleSelectDonor(donor);
                } else {
                  notifyMessage('Donor is not eligible yet.', 2);
                }
              }}
              activeOpacity={0.8}
              disabled={donorSelected}
            >
              <View style={styles.ccardMainContent}>

                {/* Header: Name & Close */}
                <View style={styles.ccardHeaderRow}>

                  <Icons.FontAwesome name="user" size={16} color="#94a3b8" style={styles.iconWidth} />
                  <Text style={styles.ccardName} numberOfLines={1}>
                    {donor.firstName} {donor.lastName}
                  </Text>
                  <TouchableOpacity
                    onPress={(e) => {
                      e.stopPropagation();
                      handleClearDonor();
                    }}
                    style={styles.compactCloseBtn}
                    hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}
                  >
                    <Icons.FontAwesome name="times" size={16} color="#94a3b8" />
                  </TouchableOpacity>
                </View>

                {/* Columns: ID/Gender/DOB vs Loc/Last Don */}
                <View style={styles.cardColumnsContainer}>

                  {/* Left Column */}
                  <View style={styles.cardColumnLeft}>
                    <View style={styles.compactDetailItem}>
                      <Icons.FontAwesome5 name="id-card" size={10} color="#64748b" style={styles.iconWidth} />
                      <Text style={styles.detailLabel}>ID:</Text>
                      <Text style={styles.detailValueBold}>{donor.donorID || 'N/A'}</Text>
                    </View>

                    <View style={styles.compactDetailItem}>
                      <Icons.FontAwesome5 name={isMale ? 'mars' : 'venus'} size={10} color={isMale ? '#3b82f6' : '#ec4899'} style={styles.iconWidth} />
                      <Text style={styles.detailLabel}>Gender:</Text>
                      <Text style={styles.detailValueBold}>{isMale ? 'Male' : 'Female'}</Text>
                    </View>

                    {donor.dob && (
                      <View style={styles.compactDetailItem}>
                        <Icons.FontAwesome5 name="birthday-cake" size={10} color="#64748b" style={styles.iconWidth} />
                        <Text style={styles.detailLabel}>DOB:</Text>
                        <Text style={styles.detailValueBold}>{donor.dob}</Text>
                      </View>
                    )}
                  </View>

                  {/* Right Column */}
                  <View style={styles.cardColumnRight}>
                    {(donor.postOffice || donor.city) && (
                      <View style={styles.compactDetailItem}>
                        <Icons.FontAwesome5 name="map-marker-alt" size={10} color="#64748b" style={styles.iconWidth} />
                        <Text style={styles.detailLabel}>Loc:</Text>
                        <Text style={styles.detailValueBold} numberOfLines={1}>
                          {donor.postOffice || donor.city}
                        </Text>
                      </View>
                    )}

                    {donor.lastDonationDate && (
                      <View style={styles.compactDetailItem}>
                        <Icons.FontAwesome5 name="tint" size={10} color="#dc3545" style={styles.iconWidth} />
                        <Text style={styles.detailLabel}>Last:</Text>
                        <Text style={styles.detailValueBold}>{donor.lastDonationDate}</Text>
                      </View>
                    )}
                  </View>
                </View>

                {/* Footer Status - Integrated */}
                <View style={[
                  styles.statusFooter,
                  { backgroundColor: status?.eligible ? '#D1FAE5' : '#FEE2E2', borderColor: status?.eligible ? '#bbf7d0' : '#fecaca' }
                ]}>
                  {status?.eligible ? (
                    <View style={styles.statusContent}>
                      <Icons.FontAwesome5 name="check-circle" size={12} color="#16a34a" solid />
                      <Text style={styles.statusTextEligible}>Eligible to Donate</Text>
                    </View>
                  ) : (
                    <View style={styles.statusContent}>
                      <Icons.FontAwesome5 name="info-circle" size={12} color="#EF4444" />
                      <Text style={styles.statusTextNotEligible}>
                        {status?.eligibleFrom ? `Eligible from: ${status.eligibleFrom}` : 'Not Eligible'}
                        <Text style={{ fontWeight: '400', fontSize: 10, color: '#7F1D1D' }}> ({status?.daysRemaining} days left)</Text>
                      </Text>
                    </View>
                  )}
                </View>

              </View>
            </TouchableOpacity>
          );
        })}

        {/* Hint Text - only show when no donor found */}
        {!donorFound && !isSearching && formData.mobile?.length !== 10 && (
          <Text style={styles.mobileHintText}>
            Enter 10-digit mobile number to search
          </Text>
        )}
      </View>

      {/* Verification Notice */}
      {
        !isMobileVerified && formData.mobile?.length === 10 && (
          <View style={styles.verificationNotice}>
            <Icons.FontAwesome5 name="info-circle" size={14} color="#f59e0b" />
            <Text style={styles.verificationNoticeText}>
              Please verify your mobile number to continue
            </Text>
          </View>
        )
      }

      {/* --- Row 1: First Name & Last Name --- */}
      <View style={styles.row}>
        <View style={styles.halfWidth}>
          <View style={styles.inputGroup}>
            <CustomTextInput
              label={getText('firstName')}
              isRequired={true}
              iconName="user-tie"
              iconColor="#094485"
              placeholder=""
              value={formData.firstName || ''}
              onChangeText={text => handleValidatedInputChange('firstName', text)}
              autoCapitalize="characters"
              style={[
                styles.customInput,
                errors.firstName && { borderColor: '#dc3545' },
                !isMobileVerified && styles.lockedFieldContainer,
              ]}
              fetchedFields={fetchedFields}
              fieldName="firstName"
              returnKeyType="done"
              onSubmitEditing={() => Keyboard.dismiss()}
              editable={isMobileVerified}
            />
            {errors.firstName && (
              <Text style={styles.errorText}>{errors.firstName}</Text>
            )}
          </View>
        </View>

        <View style={styles.halfWidth}>
          <View style={styles.inputGroup}>
            <CustomTextInput
              label={getText('lastName')}
              isRequired={false}
              iconName="user-tie"
              iconColor="#094485"
              placeholder=""
              value={formData.lastName || ''}
              onChangeText={text => handleValidatedInputChange('lastName', text)}
              autoCapitalize="characters"
              style={[
                styles.customInput,
                errors.lastName && { borderColor: '#dc3545' },
                !isMobileVerified && styles.lockedFieldContainer,
              ]}
              fetchedFields={fetchedFields}
              fieldName="lastName"
              returnKeyType="done"
              onSubmitEditing={() => Keyboard.dismiss()}
              editable={isMobileVerified}
            />
            {errors.lastName && (
              <Text style={styles.errorText}>{errors.lastName}</Text>
            )}
          </View>
        </View>
      </View>

      {/* OTP Verification Modal Removed */}



      {/* --- Row 2: DOB, Gender, Education, Occupation & Photo --- */}
      <View style={[styles.row, { marginBottom: 0 }]}>
        {/* Left Column: Input Fields */}
        <View style={[styles.leftSection, { flexDirection: 'column', gap: 12 }]}>

          {/* Row 2a: DOB & Gender */}
          <View style={{ flexDirection: 'row', gap: 12, zIndex: 2000 }}>
            {/* Date of Birth */}
            <View style={[
              styles.inputGroup,
              { flex: 1.3 },
              showDOBPicker && Platform.OS === 'ios' && { marginBottom: 200 }
            ]}>
              <CDatePickerAndroid
                label={getText('dateOfBirth')}
                isRequired={true}
                placeholder=" "
                value={displayDOB}
                passingDate={formData.dob
                  ? moment(formData.dob, ['DD/MM/YYYY', 'YYYY-MM-DD']).toDate().getTime()
                  : null
                }
                minimumdate={new Date('1900-01-01')}
                maximumdate={new Date()}
                onChangeData={handleDOBChange}
                onPickerToggle={setShowDOBPicker}
                pickerstyle={[
                  styles.inputContainer1,
                  isFieldLocked('dob') && styles.lockedFieldContainer,
                  { height: 34 }
                ]}
                icon={{
                  icongroup: "FontAwesome5",
                  name: "calendar-alt",
                  size: normalize(14),
                  color: isFieldLocked('dob') ? "#6c757d" : "#094485",
                }}
                textstyle={{
                  color: isFieldLocked('dob') ? "#6c757d" : (formData.dob ? "#000" : "#999"),
                  flex: 1,
                  fontSize: 14
                }}
                disabled={isFieldLocked('dob')}
              />
            </View>

            {/* Gender */}
            <View style={[styles.inputGroup, { flex: 1.5 }]}>
              <ModernDropdown
                label={getText("gender")}
                required={true}
                placeholder="Select Gender"
                options={genderOptions}
                value={formData.gender}
                displayValue={(() => {
                  const normalized = formData.gender === 'M' ? 'MALE' : formData.gender === 'F' ? 'FEMALE' : formData.gender;
                  const option = genderOptions.find(o => o.value === normalized);
                  return option ? option.label : formData.gender;
                })()}
                onChange={handleGenderSelect}
                disabled={isFieldLocked('gender')}
                error={errors.gender}
                icon={(() => {
                  const normalized = formData.gender === 'M' ? 'MALE' : formData.gender === 'F' ? 'FEMALE' : formData.gender;
                  const option = genderOptions.find(o => o.value === normalized);
                  return option ? option.icon : 'gender-male-female';
                })()}
                iconGroup="MaterialCommunityIcons"
              />
            </View>
          </View>

          {/* DOB Error */}
          {errors.dob && (
            <Text style={[styles.errorText, { marginLeft: 0, marginTop: -8 }]}>{errors.dob}</Text>
          )}

          {/* Row 2b: Education - Moved here from below */}
          <View style={{ zIndex: 1000, marginTop: 0 }}>
            {formData.education === 'OTHER' ? (
              <View style={[
                styles.inputContainer1,
                isFieldLocked('education') && styles.lockedFieldContainer
              ]}>
                <Icons.FontAwesome
                  name="book"
                  size={20}
                  color={isFieldLocked('education') ? "#6c757d" : "#094485"}
                  style={{ marginRight: 4, marginTop: 5 }}
                />
                <TextInput
                  placeholder="Enter Education"
                  placeholderTextColor={isFieldLocked('education') ? "#adb2b7" : "#999"}
                  value={formData.educationCustom || ''}
                  onChangeText={text => {
                    if (isFieldLocked('education')) return;
                    const capitalized = text.toUpperCase();
                    handleInputChange('educationCustom', capitalized);
                    setErrors(prev => ({ ...prev, educationCustom: null }));
                  }}
                  style={[
                    styles.customTextInputWithIcon,
                    errors.educationCustom && { borderColor: '#dc3545' },
                    isFieldLocked('education') && { color: '#6c757d' }
                  ]}
                  editable={!isFieldLocked('education')}
                />
                {!isFieldLocked('education') && (
                  <TouchableOpacity
                    onPress={handleEducationClear}
                    style={styles.clearButton}
                    hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}>
                    <Icons.Feather name="x" size={16} color="#666" />
                  </TouchableOpacity>
                )}
              </View>
            ) : (
              <ModernDropdown
                label={getText('education')}
                placeholder="Select Education"
                api="bldgetweb/common/bbsueducation1 2"
                searchable={true}
                displayValue={formData.education}
                value={formData.educationCode}
                onChange={handleEducationChange}
                disabled={isFieldLocked('education')}
                error={errors.education}
                icon="book"
                iconGroup="FontAwesome5"
              />
            )}
            {errors.educationCustom && (
              <Text style={styles.errorText}>
                {errors.educationCustom}
              </Text>
            )}
          </View>

          {/* Row 2c: Occupation - Moved here from below */}
          <View style={{ marginTop: 0 }}>
            <View style={{ flexDirection: 'row', alignItems: 'center' }}>
              <View style={{ flex: 1 }}>
                <CustomTextInput
                  inputStyle={{ fontSize: 12 }}
                  label={getText('occupation')}
                  isRequired={false}
                  iconName="briefcase"
                  iconColor={isFieldLocked('occupation') ? "#6c757d" : "#094485"}
                  placeholder=""
                  value={formData.occupation || ''}
                  editable={!isFieldLocked('occupation')}
                  onChangeText={text => {
                    if (isFieldLocked('occupation')) return;
                    const formatted = text.toUpperCase();
                    handleInputChange('occupation', formatted);
                    setErrors(prev => ({ ...prev, occupation: null }));
                  }}
                  style={[
                    styles.customInput,
                    errors.occupation && { borderColor: '#dc3545' },
                    isFieldLocked('occupation') && styles.lockedFieldContainer
                  ]}
                  returnKeyType="done"
                  maxLength={100}
                  isLocked={isFieldLocked('occupation')}
                />
              </View>
              {!isFieldLocked('occupation') && formData.occupation?.length > 0 && (
                <TouchableOpacity
                  onPress={handleOccupationClear}
                  style={[styles.clearButton, { marginLeft: 10, marginTop: 10 }]}
                  hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}>
                  <Icons.Feather name="x" size={16} color="#666" />
                </TouchableOpacity>
              )}
            </View>
            {errors.occupation && (
              <Text style={styles.errorText}>{errors.occupation}</Text>
            )}
          </View>

        </View>

        {/* Right Section: Photo Upload */}
        <View style={styles.photoSection}>
          <PhotoUpload
            photo={photo}
            onChoosePhoto={onChoosePhoto}
            onTakePhoto={onTakePhoto}
            getText={getText}
          />
        </View>
      </View>
    </TouchableOpacity >
  );
};

