import React, { useState, useEffect, useRef } from 'react';
import {
    View,
    Text,
    TouchableOpacity,
    Modal,
    FlatList,
    TextInput,
    StyleSheet,
    ActivityIndicator,
    Animated,
    Dimensions,
    Platform,
} from 'react-native';
import Icons from '../Common/Icons';
import { normalize } from '../CommonStyle/componentStyle';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import { APIURL } from '../Common/apiConstants';

const { height: SCREEN_HEIGHT } = Dimensions.get('window');

const ModernDropdown = ({
    label,
    value, // This can be the ID or the Display Text depending on usage. 
    // Ideally, for this app's pattern, 'value' passed in matches 'displayValue' prop of other components?
    // We'll stick to the pattern: value = what is currently selected (ID), displayValue = Text to show.
    // BUT PersonalInfoSection passes the TEXT as the main prop for display.
    // So we will maintain: value = ID (optional), displayValue = Text (Required for display)
    displayValue,
    placeholder = 'Select...',
    options = [], // Static options
    api = null, // API endpoint to fetch options
    onChange, // Returns { value, label, originalItem }
    icon = null,
    iconGroup = 'FontAwesome5',
    searchable = false,
    disabled = false,
    required = false,
    error = null,
    style,
    customRenderItem,
}) => {
    const [visible, setVisible] = useState(false);
    const [data, setData] = useState(options);
    const [loading, setLoading] = useState(false);
    const [searchText, setSearchText] = useState('');
    const [filteredData, setFilteredData] = useState([]);
    const [loadedFromApi, setLoadedFromApi] = useState(false);

    // Animation for modal
    const slideAnim = useRef(new Animated.Value(SCREEN_HEIGHT)).current;

    useEffect(() => {
        if (visible) {
            if (api && !loadedFromApi) {
                fetchData();
            } else if (!api) {
                // If static options change
                const formatted = formatOptions(options);
                setData(formatted);
                setFilteredData(formatted);
            }
            openModal();
        } else {
            closeModal();
        }
    }, [visible]);

    useEffect(() => {
        if (searchText) {
            const lower = searchText.toLowerCase();
            const filtered = data.filter(item =>
                item.label.toLowerCase().includes(lower)
            );
            setFilteredData(filtered);
        } else {
            setFilteredData(data);
        }
    }, [searchText, data]);

    const formatOptions = (rawOptions) => {
        return rawOptions.map(item => ({
            label: item.displayvalue || item.label || item.toString(),
            value: item.datavalue || item.value || item,
            icon: item.icon,
            iconColor: item.iconcolor,
            original: item
        }));
    };

    const fetchData = async () => {
        setLoading(true);
        try {
            // Handle the space in API URL if present (legacy code had "bbsueducation1 2")
            const safeApi = api.replace(' ', '%20');
            const response = await NetworkServiceCall('get', APIURL + safeApi, '');

            let items = [];
            if (response?.data?.data && Array.isArray(response.data.data)) {
                items = response.data.data.map(item => ({
                    label: item.datatext || item.name || 'Unknown',
                    value: item.code || item.id,
                    original: item
                }));
            }

            // Add "Other" option if dynamic
            items.push({ label: 'Other', value: 'OTHER', original: { datavalue: 'OTHER', displayvalue: 'Other' } });

            setData(items);
            setFilteredData(items);
            setLoadedFromApi(true);
        } catch (err) {
            console.error('Dropdown Fetch Error:', err);
        } finally {
            setLoading(false);
        }
    };

    const openModal = () => {
        Animated.spring(slideAnim, {
            toValue: 0,
            useNativeDriver: true,
        }).start();
    };

    const closeModal = () => {
        Animated.timing(slideAnim, {
            toValue: SCREEN_HEIGHT,
            duration: 250,
            useNativeDriver: true,
        }).start(() => setVisible(false));
    };


    const handleSelect = (item) => {
        onChange({
            value: item.value,
            label: item.label,
            originalItem: item.original
        });
        setVisible(false);
        setSearchText('');
    };

    const renderItem = ({ item }) => {
        const isSelected = displayValue === item.label;
        const itemIconGroup = item.iconGroup || iconGroup;

        return (
            <TouchableOpacity
                style={[styles.itemContainer, isSelected && styles.itemSelected]}
                onPress={() => handleSelect(item)}
            >
                <View style={styles.itemContent}>
                    {item.icon && (
                        itemIconGroup === 'FontAwesome5' ? (
                            <Icons.FontAwesome5
                                name={item.icon}
                                size={16}
                                color={item.iconColor || '#555'}
                                style={{ marginRight: 12 }}
                                solid
                            />
                        ) : (
                            <Icons.MaterialCommunityIcons
                                name={item.icon}
                                size={20}
                                color={item.iconColor || '#555'}
                                style={{ marginRight: 12 }}
                            />
                        )
                    )}
                    <Text style={[styles.itemText, isSelected && styles.itemTextSelected]}>
                        {item.label}
                    </Text>
                </View>

                {isSelected && (
                    <Icons.FontAwesome5 name="check" size={14} color="#094485" />
                )}
            </TouchableOpacity>
        );
    };

    return (
        <View style={[styles.container, style]}>
            {/* Trigger Button */}
            <TouchableOpacity
                style={[
                    styles.trigger,
                    disabled && styles.disabled,
                    error && styles.errorBorder,
                    visible && styles.focusedBorder
                ]}
                onPress={() => !disabled && setVisible(true)}
                activeOpacity={0.7}
                disabled={disabled}
            >
                {label && (
                    <View style={styles.labelContainer}>
                        <Text style={[styles.label, disabled && { color: '#6c757d' }]}>
                            {label}
                            {required && <Text style={{ color: '#dc3545' }}> *</Text>}
                        </Text>
                    </View>
                )}

                <View style={styles.triggerContent}>
                    {icon && (
                        <View style={styles.iconContainer}>
                            {iconGroup === 'FontAwesome5' ? (
                                <Icons.FontAwesome5 name={icon} size={16} color={disabled ? "#6c757d" : "#094485"} solid />
                            ) : (
                                <Icons.MaterialCommunityIcons name={icon} size={18} color={disabled ? "#6c757d" : "#094485"} />
                            )}
                        </View>
                    )}

                    <Text style={[
                        styles.valueText,
                        !displayValue && styles.placeholderText,
                        disabled && { color: '#6c757d' }
                    ]} numberOfLines={1}>
                        {displayValue || placeholder}
                    </Text>

                    <Icons.Feather name="chevron-down" size={18} color={disabled ? "#9ca3af" : "#6b7280"} />
                </View>
            </TouchableOpacity>

            {error && <Text style={styles.errorText}>{error}</Text>}

            {/* Modal */}
            <Modal
                visible={visible}
                transparent={true}
                animationType="none"
                onRequestClose={() => setVisible(false)}
            >
                <View style={styles.modalOverlay}>
                    <TouchableOpacity
                        style={styles.modalBackdrop}
                        activeOpacity={1}
                        onPress={() => setVisible(false)}
                    />

                    <Animated.View style={[
                        styles.modalContent,
                        { transform: [{ translateY: slideAnim }] }
                    ]}>
                        <View style={styles.modalHeader}>
                            <View style={styles.handleBar} />
                            <Text style={styles.modalTitle}>Select {label}</Text>
                            <TouchableOpacity style={styles.closeButton} onPress={() => setVisible(false)}>
                                <Icons.Feather name="x" size={20} color="#6b7280" />
                            </TouchableOpacity>
                        </View>

                        {searchable && (
                            <View style={styles.searchContainer}>
                                <Icons.Feather name="search" size={16} color="#9ca3af" style={styles.searchIcon} />
                                <TextInput
                                    style={styles.searchInput}
                                    placeholder="Search..."
                                    value={searchText}
                                    onChangeText={setSearchText}
                                    autoCapitalize="none"
                                />
                                {searchText.length > 0 && (
                                    <TouchableOpacity onPress={() => setSearchText('')}>
                                        <Icons.Feather name="x-circle" size={16} color="#9ca3af" />
                                    </TouchableOpacity>
                                )}
                            </View>
                        )}

                        {loading ? (
                            <View style={styles.centerContainer}>
                                <ActivityIndicator size="large" color="#094485" />
                            </View>
                        ) : (
                            <FlatList
                                data={filteredData}
                                renderItem={renderItem}
                                keyExtractor={(item, index) => item.value?.toString() || index.toString()}
                                contentContainerStyle={styles.listContent}
                                ListEmptyComponent={
                                    <View style={styles.centerContainer}>
                                        <Text style={styles.emptyText}>No options found</Text>
                                    </View>
                                }
                            />
                        )}
                    </Animated.View>
                </View>
            </Modal>
        </View>
    );
};

const styles = StyleSheet.create({
    container: {
        marginBottom: 0,
        width: '100%',
    },
    trigger: {
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: '#fff',
        borderWidth: 1,
        borderColor: '#E0E0E0',
        borderRadius: 8,
        height: 38, // Slightly taller for modern look
        paddingHorizontal: 12,
        marginTop: 6, // Space for floating label
    },
    focusedBorder: {
        borderColor: '#094485',
        elevation: 2,
        shadowColor: '#094485',
        shadowOpacity: 0.1,
        shadowRadius: 2,
    },
    errorBorder: {
        borderColor: '#dc3545',
    },
    disabled: {
        backgroundColor: '#f8f9fa',
        borderColor: '#d6d8db',
    },
    labelContainer: {
        position: 'absolute',
        top: -9,
        left: 8,
        backgroundColor: '#fff',
        paddingHorizontal: 4,
        zIndex: 1,
    },
    label: {
        fontSize: 11,
        color: '#094485',
        fontWeight: '600',
    },
    triggerContent: {
        flex: 1,
        flexDirection: 'row',
        alignItems: 'center',
    },
    iconContainer: {
        marginRight: 8,
        width: 20,
        alignItems: 'center',
    },
    valueText: {
        flex: 1,
        fontSize: 14,
        color: '#1f2937',
        fontWeight: '500',
    },
    placeholderText: {
        color: '#9ca3af',
        fontWeight: '400',
    },
    errorText: {
        color: '#dc3545',
        fontSize: 12,
        marginTop: 4,
        marginLeft: 4,
    },

    // Modal Styles
    modalOverlay: {
        flex: 1,
        backgroundColor: 'rgba(0,0,0,0.5)',
        justifyContent: 'flex-end',
    },
    modalBackdrop: {
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
    },
    modalContent: {
        backgroundColor: '#fff',
        borderTopLeftRadius: 20,
        borderTopRightRadius: 20,
        height: '60%',
        shadowColor: '#000',
        shadowOffset: { width: 0, height: -2 },
        shadowOpacity: 0.25,
        shadowRadius: 5,
        elevation: 5,
    },
    modalHeader: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'space-between',
        paddingHorizontal: 16,
        paddingVertical: 12,
        borderBottomWidth: 1,
        borderBottomColor: '#f3f4f6',
    },
    handleBar: {
        width: 40,
        height: 4,
        backgroundColor: '#e5e7eb',
        borderRadius: 2,
        position: 'absolute',
        top: 6,
        left: '50%',
        marginLeft: -20,
    },
    modalTitle: {
        fontSize: 16,
        fontWeight: 'bold',
        color: '#111827',
    },
    closeButton: {
        padding: 4,
    },
    searchContainer: {
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: '#f3f4f6',
        margin: 12,
        borderRadius: 8,
        paddingHorizontal: 10,
        height: 40,
    },
    searchIcon: {
        marginRight: 8,
    },
    searchInput: {
        flex: 1,
        fontSize: 14,
        color: '#1f2937',
        paddingVertical: 0,
    },
    listContent: {
        paddingBottom: 20,
    },
    itemContainer: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'space-between',
        paddingVertical: 14,
        paddingHorizontal: 16,
        borderBottomWidth: 1,
        borderBottomColor: '#f9fafb',
    },
    itemSelected: {
        backgroundColor: '#f0f9ff',
    },
    itemContent: {
        flexDirection: 'row',
        alignItems: 'center',
    },
    itemText: {
        fontSize: 15,
        color: '#374151',
    },
    itemTextSelected: {
        color: '#094485',
        fontWeight: '600',
    },
    centerContainer: {
        flex: 1,
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: 100,
    },
    emptyText: {
        color: '#9ca3af',
        fontSize: 14,
    },
});

export default ModernDropdown;
