import React, { useState, memo, useEffect, useContext } from 'react';
import { View, Dimensions, Text, TouchableOpacity } from 'react-native';
import Overlay from "react-native-modal-overlay";
import { APIURL } from '../Common/apiConstants';
import { Global } from '../Common/Global';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import { isBNUL, isNU, notifyMessage } from '../CommonStyle/ComponentFunctions';
import { normalize } from '../CommonStyle/componentStyle';
import InsureResponseComponentContext from '../Handlers/insureResponseComponentContext';
import Icons from '../Common/Icons';

export default function CConfirmation(props) {

  const [overlay, setOverlay] = useState(true)
  const { responseJSON, setResponseJSON } = useContext(InsureResponseComponentContext);
  const data = isNU(responseJSON) && isBNUL(responseJSON.consultation) ? responseJSON.consultation : [];

  function deleteClassificationNature() {

    var deleteItem = data.find(sitem => sitem.hosumrclassificationnature === props.keyid)

    var output = {};
    output.groups = {};
    output.groups.procedurename = "hosumrclassificationnnaturedelete1"
    output.groups.consultationdata = props.data.consultationdata
    output.groups.deleteArray = [deleteItem];

    let buttonapi = APIURL + 'commondelete/RnCommonDelete';
    console.log("deletebuttonapi", buttonapi)
    console.log("delete outputttttttttttttRRRRRRRRRRRRRRRRRRRRR", JSON.stringify(output))
    NetworkServiceCall("post", buttonapi, output)
      .then(function (response) {
        if (response.httpstatus == 200) {

          const updatedResponseJSON = {
            ...responseJSON,
            editStatus: true,
            consultation: [...responseJSON.consultation], // Clone the consultation array
          };
          updatedResponseJSON.consultation = updatedResponseJSON.consultation.filter(
            item => item.hosumrclassificationnature !== props.keyid
          );
          setResponseJSON(updatedResponseJSON);
          props.confirmation(false);
          notifyMessage("Deleted Successfully", 1);
        }
        else {
          notifyMessage("Delete Error,Please try again", 2)
        }
      })
  }

  function getPopupContainerStyle(height) {
    return {
      position: 'absolute',
      width: Dimensions.get('window').width,
      height: Dimensions.get('window').height * 0.20,
      borderBottomLeftRadius: 0,
      borderBottomRightRadius: 0,
      borderTopLeftRadius: 5,
      borderTopRightRadius: 5,
      borderWidth: 2,
      borderTopColor: 'darkblue',
      borderColor: '#fff',
      bottom: 0
    };
  }

  return (
    <Overlay
      visible={overlay}
      onClose={() => props.confirmation(false)}
      closeOnTouchOutside
      animationType="fadeInUp"
      containerStyle={{ backgroundColor: 'rgba(0, 0, 0, 0.40)' }}
      animationDuration={500}
      childrenWrapperStyle={getPopupContainerStyle(1000)}>
      <View style={{
        marginTop: normalize(-10),
        width: Dimensions.get('window').width - 10,
        height: Dimensions.get('window').height * 0.185,
        borderRadius: normalize(17),
      }}>
        <View style={{ flexDirection: 'row', alignItems: 'center' }}>
          <View style={{ width: '15%', alignItems: 'center', paddingLeft: normalize(5) }}>
            <Icons.FontAwesome5
              name={getObject(props.type).iconname}
              size={normalize(30)}
              color={'#FFCB08'}
            />
          </View>

          <View style={{ width: '85%', }}>
            <Text style={{ color: 'black', fontSize: normalize(14), fontWeight: '800' }}>{getObject(props.type).heading}</Text>
            <Text style={{ color: 'black', fontSize: normalize(14), fontWeight: '400', marginTop: normalize(10) }}>
              {getTextKey(props.type)}
            </Text>
          </View>
        </View>

        <View
          style={{
            flexDirection: 'row',
            width: '100%',
            justifyContent: 'flex-end',
            position: 'absolute', bottom: normalize(5), zIndex: 1,
            borderTopColor: 'lightgrey',
            borderTopWidth: 1,
          }}>

          <TouchableOpacity
            onPress={() => setOverlay(false, props.confirmation(false))}
            style={{
              backgroundColor: '#fff', borderRadius: normalize(7), width: normalize(75), justifyContent: 'center', alignItems: 'center',
              height: normalize(30), width: normalize(100), marginRight: normalize(10), marginTop: normalize(10),
              borderWidth: 1, borderColor: Global.AppTheme.primary_color,
            }}
          >
            <Text style={{ alignSelf: 'center', fontSize: normalize(12), color: Global.AppTheme.primary_color, fontWeight: 'bold' }}>
              {getObject(props.type).button1}
            </Text>
          </TouchableOpacity>

          <TouchableOpacity
            onPress={() => deleteClassificationNature()}
            style={{
              borderRadius: normalize(7), width: normalize(75), justifyContent: 'center', alignItems: 'center',
              height: normalize(30), width: normalize(100), marginRight: normalize(5), marginTop: normalize(10),
              borderWidth: 1,
              borderColor: Global.AppTheme.primary_color, backgroundColor: Global.AppTheme.primary_color,
            }}
          >
            <Text style={{ alignSelf: 'center', fontSize: normalize(12), color: "#fff", fontWeight: 'bold' }}>
              {getObject(props.type).button2}
            </Text>
          </TouchableOpacity>
        </View>

      </View>
    </Overlay>
  );

  function getTextKey(key) {
    switch (key) {
      case 1: return "Please enter installation key to continue."
      case 2: return "Please make sure data saved before verify, Are you sure you want to verify ?"
      case 3: return "Do you want share consent form?"
      case 4: return "Do you want to delete?"
      case 5: return "Hold On, Are you sure you want to exit without save ?"
      case 6: return "Hold on, Are you sure you want to log out ?"
      default: return "Do you want to exit ?"
    }
  }

  function getObject(key) {
    switch (key) {
      case 1: return { "iconname": "lock", "button1": "CANCEL", "button2": "CONFIRM", "heading": "INSTALLATION KEY" }
      case 2: return { "iconname": "save", "button1": "NO", "button2": "VERIFY", "heading": "VERIFICATION" }
      case 3: return { "iconname": "file-invoice", "button1": "NO", "button2": "YES", "heading": "DELETION" }
      case 4: return { "iconname": "trash", "button1": "NO", "button2": "YES", "heading": "DELETION" }
      case 5: return { "iconname": "exclamation-triangle", "button1": "NO", "button2": "YES", "heading": "EXIT WITHOUT SAVE ?" }
      case 6: return { "iconname": "exclamation-triangle", "button1": "NO", "button2": "YES", "heading": "LOG OUT" }
      default: return { "iconname": "exclamation-triangle", "button1": "NO", "button2": "YES", "heading": "CONFIRMATION" }
    }
  }
}
