import React, { useState, useEffect } from 'react';
import { View, Text, FlatList, Dimensions, TouchableOpacity, Platform } from 'react-native';
import { notifyMessage, Loader, isBNUL, isNU, CButtonShadow } from '../CommonStyle/ComponentFunctions';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import HOCIcons from '../HOC/HOCIcons';
import {
    MenuOption,
} from 'react-native-popup-menu';
import { normalize } from '../CommonStyle/componentStyle';
import HShadowButton from '../HOC/HShadowButton';
import { Global } from '../Common/Global';
import moment from 'moment';

export default function CDropDownList(props) {

    useEffect(() => {
        FetchDropdownList();
    }, [])

    const [loading, setLoading] = useState(false);
    const [displayData, setDisplayData] = useState([]);
    const [refresh, setRefresh] = useState(0);
    const [searchData, setSearchData] = useState('');

    function FetchDropdownList() {

        setDisplayData([]);
        setLoading(true);
        props.dropdownapi && props.dropdownapi != null && props.dropdownapi != undefined ?
            (console.log('CDropDownList props.dropdownapi', props.dropdownapi),
                NetworkServiceCall('get', props.dropdownapi, '').then(
                    function (response) {
                        // console.log('CDropDownList response', JSON.stringify(response))
                        if (
                            response.httpstatus &&
                            response.httpstatus != null &&
                            response.httpstatus != undefined &&
                            response.httpstatus == 200
                        ) {
                            setDisplayData(response.data.data);
                            setLoading(false);
                        } else {
                            notifyMessage('Data Not Found', 4);
                            setLoading(false);
                        }
                    },
                ))
            : props.dropdownarray && props.dropdownarray != null && props.dropdownarray != undefined ?
                (
                    // setDisplayData([]),
                    setTimeout(() => {
                        setDisplayData([...props.dropdownarray.data.data.map((val) => {
                            return {
                                ...val,
                                selected: false
                            }
                        })]);
                        setLoading(false);
                    })
                )
                :
                setLoading(false);
    }

    function insideView(data) {

        return (
            <>
                {data.item.hideicon ?
                    null
                    :
                    <HOCIcons.Icons
                        icongroup={isNU(data.item.icongroup) ? data.item.icongroup : 3}
                        name={data.item.icon ? data.item.icon : data.item.selected ? "radiobox-marked" : "circle-double"}//radiobox-marked
                        color={data.item.iconcolor ? data.item.iconcolor : 'black'}
                        size={isNU(data.item.iconsize) ? data.item.iconsize : normalize(20)}
                        style={{
                            marginRight: normalize(4),
                            borderWidth: 0,
                            textAlign: 'center'
                        }}
                    />
                }
                {data.item.badgenumber != null && data.item.badgenumber != undefined ?
                    <View style={{ borderWidth: 0, borderRadius: 100, height: normalize(14), width: normalize(14), position: 'absolute', backgroundColor: '#912c2c', right: 0, top: 0, justifyContent: 'center', alignItems: 'center' }}>
                        <Text style={{ fontSize: normalize(10), textAlign: 'center', color: 'white' }}>{data.item.badgenumber}</Text>
                    </View>
                    : null}

                <Text
                    style={{
                        borderWidth: 0,
                        fontWeight: data.item.selected ? 'bold' : 'normal',
                        fontSize: normalize(10),
                        color: 'black',
                        flex: 1
                    }}
                >
                    {data.item.displayvalue != null && data.item.displayvalue != undefined ? data.item.displayvalue.toUpperCase() : null}
                </Text>
                {props.selectbutton ?
                    <HOCIcons.Icons
                        icongroup={3}
                        name={data.item.selected ? "checkbox-marked" : "checkbox-blank-outline"}//radiobox-marked
                        color={data.item.selected ? 'green' : 'grey'}
                        size={isNU(data.item.iconsize) ? data.item.iconsize : normalize(15)}
                        style={{
                            marginRight: normalize(4),
                            borderWidth: 0,
                            textAlign: 'center'
                        }}
                    />
                    : null}
            </>
        )

    }

    function renderItem(data) {

        return (
            props.selectbutton ?
                <TouchableOpacity
                    onPress={() => {
                        data.item.selected = !data.item.selected;
                        setRefresh(refresh + 1);
                    }}
                    disabled={false}
                    style={{
                        paddingVertical: normalize(5),
                        borderWidth: 0.5,
                        borderColor: 'lightgrey',
                        flexDirection: 'row',
                        alignItems: 'center',
                        backgroundColor: data.item.selected ? "#766fff42" : "#ffffffc7"
                    }}
                >
                    {insideView(data)}
                </TouchableOpacity>
                :
                <MenuOption
                    onSelect={() => {
                        data.item.selected = true,
                            setRefresh(refresh + 1),
                            props.callback(data.item)
                    }}
                    disabled={false}
                    style={{
                        paddingVertical: normalize(2),
                        borderWidth: 0.5,
                        borderColor: 'lightgrey',
                        flexDirection: 'row',
                        alignItems: 'center'
                    }}
                >
                    {insideView(data)}
                </MenuOption>

        )
    }

    function fnCheckSelected(array) {
        let prevcodearray = isBNUL(array) ? array.filter((i, k) => { return i.selected ? { ...i } : undefined }) : [];
        let prevcode = isBNUL(prevcodearray) ? true : false;
        return prevcode;
    }

    function GetDropdown(data) {
        const newDropDownData = data != undefined
            ? data.filter(function (item) {
                const dataItem = item.displayvalue
                    ? item.displayvalue.toUpperCase()
                    : ''.toUpperCase();
                const textData = searchData.toUpperCase();
                return dataItem.indexOf(textData) > -1;
            })
            : null;

        return (
            <FlatList
                keyboardShouldPersistTaps={'handled'}
                data={newDropDownData}
                renderItem={renderItem}
                ListFooterComponent={(val) => {
                    return (
                        <>
                            {isNU(props.info) ?
                                <View style={{ marginTop: normalize(3), borderRadius: 5, borderWidth: 0, width: '100%', borderColor: 'lightgrey', flexDirection: 'row', alignItems: 'center', backgroundColor: 'white' }}>
                                    <HOCIcons.Entypo
                                        icongroup={5}
                                        name={"info-with-circle"}
                                        size={normalize(12)}
                                        color={"grey"}
                                        style={{ textAlign: 'center', padding: normalize(3), paddingLeft: normalize(8) }}
                                    />
                                    <Text adjustsFontSizeToFit style={{ width: '90%', color: 'grey', fontStyle: 'italic', fontSize: normalize(11), textAlign: 'left' }}>
                                        {" "}{isNU(props.info) ? props.info : null}
                                    </Text>
                                </View>
                                : null}
                            {props.selectbutton ?
                                <View
                                    style={{ justifyContent: 'center', alignItems: 'flex-start', }}>
                                    {fnCheckSelected(newDropDownData) ?
                                        <View style={{ backgroundColor: 'white' }}>
                                            <MenuOption
                                                onSelect={() => {
                                                    props.callback(displayData)
                                                }}>
                                                <HShadowButton
                                                    useicon={true}
                                                    usetext={true}
                                                    disabled={true}
                                                    buttonstyle={{
                                                        ...CButtonShadow(),
                                                        alignItems: 'center',
                                                        justifyContent: 'center',
                                                        borderWidth: 1,
                                                        borderColor: 'lightblue',
                                                        borderRadius: 10,
                                                        height: normalize(40),
                                                        width: normalize(50),
                                                        marginVertical: normalize(4),
                                                        marginHorizontal: normalize(4),
                                                        backgroundColor: 'white'
                                                    }}
                                                    iconcolor={Global.AppTheme.primary_color}
                                                    icongroup={1}
                                                    iconname={'select1'}
                                                    iconsize={normalize(22)}
                                                    displaytext={'Select'}
                                                    buttonCallback={() => {

                                                    }}
                                                    disabletextadjust={true}
                                                    textstyle={{
                                                        borderWidth: 0,
                                                        color: Global.AppTheme.primary_color,
                                                        fontSize: normalize(9),
                                                        textAlign: 'center',
                                                        alignSelf: 'center'
                                                    }}
                                                />


                                                {/* <HOCIcons.Icons
                                                    icongroup={1}
                                                    name={'select1'}
                                                    color={'darkblue'}
                                                    size={normalize(25)}
                                                />
                                                <Text style={{
                                                    fontSize: normalize(6),
                                                    fontWeight: 'bold',
                                                    color: 'darkblue',
                                                    textAlign: 'center'
                                                }} >Select</Text> */}

                                            </MenuOption>
                                        </View>
                                        :
                                        <View style={{
                                            height: Dimensions.get('screen').height * 0.06,
                                            width: Dimensions.get('screen').height * 0.06,
                                            marginVertical: normalize(4),
                                            marginHorizontal: normalize(4),
                                        }}>

                                        </View>
                                    }
                                </View>
                                : null}
                        </>
                    )
                }}
            // ListFooterComponent={() => {
            //     return (
            //         <>
            //             {isNU(props.info) ?
            //                 <View style={{ marginTop: normalize(3), borderRadius: 5, borderWidth: 0, width: '100%', borderColor: 'lightgrey', flexDirection: 'row', alignItems: 'center', backgroundColor: 'white' }}>
            //                     <HOCIcons.Entypo
            //                         icongroup={5}
            //                         name={"info-with-circle"}
            //                         size={normalize(12)}
            //                         color={"grey"}
            //                         style={{ textAlign: 'center', padding: normalize(3), paddingLeft: normalize(8) }}
            //                     />
            //                     <Text adjustsFontSizeToFit style={{ width: '90%', color: 'grey', fontStyle: 'italic', fontSize: normalize(11), textAlign: 'left' }}>
            //                         {" "}{isNU(props.info) ? props.info : null}
            //                     </Text>
            //                 </View>
            //             : null}
            //         </>
            //     )
            // }}
            // estimatedItemSize={normalize(25)}
            />
        );
    }

    if (Platform.OS === 'web') {
        const dataItems = displayData || (props.dropdownarray?.data?.data || []);

        return (
            <View style={{ borderWidth: 1, borderColor: '#ccc', borderRadius: 5, padding: 5, backgroundColor: 'white' }}>
                {React.createElement('select', {
                    style: {
                        width: '100%',
                        border: 'none',
                        outline: 'none',
                        fontSize: 14,
                        padding: 5,
                        backgroundColor: 'transparent'
                    },
                    onChange: (e) => {
                        const val = e.target.value;
                        const selectedItem = dataItems.find(i => i.value === val || i.datavalue === val || i.displayvalue === val) ||
                            { value: val, datavalue: val, displayvalue: val }; // Fallback

                        props.callback(selectedItem);
                    },
                    defaultValue: "" // Can manage value if prop passed, but callback handles update
                }, [
                    React.createElement('option', { value: "", disabled: true, key: 'placeholder' }, "Select..."),
                    ...dataItems.map((item, idx) =>
                        React.createElement('option', {
                            value: item.value || item.datavalue || item.displayvalue,
                            key: idx
                        }, item.displayvalue || item.label)
                    )
                ])}
            </View>
        );
    }

    return (
        <View style={{ borderWidth: 0.5, borderRadius: 5, borderColor: 'lightgrey', backgroundColor: 'white', }}>
            {loading ? <Loader /> : null}
            {isBNUL(displayData) ?
                GetDropdown(displayData)
                : null}
        </View>
    )
}