import React, { useState } from 'react';
import { View } from 'react-native'
import AntDesign from 'react-native-vector-icons/AntDesign';
import { normalize } from '../CommonStyle/componentStyle';
import CText from '../CustomComponents/CText';

const SCheckBox = (props) => {
    const [data, setData] = useState(props.data != undefined ? props.data : {
        value: false,
    })
    return (
        <View style={{ flexDirection: 'row', alignItems: 'center', }}>
            {data.displaytext != undefined ? <CText style={{ color: 'black', fontSize: normalize(14) }}>{data.displaytext}</CText> : null}
            <AntDesign name={data.value ? "checksquare" : "checksquareo"}
                size={normalize(data.size != undefined ? data.size : normalize(20))} color={data.value ? "darkblue" : "grey"}
                style={{ paddingHorizontal: 5, }}
                disabled={props.disabled != undefined ? props.disabled : false}
                onPress={() => { setData({ ...data, ['value']: !data.value }), props.callBack != undefined ? props.callBack(!data.value) : null }} />
        </View>
    )
}
export default SCheckBox;