import React, { memo, useMemo, useState, useEffect, useRef } from 'react';
import {
  Text,
  View,
  StyleSheet,
  TouchableHighlight,
  TouchableOpacity,
} from 'react-native';
import moment from 'moment';
import { useNavigation } from '@react-navigation/native';
import { SwipeRow } from 'react-native-swipe-list-view';

import { normalize } from '../CommonStyle/componentStyle';
import { Global } from '../Common/Global';
import HOCIcons from '../HOC/HOCIcons';
import { CButtonShadow, CShadowDynamic } from '../CommonStyle/ComponentFunctions';

// --- Configuration ---
const CARD_HEIGHT = normalize(55);

// --- Helper Functions ---

const formatBagType = (type) => {
  if (!type) return 'Blood Bag';
  const parts = type.split('_');
  const name = parts[0].replace('bag', '');
  const vol = parts[1] ? `${parts[1]}ml` : '';
  return `${name.charAt(0).toUpperCase() + name.slice(1)} ${vol}`;
};

/**
 * Logic for Separation Window (6 Hours from Collection)
 * Returns the countdown timer and the formatted collection timestamp.
 */
const getSeparationInfo = (collectionDateStr) => {
  if (!collectionDateStr) {
    return {
      timerLabel: 'No Date',
      timerColor: '#90A4AE',
      collectionLabel: 'N/A'
    };
  }

  const collectionDate = moment(collectionDateStr);
  const now = moment();

  // The separation deadline is exactly 6 hours after collection
  const deadline = collectionDate.clone().add(6, 'hours');

  // Calculate difference in seconds for precise timer
  const diffSeconds = deadline.diff(now, 'seconds');
  const absDiffSeconds = Math.abs(diffSeconds);

  const hours = Math.floor(absDiffSeconds / 3600);
  const minutes = Math.floor((absDiffSeconds % 3600) / 60);
  const seconds = absDiffSeconds % 60;

  // Format as H:MM:SS
  const formattedTime = `${hours}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  let timerLabel = '';
  let timerValue = formattedTime;
  let timerColor = '#388E3C'; // Default Green
  let icon = 'clock';
  let isExpired = false;

  if (diffSeconds < 0) {
    // Overdue
    timerLabel = 'Expired';
    timerValue = deadline.format('HH:mm');
    timerColor = '#D32F2F'; // Red
    icon = 'exclamation-circle';
    isExpired = true;
  } else {
    // Within Window - Show "Window" label
    timerLabel = 'Separation';
    timerValue = formattedTime;
    const diffMinutes = Math.floor(diffSeconds / 60);
    if (diffMinutes < 60) {
      timerColor = '#F57C00'; // Orange (Last hour warning)
      icon = 'hourglass-half';
    } else if (diffMinutes < 120) {
      timerColor = '#FFC107'; // Yellow (2 hour warning)
      icon = 'clock';
    }
  }

  return {
    timerLabel,
    timerValue,
    timerColor,
    icon,
    isExpired,
    collectionLabel: `Coll: ${collectionDate.format('DD MMM HH:mm')}`
  };
};

/**
 * Get status text split into individual letters for vertical display
 * Returns array in normal order so it reads correctly from top to bottom
 */
const getVerticalSpelling = (status) => {
  const normalizedStatus = status?.toUpperCase() || '';
  // Return array in normal order for top-to-bottom vertical display
  return normalizedStatus.split('').map(char => char.toUpperCase());
};

const getStatusColor = (status) => {
  const map = {
    BLED: '#6b758fff',        // Green
    DONATING: '#2196F3',    // Blue
    COLLECTED: '#9C27B0',   // Purple
    SEPARATING: '#FF9800',  // Orange
    COMPLETED: '#009688',   // Teal
    EXPIRED: '#D32F2F',     // Red
    ISSUED: '#607D8B',      // Blue Grey
  };
  return map[status?.toUpperCase()] || Global.AppTheme.primary_color;
};

// --- Main Component ---

// --- Timer Component (Extracted for Performance) ---
const TimerDisplay = memo(({ collectionDate }) => {
  const [_, setTick] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setTick(t => t + 1);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  const sepInfo = getSeparationInfo(collectionDate);

  return (
    <View style={styles.timerContainer}>
      <View style={styles.timerLabelRow}>
        <HOCIcons.FontAwesome5 name={sepInfo.icon} size={normalize(9)} color={sepInfo.timerColor} />
        <Text style={styles.timerLabel}>
          {sepInfo.timerLabel}
        </Text>
      </View>
      <Text style={[styles.timerValue, { color: sepInfo.timerColor }]}>
        {sepInfo.timerValue}
      </Text>
    </View>
  );
});

const BagCard = memo(({ data, onBagPress, actionLabel, onAction, slotNumber, isCanceled, onDelete, itemNumber, showVerificationButton }) => {
  const navigation = useNavigation();
  const item = Array.isArray(data) ? data[0] : data;

  const {
    donationid,
    bagno,
    batchno,
    bagtype,
    collectiontype,
    status,
    donationvolume,
    collectiondate,
    componentsSaved,
    componentsData,
    bloodgroup,
    abogroup,
    rhgroup,
  } = item;

  const displayBloodGroup = (abogroup && rhgroup) ? `${abogroup}${rhgroup}` : (bloodgroup || 'N/A');

  const getBloodGroupColor = (bg) => {
    if (!bg || bg === 'N/A') return '#64748b';
    const b = bg.toUpperCase();
    if (b.includes('+')) return '#dc2626';
    if (b.includes('-')) return '#2563eb';
    return '#64748b';
  };

  // Static Calculation for Panel Color (Updates on interaction/scroll instead of every second)
  // This drastically improves list performance
  const sepInfoForColor = useMemo(() => getSeparationInfo(collectiondate), [collectiondate]);
  const statusColor = componentsSaved ? '#10b981' : getStatusColor(status);
  const displayBagType = formatBagType(bagtype);
  const swipeRowRef = useRef(null);

  const snapToCenter = () => {
    if (swipeRowRef.current) {
      swipeRowRef.current.closeRow();
    }
  };

  const openLeftSwipe = () => {
    if (swipeRowRef.current) {
      swipeRowRef.current.manuallySwipeRow(100);
    }
  }

  // Get components summary text
  const componentsText = useMemo(() => {
    if (!componentsSaved || !componentsData || componentsData.length === 0) return null;
    return componentsData.map(c => `${c.componentname || c.name}`).join(' • ');
  }, [componentsSaved, componentsData]);

  return (
    <View style={styles.cardWrapper}>
      <SwipeRow
        ref={swipeRowRef}
        disableScrollOnSwipe={true}
        directionalDistanceChangeThreshold={1}
        swipeToOpenPercent={5}
        swipeToClosePercent={40}
        friction={10}
        tension={100}
        useNativeDriver={true}
        leftOpenValue={60}
        rightOpenValue={(onAction ? -60 : 0) + (onDelete ? -60 : 0)}
        stopLeftSwipe={100}
        stopRightSwipe={(onAction ? -80 : 0) + (onDelete ? -80 : 0)}
        disableLeftSwipe={false}
        disableRightSwipe={false}
      >
        {/* HIDDEN ROW (Back) */}
        <View style={styles.hiddenRow}>
          {/* Left Swipe Background (Info Only) */}
          <View style={[styles.hiddenSide, { alignItems: 'flex-start' }]}>
            <TouchableOpacity
              style={styles.swipeLeftAction}
              onPress={onBagPress ? () => onBagPress(item) : undefined}
            >
              <HOCIcons.FontAwesome5 name="info-circle" size={normalize(16)} color="#3b82f6" />
              <Text style={styles.swipeActionText}>Info</Text>
            </TouchableOpacity>
          </View>

          {/* Right Swipe Background (Result & Delete) */}
          <View style={[styles.hiddenSide, { alignItems: 'flex-end', flexDirection: 'row' }]}>
            {onAction && (
              <TouchableOpacity
                style={[styles.swipeLeftAction, { backgroundColor: componentsSaved ? '#dcfce7' : '#eff6ff', marginRight: normalize(4) }]}
                onPress={onAction}
              >
                <HOCIcons.FontAwesome5
                  name={componentsSaved ? "file-signature" : "flask"}
                  size={normalize(16)}
                  color={componentsSaved ? "#059669" : "#3b82f6"}
                />
                <Text style={[styles.swipeActionText, { color: componentsSaved ? "#059669" : "#3b82f6" }]}>
                  {componentsSaved ? "Edit" : "Result"}
                </Text>
              </TouchableOpacity>
            )}
            {onDelete && (
              <TouchableOpacity
                style={[styles.swipeLeftAction, { backgroundColor: '#fee2e2', marginRight: normalize(6) }]}
                onPress={onDelete}
              >
                <HOCIcons.FontAwesome5 name="trash-alt" size={normalize(14)} color="#ef4444" />
                <Text style={[styles.swipeActionText, { color: '#ef4444' }]}>Delete</Text>
              </TouchableOpacity>
            )}
          </View>

        </View>

        {/* VISIBLE ROW (Front) */}
        <TouchableHighlight
          style={[
            styles.cardSurface,
            componentsSaved && styles.cardSurfaceCompleted,
            isCanceled && { opacity: 0.6 }
          ]}
          underlayColor={componentsSaved ? "#d1fae5" : "#FAFAFA"}
          activeOpacity={1}
          onPress={() => { }} // Disable main card click
        >
          <View style={styles.cardRow}>

            {/* 1. Left Section: Vertical Panel (Rotated Text) */}
            <TouchableOpacity style={[
              styles.leftPanel,
              { backgroundColor: isCanceled ? '#94a3b8' : (componentsSaved ? '#10b981' : (sepInfoForColor.isExpired ? '#D32F2F' : statusColor)) }
            ]}
              onPress={openLeftSwipe}
            >
              <HOCIcons.FontAwesome5
                name="chevron-left"
                size={normalize(12)}
                color="#999"
                style={{
                  left: normalize(11),
                  top: normalize(13)
                }}
              />
              <Text style={styles.verticalText}>
                {componentsSaved ? 'DONE' : (isCanceled ? 'CANCELED' : (sepInfoForColor.isExpired ? 'EXPIRED' : status))}
              </Text>
            </TouchableOpacity>

            {/* 2. Main Content Area */}
            <View style={styles.contentContainer}>

              {/* Top Row: Donation ID & Bag Meta */}
              <View style={styles.topRow}>
                <View style={styles.topLeft}>
                  <Text style={[styles.donationId, componentsSaved && styles.donationIdCompleted]}>{donationid}</Text>
                  <View style={styles.bagMetaRow}>
                    <Text style={styles.bagType}>{displayBagType}</Text>
                    <Text style={styles.dotSeparator}>•</Text>
                    <Text style={styles.bagVol}>{donationvolume}ml</Text>
                  </View>
                </View>

                {/* Top Right: Badges */}
                <View style={styles.topRight}>
                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
                    {itemNumber && (
                      <View style={styles.itemNumberBadge}>
                        <Text style={styles.itemNumberText}>#{itemNumber}</Text>
                      </View>
                    )}
                    {slotNumber && (
                      <View style={[styles.slotBadge, isCanceled && styles.slotBadgeCanceled, { marginBottom: 0 }]}>
                        <Text style={styles.slotBadgeText}>{`Slot ${slotNumber}`}</Text>
                      </View>
                    )}
                  </View>

                  {componentsSaved ? (
                    <View style={styles.completedBadge}>
                      <HOCIcons.FontAwesome5 name="check-circle" size={normalize(9)} color="#059669" style={{ marginRight: normalize(4) }} />
                      <Text style={styles.completedBadgeText}>SEPARATED</Text>
                    </View>
                  ) : (
                    <View style={styles.collectionBadge}>
                      <HOCIcons.FontAwesome5 name="syringe" size={normalize(9)} color="#3949AB" style={{ marginRight: normalize(4) }} />
                      <Text style={styles.collectionTypeText}>{collectiontype || 'WB'}</Text>
                    </View>
                  )}
                </View>
              </View>

              {/* Divider Line */}
              <View style={[styles.divider, componentsSaved && styles.dividerCompleted]} />

              {/* Separated Components Chips */}
              {componentsSaved && componentsData && componentsData.length > 0 && (
                <View style={styles.yieldContainer}>
                  <Text style={styles.yieldLabel}>Yield:</Text>
                  <View style={styles.chipsRow}>
                    {componentsData.map((comp, idx) => (
                      <View key={idx} style={styles.componentChip}>
                        <HOCIcons.FontAwesome5 name="tint" size={normalize(8)} color="#15803d" />
                        <Text style={styles.componentChipName}>
                          {comp.aliasname || (comp.componentname || comp.name || '').split(' ').map(w => w[0]).join('') || comp.code}
                        </Text>
                        <View style={styles.componentChipQty}>
                          <Text style={styles.componentChipQtyText}>{comp.quantity}ml</Text>
                        </View>
                      </View>
                    ))}
                  </View>
                </View>
              )}

              {/* Bottom Row: Details Grid */}
              <View style={styles.bottomRow}>

                {/* Col 1: Bag & Batch Identifiers */}
                <View style={styles.colLeft}>
                  <View style={styles.infoItem}>
                    <Text style={styles.label}>Bag:</Text>
                    <Text style={styles.value} numberOfLines={1}>{bagno}</Text>
                  </View>
                  <View style={styles.infoItem}>
                    <Text style={styles.label}>Batch:</Text>
                    <Text style={styles.value} numberOfLines={1}>{batchno}</Text>
                  </View>
                </View>

                {displayBloodGroup && displayBloodGroup !== 'N/A' && (
                  <View style={styles.bloodGroupBadge}>
                    <Text style={[styles.bloodGroupText, { color: getBloodGroupColor(displayBloodGroup) }]}>
                      {displayBloodGroup}
                    </Text>
                  </View>
                )}

                {/* Col 3: Timer OR Action Button */}
                <View style={styles.colRight}>
                  {!onAction ? (
                    <>
                      <TimerDisplay collectionDate={collectiondate} />
                      <Text style={styles.collectionDateText}>{sepInfoForColor.collectionLabel}</Text>
                    </>
                  ) : (
                    // ADD THIS BLOCK to render the button
                    showVerificationButton && (

                      <TouchableOpacity
                        style={[
                          styles.actionButton,
                          { backgroundColor: actionLabel === 'Verify' ? '#4f46e5' : '#3b82f6' }, // Indigo for Verify
                          componentsSaved && styles.actionButtonCompleted
                        ]}
                        onPress={onAction}
                        activeOpacity={0.7}
                      >
                        <View style={styles.actionIconContainer}>
                          <HOCIcons.FontAwesome5
                            name={actionLabel === 'Verify' ? 'check-double' : (componentsSaved ? "file-signature" : "flask")}
                            size={normalize(10)}
                            color="#fff"
                          />
                        </View>
                        <Text style={styles.actionButtonText}>{actionLabel || "Action"}</Text>
                      </TouchableOpacity>
                    )

                  )}

                </View>

              </View>
            </View>
            <TouchableOpacity style={styles.rightChevronContainer}
              onPress={snapToCenter}
            >
              <HOCIcons.FontAwesome5
                name="chevron-right"
                size={normalize(12)}
                color="#cbd5e1"
                style={{
                  top: normalize(2),
                }}
              />
            </TouchableOpacity>
          </View>
        </TouchableHighlight>
      </SwipeRow>
    </View>
  );
});

