import React, { useContext, useState } from 'react';
import { StyleSheet, View, ImageBackground, Text } from 'react-native';
import { Global } from '../Common/Global';
import { useNavigation } from '@react-navigation/native';
import CCard from '../Custom/CCard';
import { normalize } from '../CommonStyle/componentStyle';
import { isNU } from '../CommonStyle/ComponentFunctions';
import CTemplateCard from '../Custom/CTemplateCard';
import AppContext from '../Handlers/AppContext';

const CDetailView = (props) => {


    const styles = StyleSheet.create({
        CDetailView: {
            flex: 1,
            shadowColor: '#000',
            shadowOffset: { width: 0, height: 2 },
            shadowOpacity: 0.8,
            shadowRadius: 2,
            borderTopLeftRadius: 20,
            borderTopRightRadius: 20,
            width: '100%',
            backgroundColor: props.backgroundColor ? props.backgroundColor : 'white'
        },
        image: {
            flex: 1
        }
    });

    // console.log("PATIENT DATATTTTTTATTATTATTATATATATTATATAAT",JSON.stringify(Global.PatientDetails))
    const [patientdata] = useState(Global.PatientDetails)
    const [userListShow] = useState(props.userlist != undefined ? props.userlist : true)
    const { inputText, setInputText } = useContext(AppContext);

    const navigation = useNavigation();
    return (
        <View style={styles.CDetailView}>
            {/* {console.log('patientdata----------',JSON.stringify(patientdata))} */}
            <ImageBackground
                source={props.bgimage != undefined ? { uri: props.bgimage } : require('../Asset/images/IMA.png')}
                resizeMode={props.bgimage != undefined ? "stretch" : "contain"}
                imageStyle={props.bgimage != undefined ? { opacity: 1 } : { opacity: 0.1 }}
                style={styles.image}
            >
                {patientdata != null
                    && patientdata != undefined && userListShow && !props.hideCard ?
                    <View style={{ marginHorizontal: normalize(5), marginTop: normalize(-30) }}>
                        <CCard
                            navigation={navigation}
                            type={2}
                            disableTouch={true}
                            data={[Global.PatientDetails]}
                            consultation={props.consultation ? true : false}
                            expandheight={normalize(100)}
                            disabledetailcard={props.disabledetailcard ? true : false}
                            disabledetailcardcallback={() => {
                                // console.log('kkkk')
                                isNU(props.disabledetailcardcallback) ? props.disabledetailcardcallback(true) : null
                            }}
                        />
                    </View> : null}
                {isNU(inputText) && isNU(inputText.templatedata) && inputText.showtemplatecard && props.showTemplateCard ?
                    <View style={{ marginTop: normalize(-10) }}>
                        <CTemplateCard
                            data={inputText.templatedata}
                            Cardcallback={(val) => {
                                console.log('Cardcallback.....')
                            }}
                        />
                    </View> : null}
                {props.children}
            </ImageBackground>
        </View>
    );
};



export default CDetailView;