import React, { useState, useRef, useEffect } from 'react';

import {
  SafeAreaView,
  StyleSheet,
  View,
  StatusBar,
  Platform,
  DeviceEventEmitter,
} from 'react-native';

import Navigation from './src/Navigation/PageNavigation';
import { MenuProvider } from 'react-native-popup-menu';
import { LogBox } from 'react-native';
import SSearchBar from './src/StaticComponents/SSearchBar';
import COverlay from './src/CustomComponents/COverlay';
import { InsureResponseComponentProvider } from './src/Handlers/insureResponseComponentContext';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { Global } from './src/Common/Global';
import { getAppVersion, normalize } from './src/CommonStyle/ComponentFunctions';
import Loader from './src/Custom/Loader';
import AAlert from './src/Alerts/AAlert';
import AAlertIOS from './src/Alerts/AAlertIOS';
import ErrorBoundary from './src/Common/ErrorBoundary';
import { AppProvider } from './src/Handlers/GlobalContext';
// GestureHandlerRootView may not work on web, use View as fallback
let GestureHandlerRootView;
try {
  GestureHandlerRootView = require('react-native-gesture-handler').GestureHandlerRootView;
} catch (e) {
  GestureHandlerRootView = View;
}
if (!GestureHandlerRootView) {
  GestureHandlerRootView = View;
}
import { ContextBioProvider } from './src/Handlers/ContextBio';
import { QuestionBuilderProvider } from './src/Quesitons/QuestionBuilderContext';
import EmrResponseComponentContext, { EmrResponseComponentProvider } from './src/Handlers/emrResponseComponentContext';
import { STemplateProvider } from './src/Handlers/sTemplateContext';
import DashboardSimple from './src/componentseperation/Demo/DemoDashboard';
import NotificationService from './src/Services/NotificationService';

LogBox.ignoreLogs(['Warning: ...']); // Ignore log notification by message
LogBox.ignoreAllLogs(); //Ignore all log notifications
LogBox.ignoreLogs([
  "[react-native-gesture-handler] Seems like you're using an old API with gesture components, check out new Gestures system!",
]);
LogBox.ignoreLogs([
  "DatePickerIOS has been merged with DatePickerAndroid and will be removed in a future release. It can now be installed and imported from '@react-native-community/datetimepicker' instead of 'react-native'. See https://github.com/react-native-datetimepicker/datetimepicker",
]);
LogBox.ignoreLogs([
  'Warning: componentWillReceiveProps has been renamed, and is not recommended for use. See https://reactjs.org/link/unsafe-component-lifecycles for details.',
]);
LogBox.ignoreLogs([
  'VirtualizedLists should never be nested inside plain ScrollViews with the same orientation because it can break windowing and other functionality - use another VirtualizedList-backed container instead.',
]);
LogBox.ignoreLogs([
  'Require cycle: srcHocHResultFormat.js -> srcCustomViewsDescriptionChart.js -> srcHocHResultFormat.js',
]);
LogBox.ignoreLogs([
  "Warning: Each child in a list should have a unique 'key' prop.",
]);
LogBox.ignoreLogs(['VirtualizedLists should never be nested']);
LogBox.ignoreLogs([
  '`flexWrap: `wrap`` is not supported with the `VirtualizedList` components.Consider using `numColumns` with `FlatList` instead.',
]);

const STATUSBAR_HEIGHT = StatusBar.currentHeight;
const APPBAR_HEIGHT = Platform.OS === 'ios' ? 44 : 56;

const App = () => {
  const OverlayHOCComponent = COverlay(SSearchBar);
  const [overlay, setOverlay] = useState(false);
  const [toast, setToast] = useState(false);
  const [toastMsg, setToastMsg] = useState();

  useEffect(() => {
    (async () => {
      Global.CodePushVersion = await getAppVersion();
    })();
    getAppTheme();
    DeviceEventEmitter.addListener('event.testToast', eventData =>
      getEventFun(eventData),
    );

    // Initialize Notifications
    NotificationService.configure();
    NotificationService.initBackgroundFetch();
    NotificationService.scheduleMonthlyReportNotification();
    NotificationService.scheduleDailyExpandedReportNotification();
  }, []);

  function getEventFun(params) {
    if (params) {
      setToastMsg(params);
      setToast(true);
    }
  }

  const MyStatusBar = ({ backgroundColor, ...props }) => (
    <View style={[styles.statusBar, { backgroundColor }]}>
      <SafeAreaView>
        <StatusBar translucent backgroundColor={backgroundColor} {...props} />
      </SafeAreaView>
    </View>
  );

  const getAppTheme = async () => {
    try {
      const jsonValue = await AsyncStorage.getItem(Global.asyncStorageThemeKey);
      ThemeData = JSON.parse(jsonValue);
      return jsonValue != null && jsonValue != undefined
        ? ((Global.AppTheme = ThemeData),
          console.log('GLOBAL', JSON.stringify(Global.AppTheme.primary_color)),
          setOverlay(true))
        : setOverlay(true);
    } catch (e) {
      setOverlay(true);
      console.log('EROOROORORORORO ON', JSON.stringify(e));
    }
  };

  return overlay ? (


    <GestureHandlerRootView style={styles.container}>
      <MenuProvider>
        <AppProvider>
          <InsureResponseComponentProvider>
            <ContextBioProvider>
              <EmrResponseComponentProvider>
                <STemplateProvider>
                  <QuestionBuilderProvider>
                    <View style={{ flex: 1 }}>
                      {toast ? (
                        Platform.OS == 'ios' ? (
                          <AAlertIOS
                            data={toastMsg}
                            alertVisible={toast}
                            onDismiss={val =>
                              val == undefined ? null : setToast(val)
                            }
                            close={val =>
                              val == undefined ? null : setToast(val)
                            }
                          />
                        ) : (
                          <AAlert
                            data={toastMsg}
                            alertVisible={toast}
                            close={val =>
                              val == undefined ? null : setToast(val)
                            }
                          />
                        )
                      ) : null}
                      {Platform.OS == 'ios' ? (
                        <MyStatusBar
                          backgroundColor={Global.AppTheme.primary_color}
                          barStyle="light-content"
                        />
                      ) : null}
                      <SafeAreaView style={{ flex: 1 }}>
                        <ErrorBoundary>
                          <Navigation />
                        </ErrorBoundary>
                      </SafeAreaView>
                    </View>
                  </QuestionBuilderProvider>
                </STemplateProvider>
              </EmrResponseComponentProvider>
            </ContextBioProvider>
          </InsureResponseComponentProvider>
        </AppProvider>
      </MenuProvider>
    </GestureHandlerRootView>

  ) : (
    <Loader />
  );

};

export default App;

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  statusBar: {
    height: STATUSBAR_HEIGHT,
  },
  appBar: {
    backgroundColor: '#79B45D',
    height: APPBAR_HEIGHT,
  },
  content: {
    flex: 1,
    backgroundColor: '#33373B',
  },
});
