import React, { useState, useEffect, useContext, memo } from 'react';
import {
    Text,
    TextInput,
    StyleSheet,
    View,
    Image,
    TouchableWithoutFeedback,
    TouchableOpacity,
    Dimensions,
    ImageBackground,
    FlatList,
    Switch,
    Alert,
} from 'react-native';
// import {
//     useDimensions,
// } from '@react-native-community/hooks';
import { colors } from '../CommonStyle/commonStyle';
import ComponentStyles, { normalize } from '../CommonStyle/componentStyle';
import popupStyles, {
    getListviewItem,
    getListviewItemText,
} from '../CommonStyle/PopupStyle';
import {
    Collapse,
    CollapseHeader,
    CollapseBody,
} from 'accordion-collapse-react-native';
import Entypo from 'react-native-vector-icons/Entypo';
import InsureResponseComponentContext from '../Handlers/insureResponseComponentContext';
import AntDesign from 'react-native-vector-icons/AntDesign';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import { APIURL } from '../Common/apiConstants';
import { ArrayCheck, getLoading, notifyMessage, ValueCheck } from '../CommonStyle/ComponentFunctions';
import { Global } from '../Common/Global';
import Loader from '../Custom/Loader';
import NetworkServiceCall from '../Common/NetworkServiceCall';
import axios from 'axios'
import SSearchBar from '../StaticComponents/SSearchBar';
import SAlphabet from '../StaticComponents/SAlphabet';
import STimingSwitch from '../StaticComponents/STimingSwitch';
import FastImage from 'react-native-fast-image';

function AddScreenOverlay(props) {
    
    const { width, height } = Dimensions.get('window');
    const [searchData, setSearchData] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [displayData, setDisplayData] = useState([]);
    const [data, setData] = useState(props.data)
    const [overwrite, setOverwrite] = useState(false);
    const [tempString, settempString] = useState([]);
    const [isCollapseChild, setIsCollapseChild] = useState(props.collapse);
    const [selected, setSelected] = useState(0);
    const [alphaFilter, setAlphaFilter] = useState(false);
    const [filterPurpose, setFilterPurpose] = useState([]);
    const { responseJSON, setResponseJSON } = useContext(InsureResponseComponentContext);
    // console.log(">>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>", JSON.stringify(props))
    var heading = data.heading
    useEffect(() => {
        DropDownList()
    }, []);

    function DropDownList() {
        let buttonapi
        if (data.heading == "Add Nature") {
            var x = responseJSON.consultation != undefined ? responseJSON.consultation.map((item) => item.hosumrclassificationnature) : []
            var str = x.toString()
            buttonapi = APIURL + data.buttonapi + " '" + str + "'"
        } else {
            buttonapi = APIURL + 'emr/emrcommonget/rntemplatedropdown ' + Global.userData.hosuconsultant + "," + 1
        }

        setIsLoading(true);
        console.log("RETRIEVALLLLL DROPPPPP DOWNNNNNNNN", JSON.stringify(buttonapi))
        NetworkServiceCall('get', buttonapi, '').then(function (response) {
            if (
                response.httpstatus == 200 &&
                response.data.data != null &&
                response.data.data.length > 0
            ) {
                setDisplayData(response.data.data)
                setIsLoading(false);
                props.loading(false);

            } else {
                notifyMessage('No Data Found!!!!!', 2);
                setIsLoading(false);
                props.loading(false);
            }
        });

        getLoading(v => setIsLoading(false))
    }

    function onDelete() {
        let buttonapi = APIURL + "emr/emrcommonget/rnhosumrtemplatedelete " + Global.userData.hosuconsultant + "," + tempString[0]
        console.log("Template Stringggggggggggggggg", JSON.stringify(buttonapi))
        setIsLoading(true);
        NetworkServiceCall('get', buttonapi, '')
            .then(function (response) {
                console.log(">>>>>>>>>>>>", JSON.stringify(response))
                if (response.httpstatus == 200 &&
                    response.data != undefined &&
                    response.data.message != undefined) {
                    if (response.data.deletestatus == true) {
                        notifyMessage(response.data.message, 1)
                        settempString([])
                        DropDownList()
                    } else {
                        notifyMessage(response.data.message, 4)
                    }
                    setIsLoading(false);
                } else {
                    notifyMessage('Error On Delete', 2);
                    setIsLoading(false);
                }
            })

        getLoading(v => setIsLoading(false))
    }

    function getAlphabetData(alpha, index) {
        var filter = displayData.filter(value => (value.displayvalue != undefined ? value.displayvalue : "").charAt(0) == alpha)
        setFilterPurpose(filter)
        index == 0 ? setSearchData('') : setSearchData(alpha)
        index == 0 ? setAlphaFilter(false) : setAlphaFilter(true)
    }

    var radio_overwriteoption = [
        { displayvalue: 'NO', datavalue: 0 },
        { displayvalue: 'YES', datavalue: 1 },
    ];
    return (
        <View style={{ flex: 1 }}>
            <Text style={{ alignSelf: 'center', fontSize: normalize(10), fontWeight: 'bold', marginBottom: normalize(5), marginTop: normalize(-5) }}>{ValueCheck(data.heading) ? (data.heading).toUpperCase() : data.heading}</Text>

            <View style={getOverlayScreenContainer()}>
                <SSearchBar
                    onChangeText={val => setSearchData(val)} />
            </View>
            <View style={{ flexDirection: 'row' }}>
                <View style={getOverlayScreenChildContainer()}>
                    {GetSearchData(displayData)}
                </View>

                <View>
                    <SAlphabet
                        callBack={val =>
                            val == undefined ? null : getAlphabetData(val.alpha, val.index)
                        } />
                </View>

            </View>

            <View
                style={{
                    position: 'absolute',
                    bottom: normalize(-5),
                    // alignSelf: 'center',
                    flexDirection: 'row'
                }}>
                <TouchableOpacity
                    style={{
                        justifyContent: 'flex-start',
                        borderRadius: 10,
                        alignItems: 'flex-start',
                    }}
                    onPress={() => tempString.length > 0 ? getSelect() : notifyMessage("Please select an option")}>
                    <View style={{
                        flexDirection: 'column',
                        backgroundColor: '#f1f3f6', borderRadius: 10,

                        borderWidth: 1,
                        padding: normalize(5),
                        width: normalize(50),
                        height: normalize(45),
                        alignItems: 'center',
                        justifyContent: 'center',
                        borderColor: 'lightblue',
                        elevation: 3
                    }}>
                        <AntDesign
                            name="select1"
                            color={Global.AppTheme.primary_color}
                            size={normalize(20)}
                        />
                        <Text
                            style={{
                                fontSize: normalize(11),
                                color: Global.AppTheme.primary_color,
                                fontWeight: 'bold',
                            }}>
                            {' '}
                            Select
                        </Text>
                    </View>
                </TouchableOpacity>

                {ValueCheck(data) && data.heading != undefined
                    && data.heading == "MicroTemplate" ?
                    <TouchableOpacity
                        style={{
                            justifyContent: 'flex-start',
                            borderRadius: 10,
                            marginLeft: normalize(5),
                            alignItems: 'flex-start',
                        }}
                        onPress={tempString.length > 0 ? onDelete : null}>
                        <View style={{
                            flexDirection: 'column',
                            backgroundColor: '#f1f3f6', borderRadius: 10,

                            borderWidth: 1,
                            padding: normalize(5),
                            width: normalize(50),
                            height: normalize(45),
                            alignItems: 'center',
                            justifyContent: 'center',
                            borderColor: 'lightblue',
                            elevation: 3
                        }}>
                            <FontAwesome5
                                name="trash"
                                color={Global.AppTheme.primary_color}
                                size={normalize(20)}
                            />
                            <Text
                                style={{
                                    fontSize: normalize(11),
                                    color: '#ff6666',
                                    fontWeight: 'bold',
                                }}>
                                {' '}
                                Delete
                            </Text>
                        </View>
                    </TouchableOpacity> : null}
            </View>

            {isLoading ? <Loader displaytext={true} /> : null}
        </View>
    );
    const groupExpandToggle = () => {
        setIsCollapseChild(!isCollapseChild);
    };

    function getOverlayScreenChildContainer() {
        return {
            // height: height * 0.7,
            width: '90%',
        };
    }
    function getOverlayScreenContainer() {
        return {
            flexDirection: 'row',
            margin: 10,
            height: height * 0.045,
        };
    }

    function getSelect() {
        // console.log("DATA HEADINGGGG", data.heading)
        switch (data.heading) {
            case "MicroTemplate": AddMicroTemplate()
                break;
            case "Add Nature": onSelect()
                break;

        }
    }

    function getIterationKey(key) {
        switch (key) {
            case 17:
            case 19:
            case 20: return "hosumrcode"

            case 5:
            case 43:
            case 44:
            case 45:
            case 30: return "hosumrassessment"

            default: return "hosumrassessment"
        }
    }

    function AddMicroTemplate() {
        var overwriteValue = overwrite ? 1 : 0
        if (responseJSON.consultation != undefined && tempString.length > 0) {
            var apidata = Global.ParameterInfo
            let buttonapi = APIURL + 'templatechart/getMicroTemplate/' + apidata.hopapatient + "/" + apidata.homrpatientchart + "/"
                + apidata.hosuconsultant + "/" + apidata.suuser + "/" + "'" + tempString + "'" +
                "/" + overwriteValue
            // setIsLoading(true);
            console.log("Template Retrieveee dropp downnnnnnnnnnnn", JSON.stringify(buttonapi))
            NetworkServiceCall('get', buttonapi, '')
                .then(function (response) {
                    if (response.httpstatus == 200 &&
                        response.data.classifications != null &&
                        response.data.classifications.length > 0) {

                        response.data.classifications.map((item) => {
                            responseJSON.consultation.map((sub) => {
                                if (item.hosumrclassificationnature == sub.hosumrclassificationnature) {
                                    console.log("BBBBBBBBBBBB HHHHHHH TTTTTTTTT", item.heading)
                                    switch (item.heading) {
                                        case "PATIENT SERVICE":
                                        case "DIET":
                                        case "PRESCRIPTION":

                                        case "NUTRITIONAL SCREENING":
                                        case "GENERAL NUTRITION ASSESSMENT":
                                        case "PAEDIATRIC NUTRITIONAL AND PSYCHOSOCIAL ASSESSMENT":
                                        case "PAIN RE-ASSESSMENT":
                                        case "PAIN ASSESSMENT":

                                            if (overwrite) {
                                                sub.NewData[0].editArray = item.NewData[0].editArray
                                                sub.editStatus = true
                                            } else {
                                                const TEMPLATE2 = item.NewData[0].editArray.filter(
                                                    ({ [getIterationKey(item.hosumrclassificationnature)]: id1 }) => !sub.NewData[0].editArray.some(({ [getIterationKey(item.hosumrclassificationnature)]: id2 }) => id2 === id1),
                                                );
                                                if (TEMPLATE2.length > 0 && sub.NewData != undefined) {
                                                    TEMPLATE2.map((item) => {
                                                        sub.NewData[0].editArray.push(item)
                                                        sub.editStatus = true
                                                    })
                                                }
                                            }
                                            break;

                                        default:
                                            if (overwrite) {
                                                sub.NewData = item.NewData
                                                sub.editStatus = true
                                            } else {
                                                const Filtered = item.NewData.filter(
                                                    ({ display: id1 }) => !sub.NewData.some(({ display: id2 }) => id2 === id1),
                                                );
                                                console.log("FILTEREDDDDDDDDDDDD", JSON.stringify(Filtered))
                                                if (Filtered.length > 0 && sub.NewData != undefined) {
                                                    Filtered.map((item) => {
                                                        sub.NewData.push(item)
                                                        sub.editStatus = true
                                                    })
                                                }
                                            }
                                            break;
                                    }
                                } else {
                                    var result = responseJSON.consultation.filter(y => y.hosumrclassificationnature == item.hosumrclassificationnature);
                                    if (result.length > 0) {
                                    } else {
                                        responseJSON.consultation.push({ ...item, "editStatus": true })
                                    }
                                }
                            })
                        })
                        props.visibility(false)
                    } else {
                        notifyMessage('Please try again');
                        setIsLoading(false);
                        props.visibility(false)
                    }
                });
            getLoading(v => setIsLoading(false))
        } else {
            notifyMessage("Please try again.")
        }
    }

    function onSelect() {
        // console.log("RESPONSE ADD CONSULTATION", JSON.stringify(responseJSON.consultation))
        if (Global.ParameterInfo) {
            var Args = responseJSON.consultationdata != undefined ? responseJSON.consultationdata : Global.ParameterInfo
            var ValueString = tempString.toString();
            let buttonapi = APIURL + "emr/emrcommonget/rnaddnatureretrivel " + Args.hopapatient + "," + Args.homrpatientchart + "," + Args.hosuconsultant + "," + +  Args.suuser + "," + Args.hopaconsultationtype + "," + "'" + ValueString + "'"
            setIsLoading(true);
            console.log("RETRIEVALLLLL DROPPPPP DOWNNNNNNNN", JSON.stringify(buttonapi))
            NetworkServiceCall('get', buttonapi, '').then(function (response) {
                // console.log('AddScreenOverlay', JSON.stringify(response));
                if (
                    response.httpstatus == 200 &&
                    response.data != undefined &&
                    response.data.classifications != undefined &&
                    response.data.classifications.length > 0
                ) {
                    if (responseJSON.consultation.length > 0) {
    
                        response.data.classifications.map((item) => {
                            responseJSON.consultation.unshift({
                                ...item,
                                "editStatus": true
                            })
                            // console.log('responseJSON.consultation @@@@@@@@',JSON.stringify(responseJSON.consultation));
                            Global.EditStatus = 1
                        })
                    } else {
                        props.addNature != undefined ? props.addNature(response.data.classifications) : null
                    }
                    setIsLoading(false);
                    props.visibility(false)
                } else {
                    notifyMessage('No Data Found!!!!!');
                    setIsLoading(false);
                }
            });
        } else {
            props.visibility(false)
        }

        getLoading(v => setIsLoading(false))
    }


    function getOverlayScreenChildlistContainer() {
        return {
            height: height * 0.63,
            marginBottom: height * 0.01,
            marginTop: height * 0.01,
        };
    }
    function getCollapseBody() {
        return {
            paddingLeft: width * 0.03,
        };
    }
    function getCollapseHeader() {
        return {
            margin: width * 0.002,
            padding: width * 0.007,
            ...layoutstyles.collapse_header,
        };
    }
    function getParameterView() {
        return {
            paddingLeft: width * 0.02,
        };
    }
    function getButtonStyle(backgroundcolor) {
        return {
            // backgroundColor: backgroundcolor,
            ...popupStyles.overlay_screen_big_button_style,
        };
    }
    function GetSearchData(data) {
        var filterAlpha = alphaFilter ? filterPurpose : data;
        const newDropDownData = filterAlpha.filter(function (item) {
            const dataItem = item.displayvalue
                ? item.displayvalue.toUpperCase()
                : ''.toUpperCase();
            const textData = searchData.toUpperCase();
            return dataItem.indexOf(textData) > -1;
        });

        // console.log("NEWWWWWWW DROPPP DOWNNNN DATTTATTTATATTATATATATATT",JSON.stringify(newDropDownData))


        function renderItem(data) {
            return (
                data.item.datavalue != undefined && data.item.datavalue != 0 ?
                    <View>
                        <Collapse
                            //isExpanded={true}
                            //isExpanded={data.item.isexpand}
                            onToggle={() => onSelectItem(data.item, true)}>
                            <CollapseHeader >
                                <View
                                    style={[
                                        getListviewItem(data.item.selected),
                                        {
                                            flexDirection: 'row',
                                            alignItems: 'center',
                                            justifyContent: 'flex-start',
                                            marginTop: normalize(5),
                                            borderBottomWidth: data.item.selected ? 0 : 3,
                                            borderRightWidth: data.item.selected ? 0 : 2
                                        },
                                    ]}>
                                    <FontAwesome5
                                        name={ValueCheck(data.item.iconname) ? data.item.iconname : "dot-circle"}
                                        color={ValueCheck(data.item.color) ? data.item.color : Global.AppTheme.primary_color}
                                        size={normalize(17)}
                                        style={[{ margin: 2, paddingLeft: 5 }]}
                                    />

                                    <Text
                                        style={[
                                            getListviewItemText(data.item.selected),
                                            { margin: 2, paddingLeft: 2, paddingVertical: normalize(5) },
                                        ]}>
                                        {data.item.displayvalue}
                                    </Text>
                                </View>
                            </CollapseHeader>
                            <CollapseBody>
                                <FlatList data={data.item.datagroup1} renderItem={renderHeader} />
                            </CollapseBody>
                        </Collapse>
                    </View> : null
            );
        }

        function renderHeader(data) {
            return (
                <View style={getParameterView()}>
                    <Collapse isExpanded={data.item.isexpand}>
                        <CollapseHeader style={getCollapseHeader()}>
                            <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                                <FontAwesome5
                                    name={data.item.icon}
                                    color={Global.AppTheme.primary_color}
                                    size={normalize(14)}
                                    style={{
                                        margin: 2,
                                        paddingLeft: 5,
                                    }}
                                />
                                <Text style={layoutstyles.collapseheader_text}>
                                    {data.item.displayvalue}
                                </Text>
                            </View>
                        </CollapseHeader>
                        <CollapseBody style={getCollapseBody()}>
                            <FlatList data={data.item.datagroup2} renderItem={renderValue} />
                        </CollapseBody>
                    </Collapse>
                </View>
            );
        }

        function renderValue(data) {
            //console.log("datagroup2",data)
            return (
                <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                    <Entypo name="dot-single" color="black" />
                    <Text>{data.item.displayvalue}</Text>
                </View>
            );
        }
        function onSelectItem(datavalue, multiselect) {
            if (multiselect == true) {
                if (tempString.includes(datavalue.datavalue)) {
                    datavalue.selected = !datavalue.selected;
                    setSelected(selected + 1);
                    var index = tempString.indexOf(datavalue.datavalue);
                    if (index > -1) {
                        tempString.splice(index, 1);
                    }
                } else {
                    datavalue.selected = !datavalue.selected;
                    setSelected(selected + 1);
                    tempString.push(datavalue.datavalue);
                    //var str = tempString.join();
                    // ValueString = str.toString()
                }
            }
        }

        function getOveritePopUp() {
            Alert.alert(
                "Overwrite ?",
                "Do you really want to OVERWRITE MICRO TEMPLATE ? Saved classification data will be deleted on Select.",
                [
                    { text: "CONFIRM", onPress: () => setOverwrite(true) },
                    { text: "NO", onPress: () => setOverwrite(false) }
                ]
            )
        }

        return (
            <View style={layoutstyles.overlay_screen_listview_container}>
                <View style={getOverlayScreenChildlistContainer()}>
                    <FlatList data={newDropDownData} renderItem={renderItem} />
                </View>

                {heading == "MicroTemplate" ?
                    <TouchableOpacity
                        onPress={() => !overwrite ? getOveritePopUp() : setOverwrite(false)}
                        style={{ width: normalize(120), alignItems: 'center', position: 'absolute', bottom: normalize(-60), right: 0, zIndex: 1, backgroundColor: 'transparent' }}>

                        <FastImage
                            style={{
                                height: normalize(50),
                                width: normalize(70),
                                justifyContent: "center",
                                alignItems: "center",
                            }}
                            resizeMode={'cover'}
                            source={require('../Asset/gif/overwrite.gif')}
                        />

                        <View style={{ flexDirection: 'row', alignItems: 'center', zIndex: 1 }}>
                            <Text style={{ fontSize: normalize(10), paddingHorizontal: normalize(2) }}>OVERWRITE ?</Text>
                            <View style={{}}>
                                <Switch
                                    trackColor={{ false: "#767577", true: "red" }}
                                    thumbColor={"lightgrey"}
                                    onChange={() => !overwrite ? getOveritePopUp() : setOverwrite(false)}
                                    value={overwrite}
                                />
                            </View>
                        </View>

                    </TouchableOpacity> : null}
            </View>
        );
    }
}
const layoutstyles = StyleSheet.create({
    overlay_screen_listview_container: {
        justifyContent: 'center',
        marginBottom: 10,
    },
    collapseheader_text: {
        fontSize: normalize(11),
        margin: 2,
        paddingLeft: 5,
    },
    collapsebody_text: {
        fontSize: normalize(10),
        margin: 2,
        paddingLeft: 5,
    },

    overlay_searchTextbox_View: {
        width: '96%',
    },
    collapse_header: {
        backgroundColor: '#F0F0F0',
        flexDirection: 'row',
        justifyContent: 'flex-start',
        alignContent: 'center',
        alignItems: 'center',
        borderRadius: 7,
        marginLeft: 0,
    },
    textinput_view: {
        flex: 1,
        paddingLeft: '1%',
    },
    overwrite_child_container: {
        flexDirection: 'row',
        flex: 1,
    },
    overwrite_left_container: {
        flex: 1,
        justifyContent: 'center',
    },
    overwrite_right_container: {
        flex: 1,
        justifyContent: 'space-around',
        flexDirection: 'row',
        alignContent: 'center',
        alignItems: 'center',
    },
    overwrite_right_container_text: {},
    overwrite_left_container_text: {
        fontSize: normalize(11),
        fontWeight: '300',
        color: colors.color_SelectText,
    },
});

export default memo(AddScreenOverlay);
