import React, { useState, useEffect, useContext } from 'react';
import {
    Text,
    TextInput,
    StyleSheet,
    View,
    Image,
    TouchableOpacity,
    ScrollView,
    Dimensions,
    FlatList,
    TouchableWithoutFeedback,
    Switch,
} from 'react-native';
import { colors } from '../CommonStyle/commonStyle';
import ComponentStyles, { normalize } from '../CommonStyle/componentStyle';
import Icons from '../Common/Icons';
import AwesomeButton from "react-native-really-awesome-button";
import STimingSwitch from '../StaticComponents/STimingSwitch';
import { notifyMessage, ValueCheck } from '../CommonStyle/ComponentFunctions';
import InsureResponseComponentContext from '../Handlers/insureResponseComponentContext';

function CRowAdd(props) {
    const { responseJSON, setResponseJSON } = useContext(InsureResponseComponentContext);
    const [componentAccess, setComponentAccess] = useState(0);
    const [parameterName, setParameterName] = useState('');
    const [description, setDescription] = useState('');
    return (
        <View style={{ flex: 1, width: '97%' }}>
            <Text style={{ alignSelf: 'center', fontSize: normalize(12), fontWeight: 'bold', marginBottom: normalize(5), marginTop: normalize(-5), color: 'darkblue' }}>{ValueCheck(responseJSON) && ValueCheck(responseJSON.consultationEdit) && ValueCheck(responseJSON.consultationEdit.heading) ? responseJSON.consultationEdit.heading + " PARAMETER" : 'PARAMETER'}</Text>

            <View style={{ flex: 1, marginVertical: 0 }}>
                <Text style={{ fontSize: normalize(11), paddingHorizontal: normalize(10) }}>Parameter name :</Text>

                <View style={{ borderWidth: 1, height: normalize(35), borderRadius: 7, borderColor: 'lightgrey', backgroundColor: '#fff', elevation: 3 }}>
                    <TextInput
                        numberOfLines={1}
                        keyboardType={'default'}
                        onChangeText={changevalue => setParameterName(changevalue)}
                        value={parameterName} />
                </View>

                <View>
                    <Text style={{ fontSize: normalize(11), paddingHorizontal: normalize(10) }}>Description:</Text>
                    <View style={{ borderWidth: 1, height: normalize(35), borderRadius: 7, borderColor: 'lightgrey', backgroundColor: '#fff', elevation: 3 }}
                    >
                        <TextInput
                            numberOfLines={4}
                            keyboardType={'default'}
                            placeholder='optional'
                            onChangeText={changevalue => setDescription(changevalue)}
                            value={description} />
                    </View>
                </View>

                <View style={{ borderWidth: 1, borderRadius: 7, borderColor: 'lightgrey', backgroundColor: '#fff', elevation: 3, paddingVertical: normalize(5), marginTop: normalize(5) }}>
                    <Text style={{ fontSize: normalize(11), paddingHorizontal: normalize(10) }}>Type of data:</Text>
                    <STimingSwitch
                        data={[
                            {
                                "timingslot": 2,
                                "slotname": "Value",
                                "selected": false
                            },
                            {
                                "timingslot": 6,
                                "slotname": "Description",
                                "selected": false
                            },
                            {
                                "timingslot": 1,
                                "slotname": "Date",
                                "selected": false
                            },
                            {
                                "timingslot": 3,
                                "slotname": "Question",
                                "selected": false
                            },
                            {
                                "timingslot": 4,
                                "slotname": "Remarks",
                                "selected": false
                            },
                            {
                                "timingslot": 5,
                                "slotname": "Image",
                                "selected": false
                            },

                        ]}
                        callBack={val =>
                            val == undefined ? null :
                                setComponentAccess(val)} />
                </View>

                <View
                    style={{
                        position: 'absolute',
                        bottom: normalize(0),
                        width: '100%',
                    }}>
                    <AwesomeButton
                        onPress={() => getAddColumn()}
                        borderRadius={10}
                        borderWidth={1}
                        height={normalize(40)}
                        width={normalize(55)}
                        backgroundColor={"#eaf2ff"}
                        paddingHorizontal={0}
                        raiseLevel={5}
                        paddingBottom={0}
                        borderColor={'white'}
                        paddingTop={0}>

                        <View style={{ alignItems: 'center', width: normalize(50) }} >
                            <Icons.FontAwesome5 name="save" color={"#094485"} size={normalize(20)} />
                            <Text numberOfLines={1} style={{ color: "#094485", fontSize: normalize(10) }}>Select</Text>
                        </View>
                    </AwesomeButton>
                </View>
            </View>

        </View>
    );

    function getAddColumn(params) {
        if (parameterName != "" && parameterName != undefined && componentAccess != 0) {
            var call = {
                "parametername": (parameterName).toUpperCase(),
                "parameterdescription": description,
                "columntype": componentAccess.timingslot,
            }
            props.callBack(call)
            props.visibility(false)
        } else {
            notifyMessage("Please fill required coulmns", 3)
        }
    }
}

export default CRowAdd;


