    function getSave() {

        var output = {
            "groups": {
                "procedurename": "rnhosuconsultantupdation1",
                "suuser": Global.userData.suuser,
                "hosuconsultant": Global.userData.hosuconsultant,
                "data": {
                    ...data,
                    'oplocation': `${data.hospitalblock}${data.floorno}${data.roomno}`
                }
            }
        }
        let buttonapi = APIURL + 'commontemplatesave/RnCommonTemplateSave';

        console.log("Buttonnnnnnnnnn apiiiiiiiiiiiiiiiiiiiiii", JSON.stringify(buttonapi));
        console.log("output OUserView apiiiiiiiiiiiiiiiiiiiiii", JSON.stringify(output));

        NetworkServiceCall('post', buttonapi, output).then(function (response) {
            // console.log("output OuserView apiiiiiiiiiiiiiiiiiiiiii", JSON.stringify(response))
            if (response.httpstatus == 200 && isNU(response.data) && isNU(response.data.code) && response.data.code > 0) {
                ValueCheck(Global.userData.photo) ? Global.userData.photo = data.imageurl : null,
                    ValueCheck(Global.userData.experience) ? Global.userData.experience = data.experience : null,
                    ValueCheck(Global.userData.qualification) ? Global.userData.qualification = data.qualification : null,
                    ValueCheck(Global.userData.achievement) ? Global.userData.achievement = data.achievement : null,
                    ValueCheck(Global.userData.mobileno) ? Global.userData.mobileno = data.mobileno : null,
                    // console.log('oplocation old', Global.userData.oplocation),
                    (Global.userData.oplocation = `${data.hospitalblock}${data.floorno}${data.roomno}`),
                    // console.log('oplocation updated', `${data.hospitalblock}${data.floorno}${data.roomno}`),
                    navigation.navigate('Login', { data: {} })
                // navigation.goBack();
                // console.log('Global.userData.oplocation', Global.userData.oplocation);
                notifyMessage('User details updated successfully.', 1);
                props.visibility(false);
            } else {
                notifyMessage('Data Not Updated!', 2);
            }
        });
    }
