import * as React from 'react';
import { View, Text, Button, Platform } from 'react-native';
import { NavigationContainer, useNavigation as useNativeNavigation } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { LanguageProvider } from '../context/LanguageContext';

// Target Screens
import DonorRegistration from '../Registration/DonorRegistration';
import CameraScreen from '../Screens/CameraScreen';
import PDFViewerScreen from '../components/pdfviewerscreen';

// Define the screens object for Web/Custom NavigationProvider
const screens = {
  DonorRegistration,
  CameraScreen,
  PDFViewerScreen,
};

const NavigationContext = React.createContext(null);

export const NavigationProvider = ({ children }) => {
  const [stack, setStack] = React.useState([{ name: 'DonorRegistration', params: {} }]);
  const focusListeners = React.useRef({});

  const current = stack[stack.length - 1];

  const navigate = (screenName, params = {}) => {
    setStack(prev => [...prev, { name: screenName, params }]);
  };

  const replace = (screenName, params = {}) => {
    setStack(prev => [...prev.slice(0, -1), { name: screenName, params }]);
  };

  const goBack = () => {
    if (stack.length > 1) setStack(prev => prev.slice(0, -1));
  };

  const addFocusListener = (screenName, callback) => {
    if (!focusListeners.current[screenName]) focusListeners.current[screenName] = [];
    focusListeners.current[screenName].push(callback);
    return () => {
      focusListeners.current[screenName] = focusListeners.current[screenName].filter(cb => cb !== callback);
    };
  };

  React.useEffect(() => {
    const listeners = focusListeners.current[current.name] || [];
    listeners.forEach(cb => cb());
  }, [current.name]);

  return (
    <NavigationContext.Provider
      value={{ navigate, goBack, replace, addFocusListener, current }}
    >
      <View style={{ flex: 1 }}>
        {stack.map((route, index) => {
          const ScreenComponent = screens[route.name];
          const isFocused = index === stack.length - 1;

          // If ScreenComponent is missing, we might have an issue, but for now assuming it exists in 'screens'
          if (!ScreenComponent) return null;

          return (
            <View
              key={index}
              style={{
                flex: 1,
                display: isFocused ? 'flex' : 'none',
              }}
            >
              <ScreenComponent
                navigation={{ navigate, replace, goBack }}
                route={{ params: route.params }}
              />
            </View>
          );
        })}

        {children}
      </View>
    </NavigationContext.Provider>
  );
};



export const useNavigation = () => {
  const ctx = React.useContext(NavigationContext);
  if (ctx) {
    return ctx;
  }
  // Fallback to native navigation
  try {
    return useNativeNavigation();
  } catch (e) {
    console.error("Navigation context missing", e);
    return null;
  }
};

export const useFocusEffect = (callback) => {
  const { current, addFocusListener } = useNavigation();
  const cleanupRef = React.useRef(null);

  React.useEffect(() => {
    cleanupRef.current?.();
    const unsubscribe = addFocusListener(current.name, () => {
      cleanupRef.current?.();
      cleanupRef.current = callback();
    });
    return () => {
      cleanupRef.current?.();
      unsubscribe?.();
    };
  }, [current.name]);
};

// Hook to check if the current screen is focused
export const useIsFocused = () => {
  const { current, addFocusListener } = useNavigation();
  const [isFocused, setIsFocused] = React.useState(true);

  React.useEffect(() => {
    // Initial check
    setIsFocused(true);

    // Subscribe to focus changes
    const unsubscribe = addFocusListener(current.name, () => {
      setIsFocused(true);
    });

    // When the screen loses focus, we mark it as not focused
    return () => {
      setIsFocused(false);
      unsubscribe();
    };
  }, [current.name]);

  return isFocused;
};

export const ReactNativeNavigation = () => {
  const Stack = createNativeStackNavigator();

  return (
    <NavigationContainer>
      <LanguageProvider>
        <Stack.Navigator initialRouteName="DonorRegistration" screenOptions={{
          animation: 'none',
          headerShown: false,
        }}>
          <Stack.Screen name="DonorRegistration" component={DonorRegistration} />
          <Stack.Screen name="CameraScreen" component={CameraScreen} />
          <Stack.Screen name="PDFViewerScreen" component={PDFViewerScreen} />
        </Stack.Navigator>
      </LanguageProvider>
    </NavigationContainer>
  );
}

export default function Navigation() {
  return Platform.OS == 'web' ? (
    <LanguageProvider>
      <NavigationProvider />
    </LanguageProvider>
  ) : (
    <ReactNativeNavigation />
  );
}
