import React, { useRef, useEffect, useState } from 'react';
import { View, TouchableOpacity, Text, StyleSheet } from 'react-native';
import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';

// Simple professional signature pad HTML
const htmlContent = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body, html { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; background-color: #ffffff; }
    canvas { display: block; width: 100%; height: 100%; cursor: crosshair; touch-action: none; }
    .placeholder {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        color: #e2e8f0;
        font-family: sans-serif;
        font-size: 24px;
        font-weight: 600;
        pointer-events: none;
        user-select: none;
    }
  </style>
</head>
<body>
  <div id="placeholder" class="placeholder">Sign Here</div>
  <canvas id="sig-canvas"></canvas>
  <script>
    const canvas = document.getElementById('sig-canvas');
    const placeholder = document.getElementById('placeholder');
    const ctx = canvas.getContext('2d');
    let drawing = false;
    let hasSignature = false;

    function resize() {
      // Set actual canvas size to match display size for sharp rendering on high DPI
      const rect = document.body.getBoundingClientRect();
      canvas.width = rect.width * window.devicePixelRatio;
      canvas.height = rect.height * window.devicePixelRatio;
      ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
    }
    window.addEventListener('resize', resize);
    resize();

    function hidePlaceholder() {
        if (placeholder && placeholder.style.display !== 'none') {
            placeholder.style.display = 'none';
        }
    }

    // Mouse events
    canvas.addEventListener('mousedown', startDraw);
    canvas.addEventListener('mousemove', draw);
    canvas.addEventListener('mouseup', endDraw);
    canvas.addEventListener('mouseout', endDraw);

    // Touch events
    canvas.addEventListener('touchstart', (e) => {
      e.preventDefault();
      const touch = e.touches[0];
      startDraw({ clientX: touch.clientX, clientY: touch.clientY });
    }, { passive: false });
    
    canvas.addEventListener('touchmove', (e) => {
      e.preventDefault();
      const touch = e.touches[0];
      draw({ clientX: touch.clientX, clientY: touch.clientY });
    }, { passive: false });

    canvas.addEventListener('touchend', endDraw);

    function startDraw(e) {
      hidePlaceholder();
      drawing = true;
      hasSignature = true;
      ctx.beginPath();
      const rect = canvas.getBoundingClientRect();
      ctx.moveTo(e.clientX - rect.left, e.clientY - rect.top);
      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.strokeStyle = '#000';
      window.parent.postMessage({ type: 'STROKE_START' }, '*');
    }

    function draw(e) {
      if (!drawing) return;
      const rect = canvas.getBoundingClientRect();
      ctx.lineTo(e.clientX - rect.left, e.clientY - rect.top);
      ctx.stroke();
    }

    function endDraw() {
      if(drawing) {
        drawing = false;
        window.parent.postMessage({ type: 'STROKE_END' }, '*');
      }
    }

    window.saveSignature = () => {
      if(!hasSignature) return null;
      return canvas.toDataURL('image/png');
    }

    window.clearSignature = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      hasSignature = false;
      placeholder.style.display = 'block';
      window.parent.postMessage({ type: 'CLEARED' }, '*');
    }
    
    // Listen for messages from parent
    window.addEventListener('message', (event) => {
      if (event.data?.type === 'SAVE') {
        const dataUrl = window.saveSignature();
        window.parent.postMessage({ type: 'SAVED', data: dataUrl }, '*');
      }
      if (event.data?.type === 'CLEAR') {
        window.clearSignature();
      }
    });

  </script>
</body>
</html>
`;

const WebSignaturePad = ({ onSave, onClear, onStrokeStart, onStrokeEnd, style }) => {
  const iframeRef = useRef(null);

  useEffect(() => {
    const handleMessage = (event) => {
      if (event.data?.type === 'SAVED') {
        onSave && onSave(event.data.data);
      }
      if (event.data?.type === 'STROKE_START') {
        onStrokeStart && onStrokeStart();
      }
      if (event.data?.type === 'STROKE_END') {
        onStrokeEnd && onStrokeEnd();
      }
      if (event.data?.type === 'CLEARED') {
        onClear && onClear();
      }
    };

    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [onSave, onStrokeStart, onStrokeEnd, onClear]);

  const triggerSave = () => {
    iframeRef.current?.contentWindow?.postMessage({ type: 'SAVE' }, '*');
  };

  const triggerClear = () => {
    iframeRef.current?.contentWindow?.postMessage({ type: 'CLEAR' }, '*');
  };

  return (
    <View style={[styles.container, style]}>
      <View style={styles.canvasContainer}>
        <iframe
          ref={iframeRef}
          srcDoc={htmlContent}
          style={{ width: '100%', height: '100%', border: 'none', borderRadius: 8 }}
          title="signature-pad"
        />
      </View>

      {/* Professional Controls Toolbar */}
      <View style={styles.toolbar}>
        <Text style={styles.instruction}>Please sign above</Text>

        <View style={styles.buttonGroup}>
          <TouchableOpacity
            style={[styles.button, styles.clearButton]}
            onPress={triggerClear}
            activeOpacity={0.7}
          >
            <MaterialCommunityIcons name="eraser" size={18} color="#dc2626" />
            <Text style={styles.clearText}>Clear</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[styles.button, styles.saveButton]}
            onPress={triggerSave}
            activeOpacity={0.7}
          >
            <MaterialCommunityIcons name="check" size={18} color="#ffffff" />
            <Text style={styles.saveText}>Save Signature</Text>
          </TouchableOpacity>
        </View>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#fff',
    overflow: 'hidden',
  },
  canvasContainer: {
    flex: 1,
    backgroundColor: '#fff',
    borderRadius: 8,
    overflow: 'hidden',
  },
  toolbar: {
    height: 50,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 12,
    backgroundColor: '#f8fafc',
    borderTopWidth: 1,
    borderTopColor: '#e2e8f0',
    borderBottomLeftRadius: 8,
    borderBottomRightRadius: 8,
  },
  instruction: {
    fontSize: 12,
    color: '#64748b',
    fontWeight: '500',
    fontStyle: 'italic',
  },
  buttonGroup: {
    flexDirection: 'row',
    gap: 8,
  },
  button: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 6,
    paddingHorizontal: 12,
    borderRadius: 6,
    gap: 6,
  },
  clearButton: {
    backgroundColor: '#fee2e2',
    borderWidth: 1,
    borderColor: '#fecaca',
  },
  saveButton: {
    backgroundColor: '#094485',
    shadowColor: '#094485',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.2,
    shadowRadius: 3,
    elevation: 2,
  },
  clearText: {
    fontSize: 13,
    fontWeight: '600',
    color: '#dc2626',
  },
  saveText: {
    fontSize: 13,
    fontWeight: '600',
    color: '#ffffff',
  },
});

export default WebSignaturePad;
