import React, { useContext, useState } from 'react';
import {
  StyleSheet,
  Text,
  View,
  StatusBar,
  Image,
  TouchableOpacity,
  Modal,
  Dimensions,
  ScrollView,
  Platform,
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import Feather from 'react-native-vector-icons/Feather';
import { Global } from '../Common/Global';
import CSliderMenu from '../Custom/CSliderMenu';
import { normalize } from '../CommonStyle/componentStyle';
// import { useNavigation, useIsFocused } from '@react-navigation/native';
import { useNavigation } from '../Navigation/PageNavigation';
const useIsFocused = () => true; // Stub for web
import NotificationContext from '../Handlers/NoticationsContext';
import moment from 'moment';
import { ValueCheck } from '../CommonStyle/ComponentFunctions';
import ABlink from '../Alerts/ABlink';
import COverlay from '../CustomComponents/COverlay';
import OUserView from '../Custom/OUserView';
import CBackHandler from '../CustomComponents/CBackHandler';
import CNetworkStatus from '../CustomComponents/CNetworkStatus';
import { APIURL } from '../Common/apiConstants';
import InsureResponseComponentContext from '../Handlers/insureResponseComponentContext';

const HeaderBlock = (props) => {
  const { responseJSON } = useContext(InsureResponseComponentContext);
  const [isShowSlidermenu, setIsShowSlidermenu] = useState(false);
  const [backHandler, setBackHandler] = useState(false);
  const [backHandlerLogOut, setBackHandlerLogOut] = useState(false);
  const [overlay, setOverlay] = useState(false);
  const [jsonoverlay, setJsonOverlay] = useState(false);

  const navigation = useNavigation();
  const isFocused = useIsFocused();
  const OverlayHOCComponent = COverlay(OUserView);
  const NotificationData = useContext(NotificationContext) || [];

  const result = NotificationData.filter(obj => obj.status === true);

  function OnPressGoBack() {
    if (props.callback) {
      props.callback(true);
    } else {
      if (ValueCheck(props.backhandler)) {
        if (ValueCheck(props.consultation) && Global.EditStatus === 1) {
          setBackHandler(true);
        } else if (ValueCheck(props.consultation)) {
          navigation.goBack();
        } else {
          setBackHandlerLogOut(true);
        }
      } else {
        navigation.goBack();
      }
    }
  }

  return (
    <View
      style={{
        display: 'flex',
        height: '7%',
        backgroundColor: Global.AppTheme.primary_color,
        justifyContent: 'center',
        paddingLeft: normalize(3),
        marginTop: StatusBar.currentHeight,
        ...props.style,
      }}>
      <StatusBar
        translucent
        backgroundColor={Global.AppTheme.primary_color}
        barStyle="light-content"
      />

      {/* ---------- JSON Overlay (debug view) ---------- */}
      {jsonoverlay && (
        <Modal
          onRequestClose={() => setJsonOverlay(false)}
          style={{
            height: Dimensions.get('screen').height,
            width: Dimensions.get('screen').width,
            backgroundColor: 'transparent',
            justifyContent: 'center',
            alignItems: 'center',
          }}
          transparent={true}>
          <View
            style={{
              backgroundColor: 'white',
              borderWidth: 1,
              height: Dimensions.get('screen').height * 0.9,
              alignSelf: 'center',
              width: Dimensions.get('screen').width * 0.9,
            }}>
            <TouchableOpacity onPress={() => setJsonOverlay(false)}>
              <Text
                style={{
                  textAlign: 'right',
                  fontWeight: 'bold',
                  color: 'black',
                }}>
                Close
              </Text>
            </TouchableOpacity>
            <ScrollView>
              <Text
                selectable
                style={{
                  fontSize: normalize(10),
                  color: 'black',
                  fontFamily: 'Courier New',
                }}>
                {JSON.stringify(responseJSON, null, 2)}
              </Text>
            </ScrollView>
          </View>
        </Modal>
      )}

      {/* ---------- Header Content ---------- */}
      <View
        style={{
          flexDirection: 'row',
          alignItems: 'center',
          marginBottom: normalize(6),
          paddingBottom: normalize(0),
        }}>
        {/* ---------- Back Button & Logo ---------- */}
        <TouchableOpacity
          style={{ flexDirection: 'row', alignItems: 'center' }}
          onPress={OnPressGoBack}>
          <Ionicons name="chevron-back" color="white" size={normalize(25)} />
          <View>
            {Global.betaversion ? (
              <View style={{ width: normalize(100), height: normalize(40) }} />
            ) : (
              <Image
                style={{
                  width: normalize(100),
                  height: normalize(40),
                  resizeMode: 'contain',
                  borderRadius: 8,
                }}
                source={{
                  uri: Global.screenheaderlogo,
                }}
              />
            )}
          </View>

          {/* ---------- Beta Label ---------- */}
          {Global.betaversion ? (
            <View
              style={{
                position: 'absolute',
                bottom: normalize(-6),
                right: normalize(-9),
              }}>
              <ABlink duration={500}>
                <View style={{ justifyContent: 'center', alignItems: 'center' }}>
                  <Text
                    style={{
                      color: '#eb2525ff',
                      fontSize: normalize(17),
                      letterSpacing: 1,
                      fontWeight: 'bold',
                      textShadowColor: '#000000',
                      textShadowOffset: { width: 0.5, height: 0.5 },
                      textShadowRadius: 0.5,
                    }}>
                    BETA TESTING
                  </Text>
                  <Text
                    style={{
                      color: 'white',
                      fontSize: normalize(10),
                    }}>
                    {Global.version ? `V ${Global.version}` : null}
                  </Text>
                </View>
              </ABlink>
            </View>
          ) : null}
        </TouchableOpacity>

        {/* ---------- USER NAME ---------- */}
        <TouchableOpacity
          onPress={() => props.webview ? null : setOverlay(true)}
          style={{
            flexDirection: 'row',
            flex: 1,
            justifyContent: 'flex-start',
            marginLeft: normalize(10),
          }}>
          <View>
            <Text
              adjustsFontSizeToFit
              numberOfLines={1}
              style={{
                fontWeight: 'bold',
                fontSize: normalize(15),
                color: 'white',
              }}>
              {Global?.userData?.username}
            </Text>

            {Global?.userData?.designation ? (
              <Text
                adjustsFontSizeToFit
                style={{
                  fontSize: normalize(11),
                  color: 'white',
                }}>
                {Global.userData.designation}
              </Text>
            ) : null}
          </View>
        </TouchableOpacity>

        {/* ---------- Right Side Icons ---------- */}
        {props.webview ? null : (
          <View
            style={{
              flexDirection: 'row',
              alignItems: 'center',
              justifyContent: 'flex-end',
            }}>
            {/* Reset Icon - Keep this for Web */}
            {props.onReset && (
              <TouchableOpacity
                onPress={props.onReset}
                style={{ marginRight: normalize(15) }}>
                <Ionicons
                  name="refresh-circle-outline" // or "reload-circle-outline"
                  color="white"
                  size={normalize(26)}
                />
              </TouchableOpacity>
            )}

            {/* Hide these on Web as requested */}
            {Platform.OS !== 'web' && (
              <>
                <CNetworkStatus />

                {/* Notifications */}
                <TouchableOpacity
                  onPress={() => navigation.navigate('NotificationSettings')}
                  style={{ marginRight: normalize(5) }}>
                  <View
                    style={{
                      position: 'absolute',
                      right: normalize(-5),
                      top: normalize(-8),
                      backgroundColor: 'white',
                      alignItems: 'center',
                      borderRadius: 20,
                      width: normalize(15),
                    }}>
                    {isFocused && (
                      <ABlink>
                        <Text
                          numberOfLines={1}
                          adjustsFontSizeToFit
                          style={{
                            color: result.length > 0 ? 'red' : 'black',
                            fontSize: normalize(7),
                            fontWeight: 'bold',
                          }}>
                          {result.length}
                        </Text>
                      </ABlink>
                    )}
                  </View>
                  <Ionicons
                    name="notifications-outline"
                    color="white"
                    size={normalize(15)}
                  />
                </TouchableOpacity>

                {/* Menu Icon */}
                <View style={{ paddingLeft: normalize(2) }}>
                  <TouchableOpacity
                    onPress={() => setIsShowSlidermenu(true)}
                    style={{ alignItems: 'center', justifyContent: 'center' }}>
                    <Feather name="menu" color="white" size={normalize(25)} />
                    <View>
                      {Global.LoginTime ? (
                        <Text
                          style={{
                            fontSize: normalize(9),
                            color: 'white',
                          }}>
                          {(
                            moment.duration(moment().diff(Global.LoginTime)).asMinutes()
                          ).toFixed(0) + ' Min.'}
                        </Text>
                      ) : null}
                    </View>
                  </TouchableOpacity>
                </View>
              </>
            )}
          </View>
        )}
      </View>

      {/* ---------- Overlays & Menus ---------- */}
      {overlay ? (
        <OverlayHOCComponent visibility={val => setOverlay(val)} />
      ) : null}

      {isShowSlidermenu ? (
        <CSliderMenu
          navigation={navigation}
          isShow={isShowSlidermenu}
          visibility={val => setIsShowSlidermenu(val)}
        />
      ) : null}

      {backHandler ? (
        <CBackHandler
          type={5}
          callBack={val => (setBackHandler(val), navigation.goBack())}
          close={val => setBackHandler(val)}
        />
      ) : null}

      {backHandlerLogOut ? (
        <CBackHandler
          type={6}
          callBack={val => (setBackHandlerLogOut(val), navigation.goBack())}
          close={val => setBackHandlerLogOut(val)}
        />
      ) : null}
    </View>
  );
};

export default HeaderBlock;