import React, {
  forwardRef,
  useContext,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from 'react';
import {View, FlatList, Text, BackHandler} from 'react-native';
import {Global} from '../../Common/Global';
import {normalize} from '../../CommonStyle/componentStyle';
import CAwesomeButton from '../../CustomComponents/CAwesomeButton';
import CFooterView from '../../CustomComponents/CFooterView';
import HView from '../../HOC/HView';
import {useFocusEffect, useNavigation} from '@react-navigation/native';
import {APIURL} from '../../Common/apiConstants';
import {isBNUL, isNU} from '../../CommonStyle/ComponentFunctions';
import {manageContext} from '../../Handlers/manageContext';
import PdfPreviewOverlay from '../../Screens/PdfPreviewOverlay';
import Loader from '../../Custom/Loader';

const CVitalSign = forwardRef((props, ref) => {
  const navigation = useNavigation();

  useImperativeHandle(ref, () => ({
    triggerFromHeader() {
      navigation.goBack();
      console.log('Triggered from HeaderBlock!');
    },
  }));

  useFocusEffect(
    React.useCallback(() => {
      const backAction = () => {
        navigation.goBack();
        return true;
      };
      const subscription = BackHandler.addEventListener(
        'hardwareBackPress',
        backAction,
      );
      return () => subscription.remove();
    }, [navigation]),
  );

  const stemplate = props.stemplate ?? false;
  const {contextdata, setContextData} = manageContext(stemplate);
  const [previewoverlay, setPreviewOverlay] = useState(false);
  const [previewoverlaydata, setPreviewOverlayData] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const data = contextdata.consultation?.[contextdata.natureindex]?.NewData;
  const hosumrclassificationnature =
    contextdata.consultation?.[contextdata.natureindex]
      ?.hosumrclassificationnature;

  function getPreviewData(responseJSON) {
    let buttonapi = APIURL + 'emrsaveresponse/RnResponse';
    let jsondata = {
      groups: {
        ...responseJSON,
        consultationEdit: undefined,
        componentFooter: undefined,
        procedurename: 'rnhomrNatureChartPreview',
        consultation: [
          {
            ...responseJSON.consultation[responseJSON.natureindex],
            currentreportbuttonapi: '',
          },
        ],
      },
    };
    setIsLoading(true);

    NetworkServiceCall('post', buttonapi, jsondata).then(function (response) {
      if (response.httpstatus == 200) {
        setIsLoading(false);
        setPreviewOverlayData({
          array: response?.data?.response?.editArray
            ? response.data.response.editArray
            : [],
        });
        setTimeout(() => {
          setPreviewOverlay(true);
        });
      } else {
        notifyMessage('Preview Failed.', 2);
        setIsLoading(false);
      }
    });
  }

  function getFooterIconsFunctions(val) {
    switch (val.functionid) {
      case 'BACK':
        navigation.goBack();
        break;
      case 'SVS01':
      case 'SVS02':
        props.footerButtonClick(val);
        break;
      case 'SVS03':
        navigation.navigate('PdfPreview', {
          headerblockstyle: {marginBottom: normalize(35)},
          link:
            APIURL +
            'jremr/jrcommonreport/' +
            contextdata.consultationEdit.currentreportbuttonapi,
        });
        break;
      case 'SVS04':
        navigation.navigate('PdfPreview', {
          headerblockstyle: {marginBottom: normalize(35)},
          link:
            APIURL +
            'jremr/jrcommonreport/' +
            contextdata.consultationEdit.previousreportbuttonapi,
        });
        break;
      case 'SVS05':
        getPreviewData(contextdata);
        break;
      case 'SVS06':
        navigation.navigate('CTprOverall');
        break;
      default:
        break;
    }
  }

  function renderItem({item, index}) {
    return (
      <HView
        component={item.componentname}
        data={item.editArray}
        parentClass={item}
        index={index}
        stemplate={stemplate}
      />
    );
  }

  return (
    <View style={{flex: 1}}>
      <View style={{flex: 1}}>
        {isLoading ? <Loader displaytext={true} /> : null}
        {isBNUL(data) ? (
          <FlatList
            data={data}
            removeClippedSubviews={false}
            renderItem={renderItem}
            keyExtractor={(item, index) => 'key' + item.keyid + index}
            listKey={(item, index) => 'key' + item.keyid + index}
          />
        ) : null}

        {previewoverlay &&
        isNU(previewoverlaydata) &&
        isBNUL(previewoverlaydata.array) ? (
          <PdfPreviewOverlay
            overlayheading={'PREVIEW'}
            headerblockstyle={{marginBottom: normalize(35)}}
            data={previewoverlaydata.array}
            closeOverlay={() => {
              setPreviewOverlay(false);
              setPreviewOverlayData();
            }}
            savecallback={() => {}}
          />
        ) : null}
      </View>

      {/* ✅ Footer Section with Back Button */}
      <CFooterView style={{backgroundColor: '#fff'}}>
        <View style={{flexDirection: 'row'}}>
          {[
            {
              displaytext: 'Back',
              size: 10,
              iconname: 'arrow-left',
              iconcolor: Global.AppTheme.primary_color,
              fontcolor: Global.AppTheme.primary_color,
              shadowcolor: '#fff',
              selected: false,
              visibility: true,
              iconsize: 20,
              functionid: 'BACK',
            },
          ].map((item, i) =>
            item.visibility ? (
              <View key={i} style={{paddingLeft: normalize(5)}}>
                <CAwesomeButton
                  data={item}
                  callBack={val =>
                    val == undefined ? null : getFooterIconsFunctions(val)
                  }
                />
              </View>
            ) : null,
          )}
        </View>
      </CFooterView>
    </View>
  );
});

export default CVitalSign;
