import React, { createContext, useState } from 'react';

// Creating a context with default values
const InsureResponseComponentContext = createContext({
    responseJSON: {
        "consultation": [],
        "consultationEdit": {},
    },
    setResponseJSON: () => {},  // Default setter (to be updated by provider)
});

// Creating the provider component
export const InsureResponseComponentProvider = ({ children }) => {
    const [responseJSON, setResponseJSON] = useState({
        "consultation": [],
        "consultationEdit": {},
    });

    return (
        <InsureResponseComponentContext.Provider value={{ responseJSON, setResponseJSON }}>
            {children}
        </InsureResponseComponentContext.Provider>
    );
};

export default InsureResponseComponentContext;
